var e=JSON.parse(`[{"id":"r01","title":"Arztbrief: Aufnahme wegen akuter Pankreatitis","type":"Arztbrief excerpt","text":"Arztbrief vom 12.03.2026\\n\\nPatient: Herr Markus Weber, 52 Jahre alt\\nDiagnose: Akute Pankreatitis bei Choledocholithiasis\\n\\nAufnahmegrund: Seit zwei Tagen progrediente Oberbauchschmerzen mit Ausstrahlung in den Rücken, Übelkeit und Erbrechen. Der Patient berichtet über mässigen Alkoholkonsum. Die Körpertemperatur betrug bei Aufnahme 38,7 Grad Celsius.\\n\\nLaborchemisch zeigte sich eine deutliche Erhöhung der Lipase auf 980 U/l und der Amylase auf 420 U/l. Im Ultraschall wurden mehrere Gallenblasensteine sowie ein erweiterter Ductus choledochus mit einem Durchmesser von 11 mm nachgewiesen.\\n\\nTherapie: Der Patient wurde stationär aufgenommen, zunächst mit Nahrungskarenz, intravenöser Flüssigkeitstherapie und Analgesie mit Novaminsulfon. Eine ERCP mit Papillotomie und Steinextraktion ist für den Folgetag geplant.","questions":["Welche Hauptdiagnose wurde bei Herrn Weber gestellt?","Welche Laborwerte waren deutlich erhöht?","Welches Bildgebungsverfahren wurde eingesetzt?","Welche Massnahme ist für den Folgetag geplant?"],"answers":["Akute Pankreatitis bei Choledocholithiasis","Lipase und Amylase","Ultraschall","Eine ERCP mit Papillotomie und Steinextraktion"],"vocabularyFocus":["Pankreatitis","Choledocholithiasis","Lipase","ERCP","Papillotomie"],"tags":["B2","Arztbrief","Pankreatitis","Gaströnterologie"]},{"id":"r02","title":"Laborbericht: Erhöhte Entzündungswerte","type":"Lab report explanation","text":"Laborbefund vom 15.03.2026\\n\\nPatientin: Frau Ingrid Schubert, 45 Jahre alt\\nAuftrag: Verdacht auf rheumatische Erkrankung\\n\\nErgebnisse:\\n- CRP: 58 mg/l (Norm < 5 mg/l) - deutlich erhöht\\n- BSG 1. Stunde: 45 mm (Norm < 20 mm) - erhöht\\n- Rheumafaktor: 78 IU/ml (Norm < 14 IU/ml) - positiv\\n- Anti-CCP-Antikörper: 42 U/ml (Norm < 7 U/ml) - positiv\\n- ANA: 1:320 (Norm < 1:80) - grenzwertig positiv\\n- Leukozyten: 12.500 / Mikroliter (Norm 4.000-10.000) - leicht erhöht\\n\\nBeurteilung: Die Konstellation aus positivem Rheumafaktor, Anti-CCP-Antikörpern und erhöhten Entzündungsparametern ist hochverdächtig auf eine rheumatoide Arthritis. Eine Überweisung zum Rheumatologen wird empfohlen.","questions":["Welcher Wert ist am stärksten erhöht?","Welcher Antikörper ist positiv und spricht spezifisch für rheumatoide Arthritis?","Welche Überweisung wird empfohlen?","Wie hoch ist der CRP-Wert der Patientin?"],"answers":["CRP mit 58 mg/l (Norm unter 5 mg/l)","Anti-CCP-Antikörper","Überweisung zum Rheumatologen","58 mg/l (Norm unter 5 mg/l)"],"vocabularyFocus":["CRP","BSG","Rheumafaktor","Anti-CCP","rheumatoide Arthritis"],"tags":["B2","Labor","Rheuma","Entzündung"]},{"id":"r03","title":"CT-Befund: Schädel-Hirn-Trauma","type":"Imaging report excerpt","text":"CT-Schädel vom 18.03.2026\\n\\nPatient: Herr Timo Wagner, 34 Jahre alt\\nKlinische Angabe: Zustände nach Fahrradsturz mit Helm, kurzzeitiger Bewusstseinsverlust, Übelkeit\\n\\nTechnik: Natives CT des Schädels, 5 mm Schichtdicke, axiale und koronare Rekonstruktion\\n\\nBefund:\\n- Keine frische Fraktur der Kalotte oder der Schädelbasis nachweisbar\\n- Keine intrakranielle Blutung, kein Hygrom\\n- Hirnstamm und Ventrikelsystem unauffällig\\n- Keine Mittellinienverlagerung\\n- Nasennebenhöhlen und Mastoid lufthaltig\\n\\nBeurteilung: Unauffälliger CT-Befund des Neurokraniums. Kein Nachweis einer frischen Schädel-/Hirnverletzung. Bei persistierenden Beschwerden empfehlen wir eine neurologische Verlaufskontrolle.","questions":["Welches Ereignis führte zur CT-Untersuchung?","Was wurde im CT gefunden?","Welche Strukturen waren unauffällig?","Was wird bei persistierenden Beschwerden empfohlen?"],"answers":["Ein Fahrradsturz mit kurzzeitigem Bewusstseinsverlust","Keine frische Schädel-/Hirnverletzung","Hirnstamm und Ventrikelsystem","Eine neurologische Verlaufskontrolle"],"vocabularyFocus":["Bewusstseinsverlust","Fraktur","intrakranielle Blutung","Kalotte","Mittellinienverlagerung"],"tags":["B2","CT","Neurochirurgie","Trauma"]},{"id":"r04","title":"Packungsbeilage: Ibuprofen 400 mg","type":"Medication leaflet excerpt","text":"GEBRAUCHSINFORMATION: Ibuprofen 400 mg Filmtabletten\\n\\nWirkstoff: Ibuprofen\\nAnwendungsgebiete: Leichte bis mässig starke Schmerzen wie Kopfschmerzen, Zahnschmerzen, Regelschmerzen. Fieber.\\n\\nGegenanzeigen:\\n- Überempfindlichkeit gegen Ibuprofen\\n- Bestehende oder frühere Magen-Darm-Geschwüre\\n- Schwere Leber- oder Nierenfunktionsstörung\\n- Letztes Drittel der Schwangerschaft\\n\\nDosierung:\\n- Erwachsene und Jugendliche ab 12 Jahren: 1 Tablette (400 mg) alle 6-8 Stunden\\n- Tageshöchstdosis: 3 Tabletten (1.200 mg)\\n- Einnahme nach den Mahlzeiten mit reichlich Wasser\\n\\nNebenwirkungen:\\nHäufig: Magen-Darm-Beschwerden, Übelkeit, Sodbrennen\\nGelegentlich: Durchfall, Blähungen\\nSelten: Magengeschwüre, Blutungen, allergische Reaktionen\\n\\nHinweis: Bei gleichzeitiger Einnahme von Blutverdünnern oder Kortison steigt das Risiko für Magenblutungen. Nicht länger als 4 Tage ohne ärztlichen Rat einnehmen.","questions":["Bei welchen Erkrankungen darf Ibuprofen nicht eingenommen werden?","Was ist die Tageshöchstdosis?","Mit welchen Medikamenten steigt das Risiko für Magenblutungen?","Wie lange darf Ibuprofen ohne ärztlichen Rat eingenommen werden?"],"answers":["Bei Magen-Darm-Geschwüren und im letzten Drittel der Schwangerschaft","1.200 mg (3 Tabletten)","Mit Blutverdünnern und Kortison","Nicht länger als 4 Tage"],"vocabularyFocus":["Packungsbeilage","Gegenanzeigen","Tageshöchstdosis","Nebenwirkungen","Wechselwirkungen"],"tags":["B2","Medikament","Ibuprofen","Packungsbeilage"]},{"id":"r05","title":"Klinikrichtlinie: Besuchszeiten und Hygiene","type":"Hospital policy","text":"HAUSORDNUNG UND BESUCHSREGELUNG\\n\\nStand: Januar 2026\\n\\nSehr geehrte Patientinnen und Patienten, liebe Angehörige,\\n\\nUm einen reibungslosen Krankenhausbetrieb zu gewährleisten, bitten wir um Beachtung folgender Regelungen:\\n\\nBesuchszeiten: Täglich von 14:00 bis 18:00 Uhr. Auf der Intensivstation ist der Besuch nach Absprache mit dem Stationspersonal auf eine Person pro Patient und 30 Minuten beschränkt.\\n\\nHygienevorschriften:\\n- Vor Betreten der Station: Händedesinfektion am Eingang\\n- Bei Durchfallerkrankungen oder Erkältungssymptomen: Besuch vermeiden\\n- MRSA-positive Patienten: Schutzkittel und Handschuhe beim Besuch erforderlich\\n- Auf Intensivstation: Mund-Nasen-Schutz Pflicht\\n\\nMitgebrachte Gegenstände:\\nWertsachen, grössere Mengen Bargeld und elektronische Geräte sollten nicht auf dem Zimmer aufbewahrt werden. Das Krankenhaus haftet nicht für Verlust.\\n\\nRauchen: Im gesamten Krankenhaus besteht Rauchverbot.","questions":["Von wann bis wann sind die Besuchszeiten auf der Normalstation?","Was müssen Besucher bei MRSA-positiven Patienten beachten?","Was ist auf der Intensivstation zur Hygiene verpflichtend?","Wofür haftet das Krankenhaus nicht?"],"answers":["Täglich von 14:00 bis 18:00 Uhr","Schutzkittel und Handschuhe sind erforderlich","Mund-Nasen-Schutz","Für Verlust von Wertsachen und Bargeld"],"vocabularyFocus":["Hausordnung","Hygienevorschriften","MRSA","Schutzkittel","Händedesinfektion"],"tags":["B2","Klinik","Hygiene","Besuchsregelung"]},{"id":"r06","title":"Einwilligungserklärung: Koloskopie","type":"Consent form","text":"Einwilligungserklärung für EINE KOLOSKOPIE\\n\\nPatient: _________________ Datum: _________________\\n\\nAufklärender Arzt: Dr. med. Christian Weber\\n\\nIch wurde von Dr. Weber ausführlich über die geplante Untersuchung aufgeklärt und habe die örtliche Aufklärungsbroschüre erhalten. Mir wurde erklärt:\\n\\nZweck der Untersuchung:\\nDie Koloskopie dient der Untersuchung des gesamten Dickdarms mithilfe eines biegsamen Endoskops. Dabei können Schleimhautveränderungen wie Polypen, Entzündungen oder Tumore erkannt und gegebenenfalls sofort entfernt werden.\\n\\nDurchführung:\\nDie Untersuchung findet unter einer kurzen Sedierung statt. Der Patient liegt in Seitenlage. Das Endoskop wird über den After eingeführt und vorsichtig bis zum Blinddarm vorgeschoben.\\n\\nRisiken:\\n- Häufig: Völlgegefühl, leichte Blähungen nach der Untersuchung\\n- Selten: Blutungen nach Polypenentfernung (unter 1 Prozent)\\n- Sehr selten: Darmverletzung (Perforation, unter 0,05 Prozent)\\n- Narkoserisiken: allergische Reaktion, Herz-Kreislauf-Probleme\\n\\nMir ist bekannt, dass ich zur Vorbereitung eine Darmreinigung durchführen muss und die Einnahme von Blutverdünnern vorher mit dem Arzt zu besprechen ist.\\n\\nIch hatte ausreichend Zeit für Fragen und erkläre mich mit der Durchführung einverstanden.","questions":["Welches Organ wird bei einer Koloskopie untersucht?","In welcher Position liegt der Patient während der Untersuchung?","Welches Risiko ist sehr selten und schwerwiegend?","Welche Vorbereitung muss der Patient vor der Koloskopie durchführen?"],"answers":["Der Dickdarm","In Seitenlage","Darmverletzung (Perforation)","Eine Darmreinigung"],"vocabularyFocus":["Koloskopie","Sedierung","Polypen","Perforation","Darmreinigung"],"tags":["B2","Einwilligung","Koloskopie","Gaströnterologie"]},{"id":"r07","title":"Entlassungsbrief: Herzinsuffizienz","type":"Discharge summary","text":"ENTLASSUNGSBRIEF\\n\\nPatient: Frau Gisela Krause, 78 Jahre\\nAufenthalt: 10.04.2026 bis 17.04.2026\\nDiagnose: Dekompensierte chronische Herzinsuffizienz (NYHA III)\\n\\nAnamnese: Die Patientin wurde wegen zunehmender Dyspnö, peripheren Ödemen und Gewichtszunahme von 5 kg in zwei Wochen eingewiesen.\\n\\nDiagnostik: Echokardiografie zeigte eine reduzierte linksventrikuläre Ejektionsfraktion von 35 Prozent. Im EKG Sinusrhythmus, keine Ischämiezeichen.\\n\\nTherapie und Verlauf:\\n- Stossdiurese mit Furosemid i.v., täglich 1.200 mg, über 2 Tage\\n- Umstellung auf Torasemid oral 20 mg täglich\\n- Gewichtsreduktion um 4 kg innerhalb von fünf Tagen\\n- Der Blutdruck ist eingestellt auf 125/80 mmHg\\n\\nMedikation bei Entlassung:\\n- Torasemid 20 mg 1-0-0\\n- Ramipril 5 mg 1-0-0\\n- Bisoprolol 2,5 mg 1-0-0\\n- Rivaroxaban 20 mg 1-0-0\\n\\nEmpfehlungen: Tägliche Gewichtskontrolle, salzarme Kost, körperliche Schonung, Wiedervorstellung beim Kardiologen in vier Wochen.","questions":["Welche EF (Ejektionsfraktion) wurde in der Echokardiografie gemessen?","Welches Medikament wurde zur Stossdiurese verwendet?","Wie viel Gewicht hat die Patientin im Krankenhaus verloren?","Welche Ernährungsempfehlung wurde der Patientin mitgegeben?"],"answers":["35 Prozent","Furosemid","4 kg","Salzarme Kost"],"vocabularyFocus":["Herzinsuffizienz","Ejektionsfraktion","Diurese","Ödeme","Stossdiurese"],"tags":["B2","Entlassung","Kardiologie","Herzinsuffizienz"]},{"id":"r08","title":"Überweisungsschein: Orthopädie","type":"Referral letter","text":"Überweisungsschein / Ärztliche Einweisung\\n\\nZur Vorlage beim: Facharzt für Orthopädie und Unfallchirurgie\\n\\nPatient: Ralf Sommer, 59 Jahre\\nVersichertennummer: A123456789\\n\\nSehr geehrte Kollegin, sehr geehrter Kollege,\\n\\nich überweise Herrn Sommer aufgrund seit Wochen zunehmender belastungsabhängiger Schmerzen im linken Kniegelenk. Der Patient berichtet über ein Knackgeräusch bei Beugung und Streckung. Die körperliche Untersuchung zeigt einen leichten Gelenkerguss und eine schmerzhafte Bewegungseinschränkung.\\n\\nRöntgenaufnahmen des linken Kniegelenks in zwei Ebenen wurden bereits durchgeführt und zeigen eine mediale Gonarthrose Grad II-III. Die konservative Behandlung mit Physiotherapie und NSAR hat nur unzureichend angeschlagen.\\n\\nBitte prüfen Sie die Indikation für eine Kniegelenkspiegelung oder gegebenenfalls die Implantation einer Knie-TEP (Totalendoprothese).\\n\\nMit freundlichen kollegialen Grüssen\\nDr. med. Stefan Lehmann, Hausarzt","questions":["Welche Untersuchung wurde bereits durchgeführt?","Welche Diagnose wurde mittels Röntgen gestellt?","Welche konservative Behandlung hat nicht ausreichend geholfen?","Welche operative Option soll der Orthopäde prüfen?"],"answers":["Röntgenaufnahmen des linken Kniegelenks in zwei Ebenen","Mediale Gonarthrose Grad II-III","Physiotherapie und NSAR","Eine Kniegelenkspiegelung oder Knie-TEP"],"vocabularyFocus":["Überweisung","Gonarthrose","Gelenkerguss","Endoprothese","NSAR"],"tags":["B2","Überweisung","Knie","Orthopädie"]},{"id":"r09","title":"Merkblatt: Vorbereitung zur MRT-Untersuchung","type":"Patient information sheet","text":"INFORMATIONEN ZUR MAGNETRESONANZTOMOGRAFIE (MRT)\\n\\nLiebe Patientin, lieber Patient,\\n\\nSie wurden von Ihrem Arzt zu einer MRT-Untersuchung überwiesen. Bitte beachten Sie folgende Hinweise:\\n\\nVorbereitung:\\n- Sie dürfen vor der Untersuchung normal essen und trinken\\n- Bitte keine Schmuckstücke, Piercings oder Uhren tragen\\n- Entfernen Sie gegebenenfalls Ihr Hörgerät und Ihre Zahnprothese\\n- Tragen Sie beqüme Kleidung ohne Metallteile\\n\\nWährend der Untersuchung:\\n- Sie liegen auf einer beweglichen Liege, die in die Röhre gefahren wird\\n- Die Untersuchung dauert je nach Fragestellung 20 bis 40 Minuten\\n- Es ist sehr laut, Sie erhalten einen Gehörschutz oder Kopfhörer mit Musik\\n- Sie können über eine Sprechanlage jederzeit mit dem Personal kommunizieren\\n\\nKontraindikationen (absolute):\\n- Herzschrittmacher (nicht MRT-kompatibel)\\n- Metallische Fremdkörper im Auge\\n- Cochlea-Implantat (nicht MRT-kompatibel)\\n\\nKontrastmittel: Falls eine Kontrastmittelgabe erforderlich ist, erhalten Sie vor der Untersuchung einen venösen Zugang und werden über mögliche Nebenwirkungen aufgeklärt.","questions":["Darf der Patient vor der MRT-Untersuchung essen?","Wie lange dauert eine MRT-Untersuchung in der Regel?","Welche absolute Kontraindikation wird genannt?","Wozu dient die Sprechanlage während der Untersuchung?"],"answers":["Ja, normales Essen und Trinken ist erlaubt","20 bis 40 Minuten","Herzschrittmacher (nicht MRT-kompatibel)","Zur Kommunikation mit dem Personal"],"vocabularyFocus":["Magnetresonanztomografie","Kontraindikation","Kontrastmittel","Gehörschutz","Sprechanlage"],"tags":["B2","MRT","Patienteninfo","Radiologie"]},{"id":"r10","title":"Krankenkassenmitteilung: AU-Bescheinigung","type":"Insurance/admin document","text":"Techniker Krankenkasse\\nServicecenter, 22305 Hamburg\\n\\nKundennummer: 123456789\\nDatum: 20.04.2026\\n\\nArbeitsunfähigkeitsbescheinigung (AU)\\n\\nSehr geehrte Versicherte, sehr geehrter Versicherter,\\n\\nwir bestätigen den Eingang Ihrer Arbeitsunfähigkeitsbescheinigung.\\n\\nVersicherte Person: Laura Schmidt\\nMitgliedsnummer: 987654321\\n\\nZeitraum der Arbeitsunfähigkeit: 14.04.2026 bis 25.04.2026\\nAusstellende Praxis: Praxis Dr. Schubert, Allgemeinmedizin\\n\\nWichtige Hinweise:\\n1. Ihre AU-Bescheinigung wurde elektronisch an Ihren Arbeitgeber übermittelt.\\n2. Sollte die Arbeitsunfähigkeit über den 25.04.2026 hinaus andaürn, lassen Sie sich bitte vor Ablauf eine Folgebescheinigung ausstellen.\\n3. Das Krankengeld wird ab dem 22.04.2026 gezahlt.\\n4. Bitte reichen Sie die AU spätestens innerhalb einer Woche nach Ausstellung bei Ihrer Krankenkasse ein.","questions":["Wie wird die AU-Bescheinigung an den Arbeitgeber übermittelt?","Ab wann wird das Krankengeld gezahlt?","Bis wann muss die AU bei der Krankenkasse eingereicht werden?","Was muss die Versicherte tun, wenn sie länger krank ist?"],"answers":["Elektronisch","Ab dem 22.04.2026","Spätestens innerhalb einer Woche nach Ausstellung","Eine Folgebescheinigung ausstellen lassen"],"vocabularyFocus":["Arbeitsunfähigkeit","AU-Bescheinigung","Krankengeld","elektronische Übermittlung","Entgeltfortzahlung"],"tags":["B2","Krankenkasse","AU","Versicherung"]},{"id":"r11","title":"Leitlinie: Ambulante Behandlung bei Harnwegsinfekt","type":"Clinical guideline summary","text":"S3-Leitlinie: Unkomplizierte Harnwegsinfektion bei Erwachsenen\\n\\nStand: Dezember 2025 (Auszug)\\n\\nDefinition: Eine unkomplizierte Harnwegsinfektion liegt vor bei ansonsten gesunden, nicht schwangeren Fraün mit typischen Symptomen wie Dysurie, Pollakisurie und suprapubischen Schmerzen.\\n\\nErregerspektrum: In 70-80 Prozent Escherichia coli, gefolgt von Klebsiella pneumoniä, Proteus mirabilis und Staphylococcus saprophyticus.\\n\\nDiagnostik:\\n- Urin-Schnelltest (Nitrit und Leukozytenesterase)\\n- Urinkultur nur bei Versagen der Ersttherapie, Rezidiven oder Schwangeren\\n\\nTherapie der 1. Wahl:\\n- Nitrofurantoin 100 mg retard 3 x täglich für 5 Tage\\n- Alternative: Fosfomycin 3 g als Einmaldosis\\n\\nNicht empfohlen: Cotrimoxazol bei Resistenzlage über 20 Prozent, Fluorchinolone nur noch als Reserveantibiotikum.\\n\\nProphylaxe: Ausreichende Trinkmenge (mindestens 1,5 Liter pro Tag), Blättersamenextrakt, postmenopausale Östriol-Lokaltherapie.","questions":["Welche Bakterienart verursacht die meisten Harnwegsinfektionen?","Welches Antibiotikum wird als erste Wahl empfohlen?","Welche Alternative gibt es als Einmaldosis?","Was wird zur Prophylaxe empfohlen?"],"answers":["Escherichia coli (70-80 Prozent)","Nitrofurantoin","Fosfomycin 3 g als Einmaldosis","Ausreichende Trinkmenge von mindestens 1,5 Litern pro Tag"],"vocabularyFocus":["Harnwegsinfektion","Nitrofurantoin","Fosfomycin","Dysurie","Leitlinie"],"tags":["B2","Leitlinie","Harnwegsinfekt","Urologie"]},{"id":"r12","title":"Notaufnahmeprotokoll: Synkope unklarer Genese","type":"Emergency department note","text":"NOTAUFNAHME - ärztlicher ERSTBERICHT\\n\\nDatum: 22.04.2026, 14:35 Uhr\\n\\nPatient: Hans-Peter Gross, 66 Jahre\\nEintreffart: Mit Rettungswagen\\n\\nVorstellungsgrund: Synkope am Arbeitsplatz ohne Fremdeinwirkung.\\n\\nAnamnese: Der Patient habe plötzliches Schwitzen und Schwarzwerden vor Augen verspürt, dann sei er bewusstlos umgefallen. Ein Kollege fand ihn nach etwa fünf Minuten. Bei Eintreffen des Rettungsdienstes war der Patient wach und orientiert.\\n\\nVorerkrankungen: Arterielle Hypertonie, Diabetes mellitus Typ 2, Z.n. Myokardinfarkt 2021\\nMedikamente: Ramipril 5 mg, Metformin 1000 mg, ASS 100 mg\\n\\nKörperliche Untersuchung:\\n- Blutdruck: 100/60 mmHg (liegend), 85/55 mmHg (stehend) - orthostatische Dysregulation\\n- Puls: 88/min, regelmässig\\n- EKG: Sinusrhythmus, kein ST-Strecken-Infarkt\\n- Neurologie: unauffällig\\n\\nBeurteilung: Synkope bei orthostatischer Dysregulation. Medikamentöse Neüinstellung bei Blutdruckschwankungen erforderlich. Der Patient bleibt auf der internistischen Observationseinheit zur 24-Stunden-Überwachung.","questions":["Was führte zur Synkope des Patienten?","Welcher Blutdruck wurde im Stehen gemessen?","Welche Vorerkrankung hat der Patient?","Wie lange bleibt der Patient zur Überwachung?"],"answers":["Eine orthostatische Dysregulation","85/55 mmHg","Arterielle Hypertonie, Diabetes mellitus Typ 2, Z.n. Myokardinfarkt","24 Stunden auf der internistischen Observationseinheit"],"vocabularyFocus":["Synkope","orthostatische Dysregulation","Observationseinheit","Bewusstlosigkeit","Blutdruckschwankungen"],"tags":["B2","Notaufnahme","Synkope","Kardiologie"]},{"id":"r13","title":"Operationsbericht: Appendektomie laparoskopisch","type":"Operation report excerpt","text":"OPERATIONSBERICHT\\n\\nPatientin: Julia Neumann, 22 Jahre\\nDatum: 25.04.2026\\nOperation: Laparoskopische Appendektomie\\n\\nPräoperative Diagnose: Akute Appendizitis\\nPostoperative Diagnose: Akute phlegmoneuse Appendizitis\\n\\nOperationsverlauf:\\nNach Hautdesinfektion und steriler Abdeckung wurde eine Veress-Nadel infraumbilikal eingebracht und ein Kapnoperitoneum mit 15 mmHg angelegt. Es erfolgte die Einlage einer 10 mm Optik-Trokar-Hülle infraumbilikal. Zwei weitere 5 mm Trokare wurden im rechten Unterbauch und suprapubisch platziert.\\n\\nBei der Inspektion zeigte sich der Appendix vermiformis geschwollen, gerotet und mit Fibrinbelag. Es bestand kein Hinweis auf eine Perforation. Der Appendix wurde mit einem linearen Klammernahrtgerät abgesetzt, über den Trokarkanal in einem Bergebeutel geborgen und entfernt.\\n\\nBlutstillung: Sorgfältig, keine aktive Blutung\\nVerschluss: Faszienverschluss infraumbilikal mit resorbierbaren Einzelknopfnähten, Hautverschluss mit Hautkleber.\\n\\nDauer: 38 Minuten (Schnitt-Naht-Zeit)\\nBlutverlust: minimal (unter 10 ml)\\nKomplikationen: keine","questions":["Welche Diagnose wurde präoperativ gestellt?","Welche OP-Technik wurde verwendet?","Wie wurde der Appendix nach der Entfernung aus der Bauchhöhle transportiert?","In welchem Zustand war der Appendix bei der Inspektion?"],"answers":["Akute Appendizitis","Laparoskopisch","In einem Bergebeutel","Geschwollen, gerotet und mit Fibrinbelag"],"vocabularyFocus":["Appendektomie","laparoskopisch","Kapnoperitoneum","Trokar","Klammernahrtgerät"],"tags":["B2","Operationsbericht","Appendizitis","Chirurgie"]},{"id":"r14","title":"Visitennotiz: Akute Exazerbation COPD","type":"Ward round note","text":"STATIONSVISITE - 26.04.2026\\n\\nPatient: Bernd Hartmann, 72 Jahre, Zimmer 402\\nStation: 4A - Pneumologie\\n\\nAktülle Situation:\\nDer Patient wurde vor 3 Tagen mit akuter Exazerbation einer COPD Gold III bei V.a. bronchopulmonale Infektion aufgenommen. Klinisch war der Patient zuvor zunehmend dyspnoisch, mit produktivem Husten und purulentem Auswurf.\\n\\nHeutiger Status:\\n- Bewusstsein: wach, orientiert\\n- Temperatur: 37,2 Grad (rückläufig, Eintritt 38,6 Grad)\\n- SpO2: 94 Prozent Raumluft (Eintritt 88 Prozent)\\n- Auskultation: beidseits feuchte RG\\n- Blutgasanalyse: paO2 72 mmHg, paCO2 42 mmHg\\n\\nTherapie:\\n- Antibiotika: Amoxicillin/Clavulansäure 875/125 mg 1-1-1\\n- Inhalation: Salbutamol plus Ipratropium 4 x täglich\\n- Prednisolon: 40 mg täglich oral, Ausschleichen geplant\\n- Saürstoff: 2 l/min über Nasenbrille bei Bedarf\\n\\nPlan: Physiotherapie für Atemübungen, Lungenfunktion vor Entlassung, Entlassung geplant in 4-5 Tagen.","questions":["Welche Saürstoffsättigung hatte der Patient bei Aufnahme?","Welches Antibiotikum bekommt der Patient?","Welche Inhalationsmedikamente erhält der Patient täglich?","Welche Therapie wird nach der Entlassung umgestellt?"],"answers":["88 Prozent","Amoxicillin/Clavulansäure","Salbutamol plus Ipratropium 4 x täglich","Von oralem Prednisolon auf inhalatives Kortison"],"vocabularyFocus":["Exazerbation","COPD","purulent","dyspnoisch","Auskultation"],"tags":["B2","Visite","COPD","Pneumologie"]},{"id":"r15","title":"Pflegeübergabe: Dekubitusversorgung","type":"Nursing handover note","text":"Pflichtenübergabe - Frühschicht\\n\\nDatum: 28.04.2026, 06:30 Uhr\\n\\nPatient: Frau Edeltraud König, 84 Jahre, Zimmer 208\\n\\nAktüller Zustand:\\nFrau König ist nach Schenkelhalsfraktur vor 14 Tä gen operiert worden. Die Mobilisation ist langsam, sie sitzt täglich für 30 Minuten im Rollstuhl.\\n\\nDekubitus-Situation:\\n- Ein Dekubitus Grad 2 am Kreuzbein, 3 x 4 cm, Wundrand rot, wenig Exsudat\\n- Versorgung: Täglicher Verband mit Hydrokolloid, Wechsel um 10:00 Uhr\\n- Entlastung: 3-Stunden-Lagerung, spezielle Dekubitusmatratze\\n\\nErnährung:\\n- Trinkmenge: ca. 600 ml pro Tag (zu wenig, bitte an Trinken erinnern)\\n- Kostform: Weiche Kost, vorgegebene Portionen werden nur zur Hälfte gegessen\\n- Gewicht: stabil bei 58 kg\\n\\nAusscheidung:\\n- Stuhlgang: letzte Entleerung vor 2 Tagen, leichte Obstipationsneigung\\n- Massnahme: Macrogol nach Bedarf, gestern gegeben\\n\\nWichtige Termine:\\n- Heute 11:00 Uhr: Physiotherapie\\n- Morgen 09:00 Uhr: Wundkontrolle durch den Arzt\\n- Übermorgen ggf. Entlassungsplanung","questions":["Welchen Dekubitus-Grad hat Frau König am Kreuzbein?","Wie oft wird die Lagerung durchgeführt?","Welches Problem besteht bei der Ernährung?","Welches Abführmittel bekommt die Patientin bei Bedarf?"],"answers":["Dekubitus Grad 2","Alle 3 Stunden","Zu geringe Trinkmenge (ca. 600 ml pro Tag)","Macrogol"],"vocabularyFocus":["Dekubitus","Hydrokolloid","Lagerung","Exsudat","Obstipation"],"tags":["B2","Pflege","Dekubitus","Übergabe"]},{"id":"r16","title":"Reha-Empfehlung: Nach Knie-TEP","type":"Rehabilitation recommendation","text":"REHA-EMPFEHLUNG\\n\\nPatient: Klaus Richter, 67 Jahre\\nDiagnose: Z.n. Implantation einer Knie-Totalendoprothese rechts\\nDatum: 30.04.2026\\n\\nSehr geehrte Reha-Klinik,\\n\\nHerr Richter wurde am 22.04.2026 mit einer Knie-TEP rechts versorgt. Der postoperative Verlauf war komplikationslos. Der Patient ist mobil mit zwei Unterarmgehstützen und hat eine Beugung von 0-0-90 Grad erreicht. Die Wundverhältnisse sind reizlos.\\n\\nIndikation für die Reha:\\nAnschlussheilbehandlung nach Knie-TEP zur Verbesserung der Beweglichkeit, des Muskelaufbaus und der Gangschule.\\n\\nFunktionelle Einschränkungen:\\n- Streckdefizit von 5 Grad\\n- Kraftgrad M4 für Quadrizeps und ischiokrurale Muskulatur\\n- Treppensteigen nur mit Festhalten am Geländer möglich\\n\\nReha-Ziele:\\n1. Steigerung der Beugung auf 0-0-120 Grad\\n2. Vollständige Streckfähigkeit\\n3. Sicheres Treppensteigen ohne Hilfsmittel\\n4. Gangbild ohne Unterarmgehstützen innerhalb von 2 Wochen\\n\\nBelastbarkeit: Vollbelastung des rechten Beines erlaubt.\\nBegleiterkrankungen: Arterielle Hypertonie, gut eingestellt mit Ramipril 5 mg.\\n\\nEmpfohlene Dauer: 3 Wochen stationär.","questions":["Welche Operation hatte Herr Richter?","Welche Beugung hat der Patient aktüll erreicht?","Welches Streckdefizit besteht noch?","Wie lange soll die Reha dauern?"],"answers":["Knie-Totalendoprothese rechts","0-0-90 Grad","5 Grad","3 Wochen stationär"],"vocabularyFocus":["Totalendoprothese","Beugung","Streckdefizit","Gangschule","Anschlussheilbehandlung"],"tags":["B2","Reha","Knie","Orthopädie"]},{"id":"r17","title":"Nachsorgebrief: Hautkrebs-Nachsorge","type":"Follow-up letter","text":"NACHSORGEBRIEF\\n\\nPatient: Helmut Fischer, 55 Jahre\\nDiagnose: Malignes Melanom, linke Schulter, Stadium IB (pT2a, N0, M0)\\nDatum: 02.05.2026\\n\\nSehr geehrter Herr Kollege,\\n\\nwir haben Herrn Fischer heute zur dermatologischen Nachsorge gesehen. Die Erstversorgung des malignen Melanoms an der linken Schulter erfolgte im Januar 2026 mit einer weiten Exzision und Sicherheitsabstand von 2 cm. Die Wundheilung war primär.\\n\\nHeutiger Befund:\\n- Kein Anhalt für Lokalrezidiv (Narbe reizlos, kein tastbarer Knoten)\\n- Keine pathologischen Lymphknoten palpabel (Axilla links und rechts)\\n- Narben- und Hautstatus: sonnenlichtexponierte Areale, mehrere Schädigungsanzeichen\\n\\nEmpfehlungen:\\n1. Nächste Nachsorgeuntersuchung in 3 Monaten\\n2. Täglicher Lichtschutz LSF 50+ auch bei bedecktem Himmel\\n3. Selbstuntersuchung der Haut einmal monatlich\\n4. Keine Sonnenstudios oder intensiver Sonnenbaden, auch nicht im Urlaub\\n5. Sonografiekontrolle der regionären Lymphknoten in 6 Monaten\\n\\nBitte überweisen Sie Herrn Fischer zur nächsten Routine-Kontrolle an unsere Hautklinik.","questions":["Welche Krebsart wurde bei Herrn Fischer diagnostiziert?","Wie gross war der Sicherheitsabstand bei der Exzision?","In welchem Abstand soll die nächste Nachsorge stattfinden?","Welcher Lichtschutzfaktor wird empfohlen?"],"answers":["Malignes Melanom an der linken Schulter","2 cm","In 3 Monaten","LSF 50+ auch bei bedecktem Himmel"],"vocabularyFocus":["Melanom","Exzision","Nachsorge","Lichtschutz","Lokalrezidiv"],"tags":["B2","Nachsorge","Hautkrebs","Dermatologie"]},{"id":"r18","title":"Öffentlicher Aushang: Grippeschutzimpfung","type":"Public health notice","text":"AKTION: GRIPPESCHUTZIMPFUNG 2026\\n\\nGesundheitsamt der Stadt Köln\\nStand: Oktober 2026\\n\\nLiebe Mitbürgerinnen und Mitbürger,\\n\\ndie diesjährige Grippesaison steht bevor. Die Ständige Impfkommission (STIKO) empfiehlt die saisonale Grippeschutzimpfung folgenden Personengruppen:\\n\\n- Personen ab 60 Jahren\\n- Schwangere ab dem 2. Drittel der Schwangerschaft\\n- Personen mit chronischen Grunderkrankungen (Herz-Kreislauf, Atemwege, Nieren, Diabetes)\\n- medizinisches Personal und Pflegekräfte\\n- Bewohner von Alten- und Pflegeheimen\\n\\nDie Impfung ist kostenlos und kann bei Ihrem Hausarzt oder in teilnehmenden Apotheken durchgeführt werden.\\n\\nWichtige Informationen:\\n- Optimaler Impfzeitpunkt: Oktober bis November\\n- Impfschutz beginnt ca. 10 bis 14 Tage nach der Impfung\\n- Die Impfung enthält abgetötete Viren, eine Erkrankung durch die Impfung ist nicht möglich\\n- Nebenwirkungen: lokale Reaktionen an der Einstichstelle, selten leichte Allgemeinsymptome für 1-2 Tage\\n- Bei akuten fieberhaften Infekten wird die Impfung verschoben","questions":["Welche Personengruppe wird als erste genannt?","Wann ist der optimale Impfzeitpunkt?","Wie lange dauert es bis zum Impfschutz?","Kann man durch die Impfung an Grippe erkranken?"],"answers":["Personen ab 60 Jahren","Oktober bis November","Ca. 10 bis 14 Tage","Nein, die Impfung enthält abgetötete Viren"],"vocabularyFocus":["Grippeschutzimpfung","STIKO","Impfschutz","abgetötete Viren","Nebenwirkungen"],"tags":["B2","Öffentlichkeit","Grippe","Impfung"]},{"id":"r19","title":"Terminvorbereitung: Magenspiegelung","type":"Appointment instruction sheet","text":"VORBEREITUNG ZUR MAGENSPIEGELUNG (Ösophagogastroduodenoskopie)\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nIhr Termin zur Magenspiegelung wurde für den 15.05.2026 um 09:00 Uhr vereinbart. Bitte beachten Sie folgende Vorbereitungshinweise:\\n\\nEssen und Trinken:\\n- Am Tag vor der Untersuchung: Leichte Kost zum Mittagessen, ab 18:00 Uhr nichts mehr essen\\n- Am Untersuchungstag: Ab 06:00 Uhr nichts mehr trinken, auch kein Wasser\\n- Kein Kaugummi, keine Bonbons am Untersuchungstag\\n\\nMedikamente:\\n- Blutverdünnende Medikamente (Marcumar, Apixaban, ASS) müssen in Absprache mit dem verschreibenden Arzt abgesetzt werden\\n- Ihre anderen Medikamente dürfen Sie morgens mit einem kleinen Schluck Wasser einnehmen\\n\\nWas Sie mitbringen müssen:\\n- Versichertenkarte und Überweisungsschein\\n- Frühere Befunde, falls vorhanden\\n- Eine Begleitperson (da Sie nach der Untersuchung wegen der Sedierung nicht Auto fahren dürfen)\\n\\nNach der Untersuchung:\\n- Sie bleiben ca. 30 Minuten im Aufwachraum\\n- Sie dürfen bis zum nächsten Tag kein Fahrzeug führen\\n- Sie können normal essen, sobald das Betaubungsspray im Rachen nachgelassen hat","questions":["Bis wann dürfen Sie vor der Magenspiegelung essen?","Was müssen Sie ganz am Untersuchungstag ab 06:00 Uhr vermeiden?","Warum benötigen Sie eine Begleitperson?","Wie lange dürfen Sie nach der Untersuchung kein Fahrzeug führen?"],"answers":["Am Tag vor der Untersuchung ab 18:00 Uhr nichts mehr essen","Nichts mehr trinken, auch kein Wasser","Weil Sie nach der Sedierung nicht Auto fahren dürfen","Bis zum nächsten Tag"],"vocabularyFocus":["Magenspiegelung","Sedierung","Begleitperson","Blutverdünner","Aufwachraum"],"tags":["B2","Termin","Magenspiegelung","Gaströnterologie"]},{"id":"r20","title":"Patientenbeschwerde: Wartezeit in der Praxis","type":"Patient complaint letter","text":"Betreff: Beschwerde über unzumutbare Wartezeit in Ihrer Praxis\\n\\nSehr geehrte Frau Dr. Martin,\\n\\nam 25.04.2026 hatte ich um 14:30 Uhr einen Termin in Ihrer Praxis für eine Routine-Blutdruckkontrolle. Ich war pünktlich und habe an der Anmeldung eingecheckt. Trotz meines gebuchten Termins musste ich insgesamt 2 Stunden und 15 Minuten warten, bis ich aufgerufen wurde.\\n\\nIch möchte darauf hinweisen, dass ich als berufstätiger Patient meine Mittagspause für diesen Termin geopfert habe. Die überlänge Wartezeit hat dazu geführt, dass ich zu spät zurück zur Arbeit kam. Auch habe ich keine Information oder Entschuldigung für die Verzögerung erhalten.\\n\\nIch bin seit über zehn Jahren Patientin in Ihrer Praxis und war bisher zufrieden. Sollte sich an der Terminorganisation nichts ändern, werde ich mich nach einer anderen Praxis umsehen müssen.\\n\\nIch bitte um eine Rückmeldung und eine Verbesserung der Terminorganisation.\\n\\nMit freundlichen Grüssen\\nSabine Werner","questions":["Welche Uhrzeit hatte die Patientin ihren Termin?","Wie lange musste die Patientin warten?","Welche Konseqünz hatte die Wartezeit für die Patientin?","Was droht die Patientin an, falls sich nichts ändert?"],"answers":["14:30 Uhr","2 Stunden und 15 Minuten","Sie kam zu spät zurück zur Arbeit","Sie wird sich nach einer anderen Praxis umsehen"],"vocabularyFocus":["Beschwerde","Wartezeit","Terminorganisation","unzumutbar","Rückmeldung"],"tags":["B2","Beschwerde","Patient","Praxisorganisation"]},{"id":"r21","title":"Arztbrief: Aufnahme bei tiefer Beinvenenthrombose","type":"Arztbrief excerpt","text":"Arztbrief vom 05.05.2026\\n\\nPatient: Frau Daniela Gross, 44 Jahre alt\\nDiagnose: Tiefe Beinvenenthrombose (TVT) des linken Beins\\n\\nAufnahmegrund: Die Patientin stellte sich mit seit drei Tagen zunehmender Schwellung, Schweregefühl und rötlicher Verfärbung des linken Unterschenkels vor. Ein Trauma wurde verneint. Die Patientin ist beruflich als Bürokauffrau tätig mit überwiegend sitzender Tätigkeit. Eine Langstreckenflugreise lag vier Wochen zurück.\\n\\nDiagnostik: Die Duplexsonografie des linken Beins zeigte eine Thrombose der Vena poplitea und der Vena femoralis superficialis. Die D-Dimere waren mit 4,2 mg/l (Norm < 0,5 mg/l) deutlich erhöht.\\n\\nTherapie: Einleitung einer therapeutischen Antikoagulation mit Enoxaparin 1 mg pro kg Körpergewicht zweimal täglich s.c. Überlappende Einstellung auf Phenprocoumon geplant. Kompressionsversorgung Klasse 2 wurde angepasst.","questions":["Welche Diagnose wurde bei Frau Gross gestellt?","Welche Untersuchung bestätigte die Diagnose?","Welcher Laborwert war deutlich erhöht?","Welches Medikament wurde zur Akuttherapie eingesetzt?"],"answers":["Tiefe Beinvenenthrombose des linken Beins","Duplexsonografie","Die D-Dimere mit 4,2 mg/l","Enoxaparin"],"vocabularyFocus":["Thrombose","Duplexsonografie","D-Dimere","Antikoagulation","Enoxaparin"],"tags":["B2","Arztbrief","Thrombose","Gefässmedizin"]},{"id":"r22","title":"Laborbericht: Schilddrüsenwerte bei Überfunktion","type":"Lab report explanation","text":"Laborbefund vom 08.05.2026\\n\\nPatient: Herr Jörg Kaiser, 38 Jahre alt\\nAuftrag: Verdacht auf Schilddrüsenüberfunktion\\n\\nKlinische Angabe: Gewichtsverlust trotz normalen Appetits, Schwitzen, Herzklopfen, Nervosität, Zittern der Hände seit ca. 4 Wochen.\\n\\nErgebnisse:\\n- TSH: < 0,01 mU/l (Norm 0,4 - 4,0 mU/l) - supprimiert\\n- fT3: 8,9 pmol/l (Norm 3,1 - 6,8 pmol/l) - erhöht\\n- fT4: 28,5 pmol/l (Norm 11,0 - 23,0 pmol/l) - erhöht\\n- TPO-Antikörper: 340 IU/ml (Norm < 34 IU/ml) - stark erhöht\\n- TRAK: 12,8 IU/l (Norm < 1,5 IU/l) - deutlich positiv\\n\\nBeurteilung: Es liegt eine manifeste Hyperthyreose vor. Der positive TRAK und die erhöh ten TPO-Antikörper sprechen für einen Morbus Basedow. Eine Schilddrüsensonografie und eine medikamentöse Einstellung mit Thyreostatika werden empfohlen.","questions":["Welcher TSH-Wert wurde gemessen?","Welche Antikörper sind stark erhöht?","Welche Autoimmunerkrankung der Schilddrüse wird vermutet?","Welche Therapie wird empfohlen?"],"answers":["TSH unter 0,01 mU/l (supprimiert)","TPO-Antikörper (340 IU/ml)","Morbus Basedow","Medikamentöse Einstellung mit Thyreostatika"],"vocabularyFocus":["Hyperthyreose","TSH","Morbus Basedow","TRAK","Thyreostatika"],"tags":["B2","Labor","Schilddrüse","Endokrinologie"]},{"id":"r23","title":"Röntgen-Thorax: V.a. Pneumonie","type":"Imaging report excerpt","text":"Röntgen-THORAX IN ZWEI EBENEN\\n\\nPatient: Herr Albert Ziegler, 75 Jahre\\nDatum: 10.05.2026\\nFragestellung: V.a. Pneumonie bei Husten und Fieber seit 4 Tagen\\n\\nTechnik: Röntgen-Thorax pa und seitlich, 125 kV, automatische Belichtung\\n\\nBefund:\\n- Im rechten Unterlappen zeigt sich eine inhomogene, flächige Verschattung mit unscharfer Begrenzung\\n- Der rechte Sinus phrenicocostalis ist leicht ergossen, minimaler Pleurärguss\\n- Das Mediastinum ist mittelständig und nicht verbreitert\\n- Der linke Lungenflügel ist unauffällig belüftet, kein Infiltrat\\n- Das Herz ist altersentsprechend konfiguriert, keine Staungszeichen\\n- Kein Pneumothorax\\n\\nBeurteilung: Infiltrat im rechten Unterlappen, vereinbar mit einer lappenpneumonie. Bei klinischem Verdacht auf Pneumonie Beginn einer kalkulierten Antibiotikatherapie empfohlen.","questions":["In welchem Lungenbereich zeigt sich die Verschattung?","Was zeigt sich im rechten Sinus phrenicocostalis?","Welche Beurteilung wird gegeben?","Welche Therapie wird empfohlen?"],"answers":["Im rechten Unterlappen","Ein minimaler Pleurärguss","Infiltat im rechten Unterlappen, vereinbar mit einer Lappenpneumonie","Kalkulierte Antibiotikatherapie"],"vocabularyFocus":["Pneumonie","Verschattung","Pleurärguss","Infiltrat","Lappenpneumonie"],"tags":["B2","Röntgen","Pneumonie","Radiologie"]},{"id":"r24","title":"Packungsbeilage: Amoxicillin 500 mg","type":"Medication leaflet excerpt","text":"GEBRAUCHSINFORMATION: Amoxicillin 500 mg Hartkapseln\\n\\nWirkstoff: Amoxicillin-Trihydrat\\nAnwendungsgebiete: Amoxicillin ist ein Antibiotikum aus der Gruppe der Aminopenicilline. Es wird angewendet bei bakteriellen Infektionen wie Mittelohrentzündung, Mandelentzündung, Bronchitis, Harnwegsinfektionen und Borreliose.\\n\\nGegenanzeigen:\\n- Allergie gegen Penicillin oder andere Beta-Lactam-Antibiotika\\n- Infektiöse Mononukleose (Pfeiffersches Drüsenfieber)\\n- Schwere Nierenfunktionsstörung (Kreatinin-Clearance unter 30 ml/min)\\n\\nDosierung:\\n- Erwachsene und Jugendliche: 500 mg bis 1000 mg alle 8 Stunden\\n- Tageshöchstdosis: 3.000 mg (6 Kapseln)\\n- Einnahme unabhängig von den Mahlzeiten\\n\\nBesondere Warnhinweise:\\n- Bei Auftreten von schwerem Durchfall während oder nach der Einnahme kann eine pseudomembranöse Kolitis vorliegen\\n- Die gleichzeitige Einnahme von Methotrexat erhöht dessen Toxizität\\n- Antibiotika können die Wirkung der Antibabypille beeinträchtigen\\n- Die Therapie sollte mindestens bis 2 Tage nach Abklingen der Symptome fortgeführt werden","questions":["Gegen welche Allergien darf Amoxicillin nicht eingenommen werden?","Wie hoch ist die Tageshöchstdosis?","Mit welchem Medikament besteht ein erhöhtes Toxizitätsrisiko?","Welche Wirkung kann auf die Antibabypille auftreten?"],"answers":["Allergie gegen Penicillin oder andere Beta-Lactam-Antibiotika","3.000 mg (6 Kapseln)","Methotrexat","Die Wirkung kann beeinträchtigt werden"],"vocabularyFocus":["Amoxicillin","Antibiotikum","Penicillin","pseudomembranöse Kolitis","Toxizität"],"tags":["B2","Medikament","Amoxicillin","Packungsbeilage"]},{"id":"r25","title":"Klinikrichtlinie: Umgang mit Patientenverfügungen","type":"Hospital policy","text":"KLINIKRICHTLINIE: UMGANG MIT Patientenverfügungen UND VORSORGEVOLLMACHTEN\\n\\nStand: Januar 2026\\n\\n1. Geltungsbereich:\\nDiese Richtlinie gilt für alle Stationen und Abteilungen des Klinikums.\\n\\n2. Definitionen:\\nEine Patientenverfügung ist eine schriftliche, verbindliche Willenserklärung eines einwilligungsfähigen Volljährigen für den Fall, dass er selbst nicht mehr einwilligungsfähig ist. Eine Vorsorgevollmacht berechtigt eine Vertraünsperson, medizinische Entscheidungen zu treffen.\\n\\n3. Verfahren bei Aufnahme:\\n- Jeder Patient ist bei Aufnahme nach dem Vorliegen einer Patientenverfügung oder Vorsorgevollmacht zu fragen\\n- Liegt ein Dokument vor, ist eine Kopie in die Patientenakte aufzunehmen\\n- Der aufnehmende Arzt dokumentiert den Inhalt im Aufnahmebogen\\n\\n4. Verfahren bei Entscheidungen:\\n- Bei einwilligungsunfähigen Patienten ist die Patientenverfügung massgeblich\\n- Liegt keine Patientenverfügung vor, muss der Betreür oder Vorsorgebevollmächtigte hinzugezogen werden\\n- Bei lebenserhaltenden Massnahmen ist bei fehlender Verfügung das Betreuungsgericht einzuschalten\\n- Alle Entscheidungen sind im Verlauf zu dokumentieren\\n\\n5. Besonderheiten:\\n- Patientenverfügungen sind nicht befristet und müssen regelmässig im Behandlungsverlauf überprüft werden\\n- Bei Widerspruch zwischen Patientenverfügung und aktüllem Patientenwillen gilt der aktülle Wille","questions":["Wonach muss jeder Patient bei Aufnahme gefragt werden?","Was ist zu tun, wenn ein Dokument vorliegt?","Wer muss bei fehlender Patientenverfügung und lebenserhaltenden Massnahmen eingeschaltet werden?","Was gilt bei Widerspruch zwischen Patientenverfügung und aktüllem Patientenwillen?"],"answers":["Nach dem Vorliegen einer Patientenverfügung oder Vorsorgevollmacht","Eine Kopie ist in die Patientenakte aufzunehmen","Das Betreuungsgericht","Der aktülle Wille des Patienten"],"vocabularyFocus":["Patientenverfügung","Vorsorgevollmacht","Einwilligungsfähigkeit","Betreuungsgericht","Willenserklärung"],"tags":["B2","Klinik","Richtlinie","Patientenverfügung"]},{"id":"r26","title":"Einwilligungserklärung: Leistenbruch-OP","type":"Consent form","text":"Einwilligungserklärung für EINE LAPAROSKOPISCHE LEISTENBRUCH-OP\\n\\nPatient: _________________ Datum: _________________\\n\\nAufklärender Arzt: Dr. med. Anja Vollmer\\n\\nIch wurde über die geplante Operation an einem Leistenbruch aufgeklärt.\\n\\nDiagnose: Leistenhernie rechts\\n\\nOperationsmethode:\\n- Minimalinvasive Operation (TEP - Total extraperitoneale Patch-Plastik)\\n- Drei kleine Hautschnitte (ca. 1 cm), Einführen einer Kamera und Instrumente\\n- Einlegen eines Kunststoffnetzes zur Verstärkung der Bauchwand\\n- Der Eingriff dauert ca. 45 Minuten in Vollnarkose\\n\\nRisiken und Komplikationen:\\n- Häufig: Bluterguss, Schwellung im Leistenbereich (bis 20 Prozent)\\n- Gelegentlich: Taubheitsgefühl in der Leistenregion (5 Prozent)\\n- Selten: Wundinfektion, Nachblutung (unter 1 Prozent)\\n- Sehr selten: Netzinfektion, Verletzung von Samenleiter oder Darm, Rezidiv (2 Prozent)\\n\\nNach der Operation:\\n- Am gleichen Tag Entlassung möglich (ambulante OP)\\n- Kein schweres Heben (über 10 kg) für 4 Wochen\\n- Sportpause für 6 Wochen\\n- Bei Fieber oder starker Schwellung bitte sofort melden","questions":["Welche OP-Methode wird angewendet?","Wie lange dauert der Eingriff in etwa?","Wie hoch ist das Risiko für ein Rezidiv?","Wie lange sollen Sie kein schweres Heben ausüben?"],"answers":["TEP - Total extraperitoneale Patch-Plastik (minimalinvasive)","Ca. 45 Minuten","2 Prozent","4 Wochen"],"vocabularyFocus":["Leistenhernie","TEP","Patch-Plastik","minimalinvasiv","Rezidiv"],"tags":["B2","Einwilligung","Chirurgie","Leistenbruch"]},{"id":"r27","title":"Entlassungsbrief: Schlaganfall","type":"Discharge summary","text":"ENTLASSUNGSBRIEF\\n\\nPatient: Herr Günter Schilling, 70 Jahre\\nAufenthalt: 28.04.2026 bis 12.05.2026\\nDiagnose: Ischämischer Schlaganfall im Bereich der Arteria cerebri media links\\n\\nAnamnese: Der Patient wurde mit akuter Sprachstörung (motorische Aphasie) und rechtseitiger Hemiparese eingeliefert. Die Symptome begannen zwei Stunden vor Aufnahme.\\n\\nDiagnostik und Akuttherapie:\\n- CT-Schadel: Ausgeschlossen Blutung, frühe Ischämiezeichen links\\n- Thrombolyse mit rt-PA 0,9 mg/kg innerhalb von 3 Stunden nach Symptombeginn\\n- MRT am Folgetag: Ischämie im Media-Teilgebiet links\\n\\nVerlauf:\\n- Die motorische Aphasie hat sich deutlich rückgebildet\\n- Die rechtseitige Arm- und Beinparese hat sich auf ein leichtes Residuum (Kraftgrad M4) zurückgebildet\\n- Schluckstörung: initial Sondenkost, jetzt weiche Kost ohne Aspiration möglich\\n\\nMedikation bei Entlassung:\\n- ASS 100 mg 1-0-0\\n- Atorvastatin 40 mg 0-0-1\\n- Ramipril 5 mg 1-0-0\\n\\nEmpfehlungen:\\n- Frühreha (neurologische Reha) für 4 Wochen ab nächster Woche\\n- Logopädie ambulant fortsetzen\\n- Täglich Blutdruckmessen, Zieleinstellung unter 140/90 mmHg\\n- Nächste Kontrolle beim Neurologen in 6 Wochen\\n- Lebensstil: mediterrane Kost, regelmässige Bewegung","questions":["Welcher Schlaganfall-Typ wurde diagnostiziert?","Welche Akuttherapie wurde durchgeführt?","Welche Sprachstörung hatte der Patient initial?","Welches Cholesterin-senkende Medikament wurde verordnet?"],"answers":["Ischämischer Schlaganfall im Bereich der Arteria cerebri media links","Thrombolyse mit rt-PA","Motorische Aphasie","Atorvastatin 40 mg"],"vocabularyFocus":["Schlaganfall","Aphasie","Thrombolyse","Hemiparese","Logopädie"],"tags":["B2","Entlassung","Schlaganfall","Neurologie"]},{"id":"r28","title":"Überweisung: Gaströnterologie bei Morbus Crohn","type":"Referral letter","text":"Überweisung zum Facharzt für Gaströnterologie\\n\\nPatient: Felix Brenner, 28 Jahre\\n\\nSehr geehrte Frau Dr. Naumann,\\n\\nich überweise Herrn Brenner zur weiteren Abklärung und Therapie bei bekanntem Morbus Crohn. Herr Brenner ist seit drei Jahren an Morbus Crohn erkrankt (Ileocolitis). Aktüll klagt er seit vier Wochen über zunehmende Durchfälle (4-6 Mal täglich), krampfartige Unterbauchschmerzen und Gewichtsverlust von 4 kg.\\n\\nAktülle Medikation: Mesalazin 3 g täglich. Calciumschutz wird bereits durchgeführt.\\n\\nKörperliche Untersuchung:\\n- Abdomen: weich, Druckschmerz im rechten Unterbauch, keine Abwehrspannung\\n- BMI: 19,2 (fruher 22,1)\\n- Stuhl: Blutbeimengungen makroskopisch nicht sichtbar, Calprotectin im Stuhl auswärtig mit 480 mg/kg erhöht\\n\\nBisher durchgeführte Diagnostik:\\n- Koloskopie vor 8 Monaten: Aktive Entzündung im terminalen Ileum und Colon ascendens\\n- MRT-Enterografie vor 6 Monaten: Kein Hinweis auf Stenose oder Fistel\\n\\nBitte überprüfen Sie die Notwendigkeit einer Therapieeskalation auf Biologika (Anti-TNF) und planen ggf. eine erneute Koloskopie.\\n\\nMit freundlichem kollegialem Gruss\\nDr. med. Sabine Vogel, Hausärztin","questions":["Welche Form von Morbus Crohn hat der Patient?","Welches Symptom wird im Stuhl gemessen und ist erhöht?","Welche Therapie bekommt der Patient aktüll?","Welche Therapieeskalation soll geprüft werden?"],"answers":["Ileocolitis","Calprotectin (480 mg/kg, erhöht)","Mesalazin 3 g täglich","Biologika (Anti-TNF)"],"vocabularyFocus":["Morbus Crohn","Calprotectin","Mesalazin","Biologika","Therapieeskalation"],"tags":["B2","Überweisung","Morbus Crohn","Gaströnterologie"]},{"id":"r29","title":"Merkblatt: Fasten vor Blutabnahme","type":"Patient information sheet","text":"MERKBLATT: nüchternBlutabnahme\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nfür Ihre bevorstehende Blutabnahme ist es erforderlich, dass Sie nüchtern erscheinen. Bitte beachten Sie folgende Hinweise:\\n\\nWas bedeutet nüchtern?\\n- Sie dürfen 8 bis 12 Stunden vor der Blutabnahme nichts essen\\n- Sie dürfen Wasser trinken (maximal 1 Glas, keine Süssungsmittel)\\n- Kein Kaffee, Tee, Milch, Saft oder Alkohol\\n- Nicht rauchen (Nikotin verfälscht die Werte)\\n\\nWarum ist Nüchternheit wichtig?\\n- Viele Laborwerte verändern sich nach dem Essen (Glukose, Triglyceride, Cholesterin)\\n- Nur im nüchternen Zustand sind die Werte mit den Referenzbereichen vergleichbar\\n- Falsch hohe Werte können zu unnötigen Untersuchungen oder Fehlbehandlungen führen\\n\\nMedikamente:\\n- Ihre täglichen Medikamente dürfen Sie am Morgen mit einem kleinen Schluck Wasser einnehmen\\n- Das gilt nicht, wenn Ihr Arzt etwas anderes angeordnet hat\\n- Bei Diabetikern mit Insulin oder Tabletten: Bitte sprechen Sie vorher mit Ihrem Arzt\\n\\nNach der Blutabnahme:\\n- Sie können sofort wieder normal essen und trinken\\n- Lassen Sie die Druckstelle am Arm für einige Minuten ruhig, um Blürgüsse zu vermeiden","questions":["Wie viele Stunden vor der Blutabnahme sollten Sie nichts essen?","Welches Getränk ist erlaubt?","Welcher Wert verfälscht besonders durch Nikotin?","Wann können Sie normal essen?"],"answers":["8 bis 12 Stunden vor der Blutabnahme","Wasser (maximal 1 Glas)","Die Laborwerte (Nikotin verfälscht die Werte)","Sofort nach der Blutabnahme"],"vocabularyFocus":["nüchtern","Blutabnahme","Referenzbereiche","Triglyceride","Glukose"],"tags":["B2","Patienteninfo","Blutabnahme","Labor"]},{"id":"r30","title":"Krankenkasse: Kostenübernahme Brille","type":"Insurance/admin document","text":"AOK Rheinland/Hamburg\\nServicezentrum, 40212 Düsseldorf\\n\\nBescheid über Kostenübernahme: Sehhilfe\\n\\nVersicherte: Anna Schubert\\nMitgliedsnummer: 123789456\\nDatum: 15.05.2026\\n\\nSehr geehrte Versicherte,\\n\\nwir haben Ihren Antrag auf Kostenübernahme für eine Sehhilfe (Brille) geprüft.\\n\\nErgebnis:\\nDie Kosten werden übernommen, da folgende medizinische Voraussetzungen vorliegen:\\n- Bestehende Fehlsichtigkeit (Myopie und Astigmatismus)\\n- Ärztliche Verordnung durch den Augenarzt liegt vor\\n- Sehstärke: -4,75 dpt rechts, -5,25 dpt links\\n\\nLeistungsumfang:\\n- Festbetrag für das Brillengestell: 40 Euro\\n- Festbetrag für die Gläser: 50 Euro pro Glas\\n- Gesamtfestbetrag: 130 Euro\\n\\nHinweise:\\n1. Der Festbetrag wird direkt mit dem Optiker abgerechnet\\n2. Wahlleistungen (z.B. entspiegelte Gläser, Designer-Gestelle) gehen zu Ihren Lasten\\n3. Bei Mehrkosten erhalten Sie einen Kostenvoranschlag vom Optiker\\n4. Die Kostenübernahme gilt für 2 Jahre\\n5. Bei Änderung der Sehstärke um mehr als 0,5 dpt kann ein neuer Antrag gestellt werden","questions":["Welche Sehstärke hat die Versicherte auf dem linken Auge?","Wie hoch ist der Festbetrag für das Brillengestell?","Wie werden Wahlleistungen wie Designer-Gestelle abgerechnet?","Wie lange gilt die Kostenübernahme?"],"answers":["-5,25 dpt","40 Euro","Sie gehen zu Lasten der Versicherten","2 Jahre"],"vocabularyFocus":["Festbetrag","Sehhilfe","Wahlleistung","Astigmatismus","Kostenvoranschlag"],"tags":["B2","Krankenkasse","Sehhilfe","Versicherung"]},{"id":"r31","title":"Leitlinie: Therapie der Osteoporose","type":"Clinical guideline summary","text":"DVO-Leitlinie 2026: Prophylaxe, Diagnostik und Therapie der Osteoporose (Auszug)\\n\\nDefinition: Osteoporose ist eine systemische Skeletterkrankung mit verminderter Knochenmasse und erhöhtem Frakturrisiko.\\n\\nDiagnostik:\\n- Knochendichtemessung (DXA) an LWS und proximalem Femur\\n- T-Wert unter -2,5 = Osteoporose\\n- T-Wert zwischen -1,0 und -2,5 = Osteopenie\\n\\nTherapie bei bestehender Osteoporose:\\n- Basistherapie: Calcium 1.000 mg/Tag plus Vitamin D 800-1.000 IE/Tag\\n- Medikamentöse Erstlinientherapie: Bisphosphonate (Alendronat 70 mg 1 x/Woche oder Zoledronat 5 mg 1 x/Jahr intravenös)\\n- Zweitlinientherapie: Denosumab 60 mg s.c. alle 6 Monate\\n\\nIndikation für Therapie:\\n- Fraktur nach minimalem Trauma\\n- T-Wert unter -2,5 bei Fraün ab 50 Jahren\\n- T-Wert unter -2,0 bei zusätzlichen Risikofaktoren\\n\\nRisikofaktoren:\\n- Positive Familienanamnese (Mütterlicherseits Hüftfraktur)\\n- Frühzeitige Menopause (vor 45 Jahren)\\n- Langzeittherapie mit Kortison (> 3 Monate)\\n- Nikotin, Übergewicht oder Untergewicht","questions":["Ab welchem T-Wert spricht man von Osteoporose?","Welche Basistherapie wird bei Osteoporose immer empfohlen?","Welches Medikament ist die Erstlinientherapie?","Welcher Risikofaktor ist durch Medikamente bedingt?"],"answers":["T-Wert unter -2,5","Calcium 1.000 mg/Tag plus Vitamin D 800-1.000 IE/Tag","Bisphosphonate (Alendronat)","Langzeittherapie mit Kortison (über 3 Monate)"],"vocabularyFocus":["Osteoporose","DXA","Bisphosphonate","Denosumab","Frakturrisiko"],"tags":["B2","Leitlinie","Osteoporose","Orthopädie"]},{"id":"r32","title":"Notaufnahmeprotokoll: Akuter Harnverhalt","type":"Emergency department note","text":"NOTAUFNAHME - ärztlicher ERSTBERICHT\\n\\nDatum: 16.05.2026, 08:15 Uhr\\n\\nPatient: Wilhelm Krause, 72 Jahre\\nEintreffart: Eigenanreise mit Taxi\\n\\nVorstellungsgrund: Seit heute früh 04:00 Uhr kann der Patient kein Wasser lassen, trotz starkem Harndrang. Letzte Miktion vor 12 Stunden.\\n\\nAnamnese: Der Patient berichtet über seit Monaten zunehmende Miktionbeschwerden mit abgeschwächtem Harnstrahl, Nachttropfen und verstärktem nächtlichem Harndrang (3-4 Mal pro Nacht). Eine Prostatärkrankung ist bekannt, ein PSA-Spiegel von 8,2 ng/ml wurde vor 6 Monaten gemessen. Bisher keine fachspezifische Behandlung.\\n\\nKörperliche Untersuchung:\\n- Abdomen: Gestaute Blase bis zwei Qürfinger unterhalb des Nabels taat- und klopfschmerzhaft\\n- Rectale Untersuchung: Prostata vergössert (ca. 45 ml), glatt begrenzt, kein Knoten tastbar\\n- Temperatur: 36,8 Grad Celsius\\n\\nMassnahmen:\\n- Notfallmässige transurethrale Katheterisierung, Fördermenge: 900 ml klarer Urin\\n- Urinstatus: unauffällig, keine Leukozyten, keine Nitrit\\n- Blutabnahme: Kreatinin 1,4 mg/dl (Norm < 1,2) - leicht erhöht\\n\\nBeurteilung: Akuter Harnverhalt bei Prostatahyperplasie. Der Katheter bleibt für 3 Tage liegen. Überweisung zum Urologen zur weiteren Abklärung und Therapie (gegebenenfalls TURP) veranlasst.","questions":["Wie lange konnte der Patient keinen Urin lassen?","Welche Menge Urin wurde über den Katheter entleert?","Welcher Wert war im Blut leicht erhöht?","Wie lange bleibt der Katheter liegen?"],"answers":["Seit 12 Stunden","900 ml","Kreatinin (1,4 mg/dl)","3 Tage"],"vocabularyFocus":["Harnverhalt","Katheterisierung","Prostatahyperplasie","Miktion","TURP"],"tags":["B2","Notaufnahme","Harnverhalt","Urologie"]},{"id":"r33","title":"Operationsbericht: Hysterektomie","type":"Operation report excerpt","text":"OPERATIONSBERICHT\\n\\nPatientin: Frau Martina Lang, 48 Jahre\\nDatum: 18.05.2026\\nOperation: Totale laparoskopische Hysterektomie mit beidseitiger Adnektomie\\n\\nPräoperative Diagnose: Symptomatisches Uterusmyom mit Hypermenorrhö und Dysmenorrhö. Zudem beidseitige Ovarialzysten.\\nPostoperative Diagnose: s.o.\\n\\nOperationsverlauf:\\nDie Patientin wurde in Allgemeinanakose in Steinschnittlage gelagert. Nach Desinfektion und steriler Abdeckung wurde ein Pneumoperitoneum angelegt. Ein 10 mm Trokar wurde umbilikal und drei 5 mm Trokare wurden supra-/paraumbilikal eingebracht.\\n\\nDie Inspektion zeigte einen vergrösserten Uterus myomatosus mit multiplen intramuralen Myomen bis zu 4 cm Durchmesser. Die Ovarien beidseits zeigten mehrere kleine Zysten. Beide Adnexe waren unauffällig.\\n\\nEs erfolgte die Koagulation und Durchtrennung der Ligg. rotunda, der Tu ben und der Ligg. ovarica. Nach Bläsescheidenpräparation wurden die Aa. uterinä koaguliert und durchtrennt. Die Kolpotomie erfolgte zirkulär. Der Uterus wurde in morzelli erter Form über einen Bergebeutel geborgen. Vaginalverschluss mit Einzelknopfnähten.\\n\\nBlutverlust: ca. 150 ml\\nOperationsdaür: 1 Stunde 55 Minuten\\nKomplikationen: Keine","questions":["Welche Operation wurde durchgeführt?","Welche Symptome verursachte das Uterusmyom?","Wie wurde der Uterus aus der Bauchhöhle entfernt?","Wie hoch war der Blutverlust?"],"answers":["Totale laparoskopische Hysterektomie mit beidseitiger Adnektomie","Hypermenorrhö und Dysmenorrhö","Morzelliert in einem Bergebeutel","Ca. 150 ml"],"vocabularyFocus":["Hysterektomie","Adnektomie","Uterusmyom","morzellieren","Kolpotomie"],"tags":["B2","Operationsbericht","Gynäkologie","Hysterektomie"]},{"id":"r34","title":"Visitennotiz: Pankreatitis-Verlauf","type":"Ward round note","text":"STATIONSVISITE - 20.05.2026\\n\\nPatient: Sebastian Henning, 44 Jahre, Zimmer 311\\nStation: 3B - Gaströnterologie\\n\\nDiagnose: Akute ödematöse Pankreatitis bei Hypertriglyceridämie (Triglyceride bei Aufnahme 3.200 mg/dl)\\n\\nAktüller Status:\\n- Der Patient ist schmerzfrei bei Bedarfsmedikation mit Novaminsulfon (kein Opiat mehr nötig)\\n- Kostaufbau: Seit gestern leichte Schonkost (Reis, Zwieback, Tee) wird vertragen\\n- Temperatur: 37,0 Grad (afebril)\\n- Stuhlgang: regelrecht\\n\\nLabor im Verlauf:\\n- Lipase: 120 U/l (Eintritt 1.450 U/l) - deutlich fallend\\n- CRP: 32 mg/l (Eintritt 180 mg/l) - rückläufig\\n- Triglyceride: 680 mg/dl (Eintritt 3.200 mg/dl) - deutlich gefallen unter Fibrattherapie\\n\\nTherapie:\\n- Tägliche i.v. Flüssigkeit läuft aus, orale Zufuhr ausreichend\\n- Fenofibrat 200 mg 1-0-0 (neu eingestellt)\\n- Omega-3-Fettsäuren 2 g 1-0-1\\n- Nikotinentwöhnung dringend empfohlen\\n\\nPlan:\\n- Entlassung in 2-3 Tagen geplant\\n- Ernährungsberatung fettarme Kost vereinbart\\n- Wiedervorstellung Gaströnterologie in 6 Wochen","questions":["Was war die Ursache der Pankreatitis?","Welcher Laborwert zeigt den stärksten Rückgang?","Welches Medikament wurde neu eingestellt?","Welcher Lebensstilfaktor wurde dringend empfohlen?"],"answers":["Hypertriglyceridämie (Triglyceride 3.200 mg/dl bei Aufnahme)","Lipase von 1.450 auf 120 U/l","Fenofibrat","Nikotinentwöhnung"],"vocabularyFocus":["Pankreatitis","Hypertriglyceridämie","Fibrat","ödematös","Kostaufbau"],"tags":["B2","Visite","Pankreatitis","Gaströnterologie"]},{"id":"r35","title":"Pflegeübergabe: Insulinpflichtiger Diabetiker","type":"Nursing handover note","text":"Pflichtenübergabe - Spätschicht\\n\\nDatum: 21.05.2026, 20:00 Uhr\\n\\nPatient: Friedrich Bender, 65 Jahre, Zimmer 204\\nStation: 2A - Innere Medizin\\n\\nDiagnose: Diabetes mellitus Typ 2, Neüinstellung auf Insulin\\n\\nAktülle Situation:\\nPatient wurde vor 3 Tagen wegen entgleistem Blutzucker (BZ 420 mg/dl bei Aufnahme) stationär aufgenommen. Nach oraler Therapieversagen wurde auf intensivierte Insulintherapie umgestellt.\\n\\nBZ-Verlauf heute:\\n- 06:00 Uhr: 178 mg/dl\\n- 11:00 Uhr: 204 mg/dl (vor Mittagessen)\\n- 17:00 Uhr: 156 mg/dl (vor Abendessen)\\n- 20:30 Uhr: 138 mg/dl\\n\\nInsulintherapie (ICT):\\n- Basalinsulin: Lantus 18 IE um 21:00 Uhr\\n- Mahlzeiteninsulin: Novorapid nach BE-Faktor (1 IE pro 2 BE)\\n\\nBesonderheiten:\\n- Patient hat gestern um 14:00 Uhr eine Hypoglykämie (BZ 52 mg/dl) gehabt, gut auf Traubenzucker angesprochen\\n- Bitte Nachtkontrolle um 02:00 Uhr\\n- Patient wurde in Insulinpens geschult, macht Injektionen selbständig\\n\\nFussstatus:\\n- Fusssohlen: trockene Haut, keine Rhagaden\\n- Zehen: Sensibilität mit Monofilament erhalten\\n- Pulsstatus: Aa. dorsalis pedis beidseits gut tastbar\\n\\nMorgen: Wundberatung wegen alter Narbe am linken Fuss (Z.n. Ulcus)","questions":["Welcher Blutzucker wurde bei der Hypoglykämie gestern gemessen?","Wie viele Einheiten Basalinsulin bekommt der Patient?","Wann wird die nächtliche BZ-Kontrolle durchgeführt?","Welcher Pulsstatus wurde dokumentiert?"],"answers":["52 mg/dl","18 IE Lantus um 21:00 Uhr","Um 02:00 Uhr","Aa. dorsalis pedis beidseits gut tastbar"],"vocabularyFocus":["Insulintherapie","Hypoglykämie","Basalinsulin","Mahlzeiteninsulin","ICT"],"tags":["B2","Pflege","Diabetes","Insulin"]},{"id":"r36","title":"Reha-Empfehlung: Nach Herzinfarkt","type":"Rehabilitation recommendation","text":"REHA-EMPFEHLUNG\\n\\nPatient: Josef Adler, 58 Jahre\\nDiagnose: Z.n. akutem ST-Hebungsinfarkt (STEMI) der Vorderwand\\nDatum: 22.05.2026\\n\\nSehr geehrte Reha-Klinik,\\n\\nHerr Adler erlitt am 08.05.2026 einen akuten Vorderwandinfarkt. Es erfolgte eine notfallmässige PCI der LAD mit Stentimplantation (Drug-eluting Stent). Der Verlauf war komplikationslos.\\n\\nAktüller Zustand:\\n- LVEF: 45 Prozent (leicht eingeschränkt)\\n- Keine Angina pectoris mehr\\n- NYHA II (leichte Dyspnö bei Belastung)\\n- Blutdruck: 125/80 mmHg unter Medikation\\n\\nIndikation für die Reha:\\nAnschlussheilbehandlung nach akutem Myokardinfarkt und PCI.\\n\\nReha-Ziele:\\n1. Steigerung der Belastbarkeit auf 75 Watt im Belastungs-EKG\\n2. Risikofaktor-Management (Raucher, LDL 180 mg/dl)\\n3. Medikamentöse Einstellung optimieren\\n4. Psychokardiologische Betreuung (Angst vor erneutem Infarkt)\\n5. Ernährungsberatung (mediterrane Kost)\\n\\nMedikation:\\n- ASS 100 mg 1-0-0\\n- Ticagrelor 90 mg 1-0-1 (für 12 Monate)\\n- Atorvastatin 80 mg 0-0-1\\n- Metoprolol 50 mg 1-0-0\\n- Ramipril 5 mg 1-0-0\\n\\nEmpfohlene Dauer: 3 Wochen stationär.","questions":["Welche Koronararterie wurde mit einem Stent versorgt?","Welche LVEF hat der Patient aktüll?","Welches Medikament zur Blutplttchenhemmung nimmt der Patient täglich?","Welcher psychologische Aspekt soll in der Reha betreut werden?"],"answers":["LAD (Ramus interventricularis anterior)","45 Prozent","ASS 100 mg und Ticagrelor 90 mg","Angst vor erneutem Infarkt (Psychokardiologie)"],"vocabularyFocus":["Myokardinfarkt","PCI","LVEF","Ticagrelor","Psychokardiologie"],"tags":["B2","Reha","Herzinfarkt","Kardiologie"]},{"id":"r37","title":"Nachsorgebrief: Prostatakarzinom-Nachsorge","type":"Follow-up letter","text":"NACHSORGEBRIEF - UROLOGISCHE PRAXIS DR. OSTERTAG\\n\\nPatient: Erwin Becker, 68 Jahre\\nDiagnose: Adenokarzinom der Prostata pT2c pN0 cM0, Gleason 7 (3+4)\\nTherapie: Laparoskopische radikale Prostatektomie Mai 2025\\n\\nSehr geehrter Herr Kollege,\\n\\nwir haben Herrn Becker heute zur Regelkontrolle gesehen. Die Tumorerkrankung liegt jetzt ein Jahr zurück.\\n\\nAktüller Befund:\\n- Der Patient ist beschwerdefrei, kein lokales Rezidiv tastbar\\n- Kontinenz: tagsüber trocken, nachts Vorlage erforderlich (1-2 Saugvorlagen)\\n- Erektile Funktion: postoperativ nicht erhalten, PDE-5-Hemmer ohne Erfolg, Patient nötig zur Beratung\\n\\nPSA-Verlauf:\\n- 08/2025: 0,03 ng/ml\\n- 12/2025: 0,02 ng/ml\\n- 05/2026: 0,04 ng/ml (stabil)\\n\\nBeurteilung: Der PSA-Wert ist stabil unter 0,1 ng/ml. Somit besteht derzeit kein Anhalt für ein biochemisches Rezidiv.\\n\\nEmpfehlungen:\\n1. Nächste PSA-Kontrolle in 6 Monaten\\n2. Bei PSA-Anstieg > 0,2 ng/ml MRT-Prostata und ggf. Biopsie\\n3. Beckenbodentraining fortsetzen (Kontinenzverbesserung)\\n4. Vorstellung in der Sprechstunde für sexülle Gesundheit zur Beratung\\n\\nMit freundlichen kollegialen Grüssen\\nDr. Bernd Ostertag, Facharzt für Urologie","questions":["Welche Operation wurde ein Jahr zurück durchgeführt?","Welche Nebenwirkung besteht nachts noch?","Welcher PSA-Wert wurde heute gemessen?","Welche Massnahme wird bei einem PSA-Anstieg über 0,2 ng/ml empfohlen?"],"answers":["Laparoskopische radikale Prostatektomie","Nachts ist eine Vorlage erforderlich (1-2 Saugvorlagen)","0,04 ng/ml","MRT-Prostata und ggf. Biopsie"],"vocabularyFocus":["Prostata","PSA","Prostatektomie","Gleason","biochemisches Rezidiv"],"tags":["B2","Nachsorge","Prostata","Urologie"]},{"id":"r38","title":"Aushang: Lebensmittelvergiftung durch Salmonellen","type":"Public health notice","text":"Gesundheitsamt Stuttgart\\nWarnung vor Lebensmittelvergiftungen\\n\\nStand: 20.05.2026\\n\\nAktülle Häufung von Salmonellen-Erkrankungen\\n\\nDas Gesundheitsamt Stuttgart informiert über eine häufung von Salmonellen-bedingten Durchfallerkrankungen im Stadtgebiet. In den letzten zwei Wochen wurden 18 bestätigte Fälle gemeldet. Ermittlungen deuten auf einen Zusammenhang mit dem Verzehr von rohen Eiprodukten hin.\\n\\nSymptome einer Salmonellen-Infektion:\\n- Plötzlich einsetzender Durchfall\\n- Bauchschmerzen und Krämpfe\\n- Übelkeit und Erbrechen\\n- Fieber (38-39 Grad Celsius)\\n- Symptome beginnen 6-72 Stunden nach dem Verzehr kontaminierter Lebensmittel\\n\\nDauer: In der Regel 4-7 Tage.\\n\\nSchutzmassnahmen:\\n1. Eier und Geflügel immer durcherhitzen (mindestens 70 Grad für 10 Minuten)\\n2. Getrennte Schneidebretter für rohes Fleisch und andere Lebensmittel\\n3. Händewaschen nach Kontakt mit rohem Fleisch und Eiern\\n4. Kühlkette nicht unterbrechen (maximal 7 Grad für Eier)\\n5. Bei Durchfallerkrankungen: keine Speisenzubereitung für andere\\n\\nBesonders gefährdete Personengruppen:\\n- Kleinkinder unter 5 Jahren\\n- Menschen über 70 Jahre\\n- Immunsupprimierte Patienten\\n- Schwangere\\n\\nBei schwerem Verlauf oder Blut im Stuhl: Ärztliche Vorstellung anraten.","questions":["Wie viele bestätigte Salmonellen-Fälle wurden in den letzten zwei Wochen gemeldet?","Nach welcher Zeit treten die ersten Symptome auf?","Welche Temperatur ist für das Durcherhitzen von Lebensmitteln empfohlen?","Welche Personengruppe ist nicht unter den besonders gefährdeten genannt?"],"answers":["18 bestätigte Fälle","6-72 Stunden nach dem Verzehr","Mindestens 70 Grad für 10 Minuten","Jugendliche (Kleinkinder unter 5, Menschen über 70, Immunsupprimierte, Schwangere)"],"vocabularyFocus":["Salmonellen","Lebensmittelvergiftung","Durchfallerkrankung","kontaminieren","Kühlkette"],"tags":["B2","Öffentlichkeit","Salmonellen","Hygiene"]},{"id":"r39","title":"Vorbereitung: Schlafapnö-Untersuchung","type":"Appointment instruction sheet","text":"VORBEREITUNG ZUR POLYSOMNOGRAFIE (SCHLAF-LABOR)\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nIhr Termin im Schlaflabor wurde für den 25.05.2026 um 20:00 Uhr vereinbart. Sie werden eine Nacht bei uns verbringen. Bitte folgende Hinweise beachten:\\n\\nMitbringen:\\n- Ihren Pyjama oder Nachthemd (beqüm, nicht zu warm)\\n- Ihre eigenen Toilettenartikel (Zahnbürste, etc.)\\n- Täglich benötigte Medikamente\\n- Ein Buch oder etwas zur Beschäftigung vor dem Einschlafen\\n- Falls vorhanden: Ihr eigenes Kopfkissen\\n\\nNicht mitbringen:\\n- Keine Wertsachen\\n- Kein Alkohol oder koffeinhaltige Getränke am Untersuchungstag\\n\\nVorbereitung am Untersuchungstag:\\n- Kein Mittagsschlaf\\n- Normal frühstücken und zu Mittag essen\\n- Ab 14:00 Uhr kein Koffein mehr (Kaffee, schwarzer Tee, Cola, Energydrinks)\\n- Kein Alkohol am gesamten Tag\\n- Am frühen Abend duschen, aber keine Körperlotion oder Creme auftreten\\n\\nAblauf:\\n- Ankunft um 20:00 Uhr auf Station 4B (Pneumologie)\\n- Eine Schlafmedizinerin erklärt Ihnen den Ablauf und bringt die Sensoren an\\n- Sie schlafen in einem Einzelzimmer mit Video- und Audioüberwachung\\n- Die Messung endet morgens gegen 06:30 Uhr\\n- Sie erhalten ein Frühstück\\n- Erste Ergebnisse erhalten Sie voraussichtlich beim Kontrolltermin in 4 Wochen","questions":["Wann müssen Sie im Schlaflabor ankommen?","Welches Getränk ist ab 14:00 Uhr nicht mehr erlaubt?","Was dürfen Sie am frühen Abend vor der Untersuchung nicht auftragen?","Wann endet die Messung?"],"answers":["Um 20:00 Uhr","Koffeinhaltige Getränke (Kaffee, Tee, Cola, Energydrinks)","Keine Körperlotion oder Creme","Morgens gegen 06:30 Uhr"],"vocabularyFocus":["Polysomnografie","Schlaflabor","koffeinhaltig","Sensor","Videöberwachung"],"tags":["B2","Termin","Schlafapnö","Pneumologie"]},{"id":"r40","title":"Patientenbeschwerde: Falsche Medikamention","type":"Patient complaint letter","text":"Betreff: Beschwerde über Medikationsfehler bei stationärem Aufenthalt\\n\\nSehr geehrte Klinikleitung,\\n\\nmein Vater, Herr Werner Lukas (82 Jahre), war vom 05.05. bis 12.05.2026 auf Ihrer Station 3D (Geriatrie) wegen einer Harnwegsinfektion. Wir möchten einen Vorfall melden.\\n\\nAm 08.05.2026 stellten wir fest, dass mein Vater statt seines regelmässigen Blutdruckmittels Ramipril 5 mg ein anderes Medikament (Enalapril) bekam. Als wir die Pflegekraft darauf ansprachen, wurde die Medikation erst nach einer Stunde korrigiert. Die Pflegekraft sagte, es sei durch einen Vertretungsarzt so verordnet worden.\\n\\nZwar hatte mein Vater keine gesundheitlichen Schäden davongetragen, doch zeigt dieser Vorfall eine mangelhafte Überprüfung der Medikation bei stationärer Aufnahme. Mein Vater hat eine umfangreiche Medikamentenliste, die wir bei Aufnahme abgegeben haben. Offenbar wurde diese nicht korrekt in den Systemen erfasst.\\n\\nWir erwarten:\\n1. Eine Stellungnahme zum Vorfall\\n2. Eine schriftliche Zusicherung, dass die Arzneimitteltherapiesicherheit auf Ihrer Station verbessert wird\\n3. Die Überprüfung der Patientenaufnahme-Prozesse\\n\\nSollte keine zufriedenstellende Antwort erfolgen, werden wir uns an die Patientenberatungsstelle wenden.\\n\\nMit freundlichen Grüssen\\nKarsten Lukas","questions":["Welches falsche Medikament wurde dem Vater verabreicht?","Wann fiel der Fehler auf?","Wie lange dauerte die Korrektur des Fehlers?","Was fordert der Beschwerdeführer als dritten Punkt?"],"answers":["Enalapril statt Ramipril","Am 08.05.2026","Eine Stunde","Die Überprüfung der Patientenaufnahme-Prozesse"],"vocabularyFocus":["Medikationsfehler","Arzneimitteltherapiesicherheit","Verordnung","Beschwerde","Stellungnahme"],"tags":["B2","Beschwerde","Medikation","Patientensicherheit"]},{"id":"r41","title":"Arztbrief: Nephrotisches Syndrom","type":"Arztbrief excerpt","text":"Arztbrief vom 25.05.2026\\n\\nPatient: Familie: Herr Timo Frühauf, 34 Jahre alt\\nDiagnose: Nephrotisches Syndrom bei minimal-change-Glomerulonephritis\\n\\nAufnahmegrund: Der Patient wurde wegen generalisierter Ödeme, Gewichtszunahme von 6 kg in 2 Wochen und schäumendem Urin eingewiesen.\\n\\nDiagnostik:\\n- Urinstatus: Proteinurie 8,2 g/24h (Norm < 0,15 g) - massiv\\n- Serumalbumin: 1,8 g/dl (Norm 3,5-5,0 g/dl) - stark erniedrigt\\n- Kreatinin: 1,0 mg/dl - normwertig\\n- Nierenbiopsie: Minimal-change-Glomerulonephritis\\n\\nTherapie:\\n- Prednisolon 60 mg täglich als Stosstherapie\\n- Furosemid 40 mg i.v. bei Ödemen\\n- Gewichtsreduktion um 4 kg unter Diurese\\n- Salzbeschränkung auf 3 g/Tag\\n\\nPrognose: Bei minimal-change-Glomerulonephritis ist die Prognose unter Steroidtherapie gut. Ein Rückfall ist in bis zu 30 Prozent der Fälle möglich.","questions":["Welche Nierenerkrankung wurde diagnostiziert?","Wie hoch war die Proteinurie der Patientin?","Welches Medikament wurde als Stosstherapie eingesetzt?","Wie hoch ist die Rückfallwahrscheinlichkeit?"],"answers":["Nephrotisches Syndrom bei minimal-change-Glomerulonephritis","8,2 g/24h (Norm unter 0,15 g)","Prednisolon 60 mg täglich","Bis zu 30 Prozent"],"vocabularyFocus":["Nephrotisches Syndrom","Glomerulonephritis","Proteinurie","Serumalbumin","Nierenbiopsie"],"tags":["B2","Arztbrief","Niere","Nephrologie"]},{"id":"r42","title":"Laborbericht: Eisenmangelanämie","type":"Lab report explanation","text":"Laborbefund vom 27.05.2026\\n\\nPatientin: Frau Lina Stoll, 32 Jahre\\nAuftrag: Anämie-Abklärung bei Müdigkeit, Blasse, Konzentrationsschwäche\\n\\nErgebnisse:\\n- Hb: 9,2 g/dl (Norm 12,0-15,5 g/dl) - deutlich erniedrigt\\n- MCV: 72 fl (Norm 80-98 fl) - mikrozytär\\n- MCH: 24 pg (Norm 27-34 pg) - hypochrom\\n- Ferritin: 8 ng/ml (Norm 30-150 ng/ml) - stark erniedrigt\\n- Transferrin: 420 mg/dl (Norm 200-360 mg/dl) - erhöht\\n- Transferrinsättigung: 8 Prozent (Norm 16-45 Prozent) - erniedrigt\\n- CRP: normal\\n\\nBeurteilung: Mikrozytäre hypochrome Anämie bei schwerem Eisenmangel. Die Ursache sollte gynäkologisch abgeklärt werden (Hinweis auf Hypermenorrhö in der Anamnese). Thearapie: orales Eisen (Ferrosanol 100 mg 1-1-0), Vitamin C zur Resorptionsverbesserung. Kontrolle in 4 Wochen.","questions":["Welcher Hb-Wert wurde gemessen?","Welcher Eisenwert war stark erniedrigt?","Welche Ursache wird vermutet?","Welche Kombination wird zur Einnahme empfohlen?"],"answers":["9,2 g/dl (deutlich erniedrigt)","Ferritin mit 8 ng/ml","Gynäkologische Ursache (Hypermenorrhö)","Orales Eisen (Ferrosanol) plus Vitamin C"],"vocabularyFocus":["Anämie","Ferritin","mikrozytär","hypochrom","Resorptionsverbesserung"],"tags":["B2","Labor","Eisenmangel","Anämie"]},{"id":"r43","title":"MRT-Wirbelsäule: Bandscheibenvorfall","type":"Imaging report excerpt","text":"MRT DER Lendenwirbelsäule (LWS)\\n\\nPatient: Karl-Heinz Gross, 55 Jahre\\nDatum: 29.05.2026\\nFragestellung: Seit 6 Wochen bestehende Lumboischialgie links mit Ausstrahlung in den linken Fuss\\n\\nTechnik: T1- und T2-gewichtete Seqünzen in sagittaler und axialer Schichtung, STIR-Seqünz\\n\\nBefund:\\n- Regelrechte Lordose der LWS\\n- Keine Fehlstellung oder ossäre Läsion\\n- Bandscheibenvorfall (Protrusion und Extrusion) auf Höhe L4/L5 mitseqüstiertem Anteil nach links-lateral\\n- Der Vorfall führt zu einer Einengung des linken Recessus lateralis und einer Kompression der abgehenden Nervenwurzel L5\\n- Keine Spinalkanalstenose\\n- Bandscheibe L5/S1 mit leichter Höhenminderung, aber ohne Prolaps\\n- Facettengelenke altersentsprechend\\n- Kein Ödem in den Wirbelkörpern\\n\\nBeurteilung: Grosser seqüstrierter Bandscheibenvorfall L4/L5 links mit Nerverwurzelkompression L5. Bei ausbleibender Besserung unter konservativer Therapie ist eine operative Versorgung (mikrochirurgische Seqüstrektomie) indiziert.","questions":["Auf welcher Höhe befindet sich der Bandscheibenvorfall?","Welche Nervenwurzel wird komprimiert?","Welche konservative Therapie sollte vor OP versucht werden?","Welche Operation wird bei ausbleibender Besserung empfohlen?"],"answers":["L4/L5 mit seqüstrier tem Anteil nach links-lateral","Die abgehende Nervenwurzel L5","Konservative Therapie (nicht näher im Text benannt)","Mikrochirurgische Seqüstrektomie"],"vocabularyFocus":["Lumboischialgie","Bandscheibenvorfall","Seqüster","Nervenwurzelkompression","Seqüstrektomie"],"tags":["B2","MRT","Wirbelsäule","Orthopädie"]},{"id":"r44","title":"Packungsbeilage: Metformin 1000 mg","type":"Medication leaflet excerpt","text":"GEBRAUCHSINFORMATION: Metformin 1000 mg Filmtabletten\\n\\nWirkstoff: Metforminhydrochlorid\\nAnwendungsgebiete: Behandlung des Diabetes mellitus Typ 2, insbesondere bei Übergewicht, wenn durch Diä t und Bewegung allein keine ausreichende Blutzuckerkontrolle erreicht wird.\\n\\nGegenanzeigen:\\n- Überempfindlichkeit gegen Metformin\\n- Schwere Nierenfunktionsstörung (GFR unter 30 ml/min)\\n- Akute oder chronische Stoffwechselazidose\\n- Akute Erkrankungen mit Risiko einer Nierenfunktionsstörung (Dehydratation, schwere Infektion, Schock)\\n- Leberinsuffizienz\\n\\nDosierung:\\n- Einschleichend: 1/2 Tablette 1-2 mal täglich\\n- Erhaltungsdosis: 1 Tablette (1000 mg) 1-2 mal täglich zu den Mahlzeiten\\n- Maximal: 3000 mg pro Tag\\n\\nBesondere Warnhinweise:\\n- Laktatazidose: sehr selten (0,03 Fälle/1000 Patientenjahre), aber lebensbedrohlich\\n- Bei Kontrastmitteluntersuchungen Metformin 48 Stunden vorher absetzen\\n- Alkohol kann das Risiko einer Laktatazidose erhöhen\\n- Vitamin-B12-Mangel bei Langzeiteinnahme: regelmässige Kontrolle empfohlen","questions":["Wann darf Metformin nicht eingenommen werden?","Wie hoch ist die maximale Tagesdosis?","Welche sehr seltene, aber lebensbedrohliche Nebenwirkung kann auftreten?","Wann sollte Metformin vor einer Kontrastmitteluntersuchung abgesetzt werden?"],"answers":["Bei schwerer Nierenfunktionsstörung (GFR unter 30 ml/min)","3.000 mg pro Tag","Laktatazidose","48 Stunden vorher"],"vocabularyFocus":["Metformin","Laktatazidose","Nierenfunktion","Kontrastmittel","Vitamin-B12-Mangel"],"tags":["B2","Medikament","Metformin","Diabetes"]},{"id":"r45","title":"Klinikrichtlinie: Patientenverfügung und Wiederbelebung","type":"Hospital policy","text":"KLINIKRICHTLINIE: DO-NOT-RESUSCITATE-(DNR)-Verfügungen\\n\\nStand: März 2026\\n\\n1. Grundsatz:\\nJeder Patient hat das Recht, lebensverlängernde Massnahmen abzulehnen, auch wenn dies seinen Tod zur Folge hat.\\n\\n2. Voraussetzungen für eine DNR-Verfügung:\\n- Schriftliche Anordnung des behandelnden Arztes nach Gespräch mit Patient oder Betreür\\n- Die Verfügung muss von mindestens zwei Ärzten unterschrieben werden (Oberarztpflicht)\\n- Die DNR-Verfügung wird täglich auf Aktualität geprüft\\n\\n3. Umsetzung:\\n- Bei Kreislaufstillstand: keine Herzdruckmassage, keine Defibrillation, keine Intubation\\n- Die medikamentöse Therapie wird fortgesetzt (keine aktive Sterbehilfe)\\n- Palliativmassnahmen stehen im Vordergrund\\n\\n4. Ausnahmen:\\n- Bei akuten, reversiblen Ereignissen (z.B. Fremdkörperaspiration) kann reanimiert werden, wenn die DNR nicht explizit alle Massnahmen untersagt\\n- DNR gilt nicht automatisch für operative Eingriffe - hier muss individüll entschieden werden\\n\\n5. Dokumentation:\\n- Die Verfügung wird im KIS (Krankenhausinformationssystem) für alle Behandelnden sichtbar erfasst\\n- Der Aufbewahrungsort der schriftlichen Verfügung wird dokumentiert\\n- Der Patient erhält eine Kopie der Verfügung","questions":["Wie viele Ärzte müssen eine DNR-Verfügung unterschreiben?","Was umfasst die DNR-Anordnung im Kreislaufstillstand?","Gilt eine DNR automatisch für operative Eingriffe?","Wo wird die DNR-Verfügung für alle Behandelnden sichtbar erfasst?"],"answers":["Mindestens zwei Ärzte (Oberarztpflicht)","Keine Herzdruckmassage, keine Defibrillation, keine Intubation","Nein, das muss individüll entschieden werden","Im Krankenhausinformationssystem (KIS)"],"vocabularyFocus":["DNR","Wiederbelebung","Reanimation","Palliativmassnahmen","KIS"],"tags":["B2","Klinik","Richtlinie","Palliativmedizin"]},{"id":"r46","title":"Einwilligung: Katarakt-OP","type":"Consent form","text":"Einwilligungserklärung für EINE KATARAKT-OPERATION\\n\\nPatient: _________________ Datum: _________________\\n\\nAufklärender Arzt: Dr. med. Anja Meissner (Fachärztin für Augenheilkunde)\\n\\nDiagnose: Katarakt (grauer Star) am rechten Auge\\n\\nGeplanter Eingriff: Phakömulsifikation mit Implantation einer Intraokularlinse\\n\\nOperationsmethode:\\n- Der Eingriff erfolgt in örtlicher Betaubung (Tropfen und Gel) bei wachem Patienten\\n- Über einen kleinen Schnitt (ca. 2,2 mm) am Hornhautrand wird die getrübte Linse mittels Ultraschall zerstört und abgesaugt\\n- Eine Kunstlinse wird an derselben Stelle eingesetzt\\n- Dauer: ca. 15-20 Minuten\\n\\nRisiken und Komplikationen:\\n- Häufig: Trockene Augen, leichte Entzündung (10-20 Prozent)\\n- Gelegentlich: Hinterkapseltribung (Nachstar, 5-10 Prozent)\\n- Selten: Netzhautablösung (0,2 Prozent), Endophthalmitis (0,05 Prozent)\\n- Sehr selten: Linsenluxation, Glaukom, Makulaödem\\n\\nNach der OP:\\n- Augentropfen (Antibiotikum + Entzündungshemmer) für 4 Wochen\\n- Kein schweres Heben, kein Sport für 2 Wochen\\n- Augenschild nachts für 1 Woche\\n- Nachkontrollen: 1 Tag, 1 Woche, 1 Monat nach OP\\n- Neue Brille nach ca. 4-6 Wochen","questions":["Welche Methode wird zur Entfernung der getrübten Linse verwendet?","Welche Narkoseart wird angewendet?","Welches Risiko tritt gelegentlich auf?","Wie lange müssen Augentropfen angewendet werden?"],"answers":["Phakömulsifikation (Ultraschall-Zertrümmerung)","Örtliche Betaubung (Tropfen und Gel) bei wachem Patienten","Hinterkapseltribung (Nachstar, 5-10 Prozent)","4 Wochen"],"vocabularyFocus":["Katarakt","Phakömulsifikation","Intraokularlinse","Nachstar","Endophthalmitis"],"tags":["B2","Einwilligung","Augenheilkunde","Katarakt"]},{"id":"r47","title":"Entlassungsbrief: Tiefe Beinvenenthrombose","type":"Discharge summary","text":"ENTLASSUNGSBRIEF\\n\\nPatient: Herr Boris Wieland, 52 Jahre\\nAufenthalt: 22.05.2026 bis 30.05.2026\\nDiagnose: Tiefe Beinvenenthrombose (TVT) rechts bei Thrombophilie\\n\\nAnamnese: Der Patient wurde mit geschwollenem, druckschmerzhaften rechten Unterschenkel nach Langstreckenflug eingeliefert. Als Ursache fand sich eine heterozygote Faktor-V-Leiden-Mutation.\\n\\nTherapie und Verlauf:\\n- Initial: Enoxaparin s.c. in therapeutischer Dosierung über 5 Tage\\n- Überlappung auf Phenprocoumon ab Tag 2\\n- INR am Entlasstag: 2,4 (im therapeutischen Bereich)\\n- Kompressionsversorgung Klasse 2 wurde angepasst und gut vertragen\\n- Abschwellung des Beines um 4 cm Umfang\\n\\nMedikation bei Entlassung:\\n- Phenprocoumon nach INR-Schema (aktüll 3 mg täglich)\\n- INR-Kontrollen zunächst alle 1-2 Wochen\\n\\nEmpfehlungen:\\n- Kompressionsströmpfe tagsüber für mindestens 6 Monate tragen\\n- Antikoagulation für mindestens 3 Monate, Verlängerung nach Risikoprofil\\n- Bei ungeplanter OP oder Zahnbehandlung: Bridging mit Heparin erforderlich\\n- Familienmitglieder sollten auf Thrombophilie getestet werden\\n- Bewegung (Gehen) ist empfohlen, Staubecken vermeiden","questions":["Welche Gerinnungsstörung wurde als Ursache gefunden?","Welcher INR-Wert wurde bei Entlassung gemessen?","Wie lange müssen Kompressionsströmpfe getragen werden?","Wie lange soll die Antikoagulation mindestens dauern?"],"answers":["Heterozygote Faktor-V-Leiden-Mutation","2,4 (im therapeutischen Bereich)","Mindestens 6 Monate","Mindestens 3 Monate"],"vocabularyFocus":["Thrombophilie","Faktor-V-Leiden","INR","Phenprocoumon","Bridging"],"tags":["B2","Entlassung","Thrombose","Gerinnung"]},{"id":"r48","title":"Überweisung: Dermatologie bei Ekzem","type":"Referral letter","text":"Überweisung an den Facharzt für Dermatologie\\n\\nPatient: Leonie Wahl, 17 Jahre\\n\\nSehr geehrte Frau Dr. Mohr,\\n\\nich überweise die Patientin Leonie Wahl zur dermatologischen Abklärung. Seit ca. 8 Wochen besteht ein nässendes, juckendes Ekzem an beiden Händen und Unterarmen. Die Erstbehandlung mit einer kortisonhaltigen Salbe (Prednicarbat) hat nur kurzfristig geholfen. Zusätzlich klagt die Patientin über juckende Knoten am Rücken.\\n\\nAnamnese:\\n- Keine bekannten Allergien\\n- Kein bekanntes Asthma oder Heuschnupfen\\n- Familienanamnese: Mutter mit Neurodermitis\\n- Die Patientin arbeitet im Friseursalon (täglicher Kontakt zu Chemikalien)\\n\\nKörperliche Untersuchung:\\n- An beiden Händen: Erythem, Schuppung, minimale Blasenbildung an den Fingern\\n- Keine Nagelveränderungen\\n- Am Rücken: mehrere urtikarielle Plaqüs\\n\\nBitte führen Sie einen Epikutantest (Patchtest) auf Friseurstoffe und Duftstoffe durch.\\n\\nMit freundlichem kollegialem Gruss\\nDr. med. Klaus Fischer, Hausarzt","questions":["Wie lange besteht das Ekzem bereits?","Welche Behandlung hat nicht ausreichend geholfen?","Welcher Berufsallergen-Kontakt wird vermutet?","Welcher Test soll durchgeführt werden?"],"answers":["Seit ca. 8 Wochen","Kortisonhaltige Salbe (Prednicarbat)","Chemikalien im Friseursalon","Epikutantest (Patchtest) auf Friseurstoffe und Duftstoffe"],"vocabularyFocus":["Ekzem","Epikutantest","Neurodermitis","Prednicarbat","urkarielle Plaqüs"],"tags":["B2","Überweisung","Dermatologie","Allergie"]},{"id":"r49","title":"Merkblatt: Gehörschutz am Arbeitsplatz","type":"Patient information sheet","text":"MERKBLATT: Gehörschutz AM ARBEITSPLATZ\\n\\nLiebe Mitarbeiterin, lieber Mitarbeiter,\\n\\nbei Ihrem arbeitsmedizinischen Vorsorgetermin wurde eine beginnende Lärmschwerhörigkeit festgestellt. Bitte beachten Sie die folgenden Hinweise zum Schutz Ihres Gehörs:\\n\\nLärm am Arbeitsplatz:\\n- Ab einem Lärmpegel von 85 dB(A) muss der Arbeitgeber Gehörschutz zur Verfügung stellen\\n- Ab 90 dB(A) ist das Tragen von Gehörschutz Pflicht\\n- Typische laute Bereiche im Krankenhaus: Technikräume, Sterilisation, OP-Bereich\\n\\nRichtiger Gehörschutz:\\n- Gehörschutzstöpsel müssen richtig eingesetzt werden (Ohrkanal vor dem Einsetzen gerade ziehen)\\n- Kapselgehörschützer bieten den besten Schutz, sind aber weniger hygienisch über längere Zeit\\n- Die Dämpfung muss auf den Lärmpegel abgestimmt sein\\n\\nWichtige Warnsignale:\\n- Sie müssen nach der Arbeit lauter sprechen oder hören Fernseher lauter\\n- Sie haben ein Piepen oder Rauschen im Ohr (Tinnitus)\\n- Sie verstehen Sprache in lauter Umgebung schlechter\\n\\nBeim Auftreten dieser Symptome: HNO-ärztliche Vorstellung und Vorstellung beim Betriebsarzt.\\n\\nNachsorge:\\n- Regelmässige Vorsorgeuntersuchungen (alle 2 Jahre bei Lärmarbeit)\\n- Wiederholungsuntersuchung beim HNO-Arzt in 6 Monaten","questions":["Ab welchem Lärmpegel ist Gehörschutz Pflicht?","Welche Art von Gehörschutz bietet den besten Schutz?","Welches Warnsignal deutet auf eine beginnende Lärmschwerhörigkeit hin?","Wie oft finden Vorsorgeuntersuchungen bei Lärmarbeit statt?"],"answers":["Ab 90 dB(A)","Kapselgehörschützer","Piepen oder Rauschen im Ohr (Tinnitus)","Alle 2 Jahre"],"vocabularyFocus":["Lärmschwerhörigkeit","Gehörschutz","Tinnitus","dB(A)","Dämpfung"],"tags":["B2","Patienteninfo","Gehörschutz","Arbeitsmedizin"]},{"id":"r50","title":"Krankenkasse: Kostenübernahme Lutschertherapie","type":"Insurance/admin document","text":"DAK Gesundheit\\nService-Center, 20097 Hamburg\\n\\nBescheid: Leistungen der medizinischen Rehabilitation\\n\\nVersicherter: Martin Vogel\\nMitgliedsnummer: 654987123\\nDatum: 01.06.2026\\n\\nSehr geehrter Herr Vogel,\\n\\nwir haben Ihren Antrag auf Kostenübernahme einer stationären medizinischen Rehabilitationsmassnahme geprüft.\\n\\nDiagnose: Chronisches Lumbalsyndrom (ICD-10: M54.5)\\n\\nEntscheidung: Der Antrag wird in vollem Umfang bewilligt.\\n\\nBewilligter Zeitraum: 22.06.2026 bis 12.07.2026 (3 Wochen)\\n\\nEinrichtung: Reha-Zentrum Bad Mergentheim, Klinik für Orthopädie\\n\\nLeistungsumfang:\\n- Unterkunft und Verpflegung: vollstationär\\n- Ärztliche Behandlung\\n- Physiotherapie (mindestens 3 Einheiten pro Tag)\\n- Medizinische Trainingstherapie\\n- Rückenschule, psychologische Betreuung bei Schmerzbewältigung\\n- Sozialberatung\\n\\nEigenbeteiligung:\\n- Sie zahlen 10 Euro pro Tag für maximal 28 Tage im Kalenderjahr\\n- Befreiung ist bei geringem Einkommen möglich\\n\\nWeitere Hinweise:\\n1. Bitte reichen Sie den Aufnahmeschein spätestens 14 Tage vor Reha-Beginn ein\\n2. Sie sind während der Reha krankgeschrieben\\n3. Bitte bringen Sie beqüme Kleidung, Sportschuhe und Ihre Medikamente mit\\n4. Ihr Arbeitgeber wurde über die Massnahme informiert","questions":["Über welchen Zeitraum erstreckt sich die bewilligte Reha?","Wie viele physiotherapeutische Einheiten sind pro Tag vorgesehen?","Welchen Eigenanteil muss der Patient pro Tag zahlen?","Bis wann muss der Aufnahmeschein eingereicht werden?"],"answers":["22.06.2026 bis 12.07.2026 (3 Wochen)","Mindestens 3 Einheiten pro Tag","10 Euro pro Tag","Spätestens 14 Tage vor Reha-Beginn"],"vocabularyFocus":["Rehabilitation","Eigenbeteiligung","Lumbalsyndrom","Aufnahmeschein","Schmerzbewältigung"],"tags":["B2","Krankenkasse","Reha","Rücken"]},{"id":"r51","title":"Leitlinie: Ambulante Behandlung der Pneumonie","type":"Clinical guideline summary","text":"S3-Leitlinie: Behandlung von erwachsenen Patienten mit ambulanter Pneumonie\\n\\nStand: Januar 2026 (Auszug)\\n\\nDefinition: Ambulant erworbene Pneumonie (CAP) ist eine akute Infektion des Lungenparenchymes, die ausserhalb des Krankenhauses erworben wurde.\\n\\nErregerspektrum:\\n- Streptococcus pneumoniä (häufigster Erreger, 30-40 Prozent)\\n- Hämophilus inflünzä\\n- Mycoplasma pneumoniä (bei unter 60-Jährigen)\\n- Legionellen, Chlamydien, Viren (Inflünza, RSV, SARS-CoV-2)\\n\\nDiagnostik:\\n- Klinik: Husten, purulenter Auswurf, Dyspnö, Fieber, Seitenschmerz\\n- Röntgen-Thorax in 2 Ebenen zur Bestätigung\\n- CRP und ggf. Procalcitonin zur Einschätzung der bakteriellen Genese\\n\\nTherapie der CAP (ambulant):\\n- Standardtherapie: Amoxicillin 1 g 3 x täglich oral für 5-7 Tage\\n- Bei Penicillinallergie: Doxycyclin 200 mg am 1. Tag, dann 100 mg 1 x täglich\\n- Bei schwerer Pneumonie (CRP > 100 mg/l, Fieber > 39 Grad): Amoxicillin/Clavulansäure 875/125 mg 3 x täglich\\n\\nAufnahmekriterien für das Krankenhaus:\\n- CRB-65-Score > 2 Punkte\\n- Saürstoffsättigung < 90 Prozent\\n- Verwirrtheit, Tachypnö > 30/min oder systolischer RR < 90 mmHg","questions":["Welcher Erreger ist bei ambulanter Pneumonie am häufigsten?","Welches bildgebende Verfahren bestätigt die Diagnose?","Welches Antibiotikum ist die Standardtherapie?","Ab welcher Saürstoffsättigung ist eine Krankenhausaufnahme indiziert?"],"answers":["Streptococcus pneumoniä (30-40 Prozent)","Röntgen-Thorax in 2 Ebenen","Amoxicillin 1 g 3 x täglich für 5-7 Tage","Saürstoffsättigung unter 90 Prozent"],"vocabularyFocus":["Pneumonie","Erreger","Procalcitonin","CRB-65-Score","ambulant"],"tags":["B2","Leitlinie","Pneumonie","Infektiologie"]},{"id":"r52","title":"Notaufnahmeprotokoll: Akute Cholangitis","type":"Emergency department note","text":"NOTAUFNAHME - interdisziplinäre NOTAUFNAHME\\n\\nDatum: 02.06.2026, 23:15 Uhr\\n\\nPatient: Rosa König, 68 Jahre\\nEintreffart: Mit Rettungswagen, Notarzt\\n\\nVorstellungsgrund: Fieber bis 39,5 Grad, Schüttelfrost, rechtseitige Oberbauchschmerzen, Gelbfärbung der Haut seit gestern.\\n\\nVitalparameter:\\n- Blutdruck: 100/60 mmHg\\n- Puls: 110/min, tachykard\\n- SpO2: 95% Raumluft\\n- Temperatur: 39,2 Grad\\n\\nAnamnese: Bekannte Cholezystolithiasis. Keine bekannte Lebererkrankung.\\n\\nKörperliche Untersuchung:\\n- Abdomen: Druckschmerz rechter Oberbauch, Murphy-Zeichen positiv, leichte Abwehrspannung\\n- Skleren: ikterisch verfärbt\\n- Haut: leichter Ikterus\\n\\nLabor:\\n- Leukozyten: 18.500 / Mikroliter\\n- CRP: 210 mg/l\\n- Bilirubin gesamt: 4,2 mg/dl (Norm < 1,2)\\n- AP: 340 U/l (Norm < 130)\\n- GGT: 280 U/l\\n\\nSonografie Abdomen: Erweiterte intrahepatische Gallenwege, Ductus choledochus auf 14 mm erweitert, mehrere Steine im Gallenblasenfundus.\\n\\nBeurteilung: Akute Cholangitis bei Choledocholithiasis mit Cholestase und systemischer Inflammationsreaktion. Bei Verdacht auf beginnende Sepsis notfallmässige ERCP mit Papillotomie und Steinextraktion erforderlich.\\n\\nMassnahmen:\\n- Breitbandantibiotika (Piperacillin/Tazobactam) nach Blutkultur\\n- i.v. Flüssigkeit (Kristalloide)\\n- Vorbereitung zur ERCP","questions":["Welche Symptome in der Charcot-Trias sind vorhanden?","Welcher Laborwert zeigt die Gallestauung an?","Welches bildgebende Verfahren wurde in der Notaufnahme durchgeführt?","Welche Antibiotikatherapie wurde begonnen?"],"answers":["Fieber, rechtseitige Oberbauchschmerzen, Gelbfärbung (Ikterus)","Bilirubin gesamt 4,2 mg/dl, AP 340 U/l, GGT 280 U/l","Sonografie Abdomen","Piperacillin/Tazobactam"],"vocabularyFocus":["Cholangitis","Choledocholithiasis","Charcot-Trias","Ikterus","Cholestase"],"tags":["B2","Notaufnahme","Cholangitis","Gaströnterologie"]},{"id":"r53","title":"Operationsbericht: Hüft-TEP","type":"Operation report excerpt","text":"OPERATIONSBERICHT\\n\\nPatient: Georg Scheller, 74 Jahre\\nDatum: 04.06.2026\\nOperation: Implantation einer Hüft-Totalendoprothese rechts (zementiert)\\n\\nPräoperative Diagnose: Coxarthrose rechts mit schmerzhafter Bewegungseinschränkung\\nPostoperative Diagnose: s.o.\\n\\nZugang: Transglutealer Zugang nach Baür\\n\\nOperationsverlauf:\\nNach spinaler Anästhesie wurde der Patient in Rechtseitenlage gelagert. Nach Hautdesinfektion und steriler Abdeckung erfolgte ein ca. 15 cm langer Hautschnitt über dem rechten Hüftgelenk. Das subkutane Fettgewebe wurde durchtrennt, die Fascia lata incidiert und der Tractus iliotibialis gespalten.\\n\\nDer Schenkelhals wurde mit einer oszillierenden Säge durchtrennt und der Hüftkopf entfernt. Das Acetabulum wurde mit kugeligen Fräsen bis zur blutenden Spongiosa präpariert. Nach Probegrösse wurde eine Pressfit-Pfanne mit 52 mm Durchmesser implantiert und mit zwei Spongiosaschrauben zusätzlich fixiert. Ein Polyethylen-Inlay wurde eingesetzt.\\n\\nDer Femurschaft wurde aufgeraspelt und ein zementierter Schaft der Größe 12 implantiert. Nach Aushärten des Zements wurde ein Keramikkopf der Größe M aufgesetzt. Die Reposition gelang problemlos. Die Gelenkbeweglichkeit war frei, kein Impingement.\\n\\nBlutverlust: 400 ml\\nOperationsdaür: 1 Stunde 35 Minuten\\nKomplikationen: Keine\\n\\nChirurg: PD Dr. med. Stefan Gärtner","questions":["Über welchen Zugang wurde die Hüfte operiert?","Wie gross war der Blutverlust?","Welche Anästhesie-Form wurde gewählt?","Aus welchem Material besteht der Hüftkopf?"],"answers":["Transglutealer Zugang nach Baür","400 ml","Spinale Anästhesie","Keramik"],"vocabularyFocus":["Coxarthrose","Hüft-TEP","transgluteal","Pressfit","Impingement"],"tags":["B2","Operationsbericht","Hüfte","Orthopädie"]},{"id":"r54","title":"Visitennotiz: Delir bei alter Patientin","type":"Ward round note","text":"STATIONSVISITE - 06.06.2026\\n\\nPatientin: Herta Schilling, 86 Jahre, Zimmer 218\\nStation: 2C - Geriatrie\\n\\nDiagnosen: Akuter Verwirrtheitszustand (Delir) bei Exsikkose und Harnwegsinfektion\\n\\nAufnahmegrund: Die Patientin wurde von der Tochter gebracht, da sie seit zwei Tagen verwirrt, unruhig und zeitlich desorientiert sei. Sie spreche wirr, versuche aufzustehen und die Wohnung zu verlassen.\\n\\nHeutiger Status:\\n- Vigilanz: wach, aber zeitlich und situativ desorientiert\\n- CAM-Score: 4/4 (positives Delir-Screening)\\n- Temperatur: 37,8 Grad\\n- Blutdruck: 110/70 mmHg\\n- Puls: 88/min\\n- Trinkmenge: ca. 400 ml in 24h (deutlich zu wenig)\\n- Urin: Leukozyten ++, Nitrit positiv\\n\\nTherapie:\\n- i.v. Flüssigkeit (Ringer-Laktat 1000 ml/24h)\\n- Antibiotika: Ciprofloxacin 400 mg i.v. 1-0-1 (nach Antibiogramm)\\n- Bei Unruhe: Melperon 25 mg bei Bedarf (letzte Gabe vor 6h erfolgreich)\\n- Trypsin-Chymotrypsin zur Ödemausschwemmung\\n\\nVerlauf:\\n- Die Patientin ist heute Morgen ruhiger als gestern\\n- Sie erkennt ihre Tochter wieder (war gestern nicht der Fall)\\n- Trinkmenge muss weiter gesteigert werden\\n\\nPlan:\\n- Kostaufbau (Brei, Suppe, viel Trinken anbieten)\\n- Orientierungshilfen: Brille + Hörgerät bereitstellen, Uhr und Kalender aufstellen\\n- Mobilisation: Täglich 2x auf den Flur (Physiotherapie)\\n- Familienbesuch in kleinen, ruhigen Zeitfenstern","questions":["Welcher CAM-Score deutet auf ein Delir hin?","Welche Infektion wurde bei der Patientin festgestellt?","Welches Medikament wird bei Unruhe gegeben?","Welche Orientierungshilfen sollen bereitgestellt werden?"],"answers":["CAM-Score 4/4 (positiv)","Harnwegsinfektion (Leukozyten ++, Nitrit positiv)","Melperon 25 mg bei Bedarf","Brille, Hörgerät, Uhr und Kalender"],"vocabularyFocus":["Delir","CAM-Score","Exsikkose","Desorientierung","Melperon"],"tags":["B2","Visite","Delir","Geriatrie"]},{"id":"r55","title":"Pflegeübergabe: Stomaversorgung","type":"Nursing handover note","text":"Pflichtenübergabe - NACHTSCHICHT\\n\\nDatum: 05.06.2026, 06:30 Uhr\\n\\nPatient: Karl-Heinz Jung, 61 Jahre, Zimmer 209\\n\\nDiagnose: Z.n. Anlage eines endständigen Colostomas nach Sigmaresektion bei Divertikulitis\\n\\nAktüller Zustand:\\nDer Patient wurde vor 5 Tagen operiert. Der postoperative Verlauf ist komplikationslos. Der Patient ist wach, orientiert, Schmerzen 2/10.\\n\\nStoma-Situation:\\n- Colostoma im linken Unterbauch, gut durchblutet, rosige Schleimhaut\\n- Stomagrösse: 35 mm (öde marme Rückbildung im Gange)\\n- Stoma-Bett: reizlos, kein Hautausschlag, keine Mazeration\\n- Stoma-Beutel: letzter Wechsel 22:00 Uhr, halb gefüllt mit dünnbreiigem Stuhl\\n- Ausstrichmenge letzte 24h: ca. 400 ml (normal für frühe postoperative Phase)\\n\\nErnährung:\\n- Kostaufbau: Leichte Vollkost wird vertragen (Kartoffelbrei, Reis, gekochtes Gemüse)\\n- Trinkmenge: 1.200 ml (ausreichend)\\n\\nWichtiges:\\n- Stomapflegekraft kommt heute um 10:00 Uhr zur Schulung\\n- Der Patient hat Fragen zur Ernährung mit Stoma (blähende Speisen)\\n- Bitte auf Stärke der Naht achten, Stomaversorgung und -farbe dokumentieren\\n- Morgen: Abdomen-Leeraufnahme zur Kontrolle der Darmentleerung","questions":["Welche Art von Stoma wurde angelegt?","Wie gross ist das Stoma aktüll?","Welche Kost isst der Patient aktüll?","Wann kommt die Stomapflegekraft zur Schulung?"],"answers":["Ein endständiges Colostoma","35 mm","Leichte Vollkost (Kartoffelbrei, Reis, gekochtes Gemüse)","Heute um 10:00 Uhr"],"vocabularyFocus":["Colostoma","Stomaversorgung","Mazeration","Sigmaresektion","Divertikulitis"],"tags":["B2","Pflege","Stoma","Chirurgie"]},{"id":"r56","title":"Reha-Empfehlung: Nach Schulter-OP","type":"Rehabilitation recommendation","text":"REHA-EMPFEHLUNG\\n\\nPatientin: Ellen Schreiber, 54 Jahre\\nDiagnose: Z.n. arthroskopischer Rotatorenmanschettenrekonstruktion rechts\\nDatum: 07.06.2026\\n\\nSehr geehrte Reha-Einrichtung,\\n\\nFrau Schreiber wurde am 28.05.2026 an der rechten Schulter wegen einer kompletten Ruptur der Supraspinatussehne operiert. Die Rekonstruktion erfolgte mittels Ankernähten.\\n\\nAktüller Zustand:\\n- Schulterschlinge: noch für 4 Wochen erforderlich\\n- Passive Beweglichkeit: Abduktion 60 Grad, Anteversion 80 Grad, Aussenrotation 20 Grad\\n- Aktive Beweglichkeit: noch nicht freigegeben\\n- Schmerzangabe: 3/10 unter Novaminsulfon so oft\\n\\nIndikation: Anschlussheilbehandlung nach Schulter-OP.\\n\\nReha-Ziele:\\n1. Passive Mobilisation bis zur Schmerzgrenze unter physiotherapeutischer Anleitung\\n2. Abschwellung durch Lymphdrainage\\n3. Nach Schlingenabnahme in 4 Wochen: aktive Kräftigung der Rotatorenmanschette\\n4. Erlernen von Alltagskompensationen (Anziehen, Haare kämmen)\\n5. Berufliche Wiedereingliederung als Erzieherin (He bearbeitung mit Kindern)\\n\\nBegleiterkrankungen: Diabetes mellitus Typ 2, gut eingestellt.\\nBelastbarkeit: Keine aktive Belastung des rechten Arms bis zur Schlingenabnahme.\\n\\nEmpfohlene Dauer: 4 Wochen stationär.","questions":["Welche Sehne wurde rekonstruiert?","Wie lange muss die Patientin die Schulterschlinge noch tragen?","Welche passive Abduktion ist aktüll möglich?","Welchen Beruf hat die Patientin?"],"answers":["Supraspinatussehne (komplette Ruptur)","Noch 4 Wochen","60 Grad","Erzieherin"],"vocabularyFocus":["Rotatorenmanschette","Supraspinatus","Sehnenruptur","Arthroskopie","Lymphdrainage"],"tags":["B2","Reha","Schulter","Orthopädie"]},{"id":"r57","title":"Nachsorgebrief: Mammakarzinom-Nachsorge","type":"Follow-up letter","text":"NACHSORGEBRIEF - BRUSTZENTRUM, SANA KLINIKUM\\n\\nPatientin: Brigitte Kramer, 52 Jahre\\nDiagnose: Invasiv duktales Mammakarzinom links, pT1c pN0 (sn) M0, Luminal B, HER2-negativ\\n\\nTherapie: Brusterhaltende Therapie links (01/2026) mit Wächterlymphknotenbiopsie, gefolgt von 6 Wochen Bestrahlung\\n\\nSehr geehrte Frau Kollegin, sehr geehrter Herr Kollege,\\n\\nwir haben Frau Kramer heute zur Nachsorge in unserer Spechstunde gesehen.\\n\\nAktüller Befund:\\n- Die Patientin ist beschwerdefrei\\n- Linke Brust: unauffälliger Tastbefund, Narbe reizlos, kein Ödem\\n- Linke Axilla: kein tastbarer Lymphknoten\\n- Rechte Brust und Axilla: unauffällig\\n\\nEndokrine Therapie:\\n- Letrozol 2,5 mg täglich (seit M‰rz 2026)\\n- Wird gut vertragen, keine Hitzewallungen oder Gelenkschmerzen\\n\\nNächste Kontrollen:\\n- Mammographie beidseits in 12 Monaten\\n- Gynä kologische Kontrolle in 6 Monaten\\n- Sonographie Abdomen in 12 Monaten (bei Tamoxifen-Therapie nicht nötig)\\n- Nächste Nachsorge-Vorstellung in 6 Monaten\\n\\nEmpfehlungen:\\n- Vitamin D- und Calcium-Einnahme wegen Aromatasehemmer-Therapie\\n- Tägliche Bewegung (30 Minuten, moderat)\\n- Gewichtsreduktion empfohlen (BMI 29, Adipositas Grad I)\\n- Psychoonkologische Mitbetreuung fortführen (Abschlussgespräch nächste Woche)","questions":["Welche Operation wurde bei Frau Kramer durchgeführt?","Welches endokrine Medikament nimmt die Patientin täglich?","Wann wird die nächste Mammographie durchgeführt?","Warum wird Vitamin D und Calcium empfohlen?"],"answers":["Brusterhaltende Therapie links mit Wächterlymphknotenbiopsie","Letrozol 2,5 mg täglich","In 12 Monaten","Wegen der Aromatasehemmer-Therapie (Knochenschutz)"],"vocabularyFocus":["Mammakarzinom","brusterhaltend","Wächterlymphknoten","Letrozol","Aromatasehemmer"],"tags":["B2","Nachsorge","Brustkrebs","Onkologie"]},{"id":"r58","title":"Aushang: Masern-Schutzimpfung","type":"Public health notice","text":"GESUNDHEITSAMT FRANKFURT AM MAIN\\n\\nAKTUELLER HINWEIS: MASERN IN FRANKFURT\\n\\nStand: 05.06.2026\\n\\nIm Stadtgebiet Frankfurt wurden in den letzten 4 Wochen 12 bestätigte Masernfälle gemeldet. Die betroffenen Personen sind überwiegend ungeimpfte Jugendliche und junge Erwachsene.\\n\\nWas sind Masern?\\nEine hochansteckende Virusinfektion, die durch Trüpfcheninfektion übertragen wird. Die Ansteckungsrate liegt bei über 90 Prozent bei ungeschützten Kontaktpersonen.\\n\\nSymptome:\\n- Fieber, Husten, Schnupfen, Bindehautentzündung (3-5 Tage)\\n- Dann typischer Hautausschlag (rötlich-braune Flecken, beginnend im Gesicht, sich über den gesamten Körper ausbreitend)\\n\\nKomplikationen:\\n- Mittelohrentzündung (haüfig)\\n- Lungenentzündung (1-5 Prozent)\\n- Masernenzephalitis (0,1 Prozent)\\n- Subakute sclerosierende Panenzephalitis (SSPE) als Spätfolge nach Jahren (extrem selten)\\n\\nSchutzmassnahmen:\\n- Die Impfung ist der wirksamste Schutz\\n- Empfohlen für alle ab 12 Monaten (erste Impfung) und 15-23 Monaten (zweite Impfung)\\n- Nicht- oder unvollständig geimpfte Erwachsene ab Jahrgang 1970 sollten die Impfung nachholen\\n- Die Impfung ist über die Krankenkasse kostenfrei\\n\\nBitte überprüfen Sie Ihren Impfstatus. Bei Unsicherheit: Hausarzt konsultieren.","questions":["Wie viele Masernfälle wurden in den letzten 4 Wochen gemeldet?","Welche Ansteckungsrate haben Masern bei ungeschützten Personen?","Welche schwerwiegende Komplikation kann als Spätfolge auftreten?","Welcher Jahrgang soll die Masernimpfung nachholen?"],"answers":["12 bestätigte Fälle","Über 90 Prozent","Subakute sclerosierende Panenzephalitis (SSPE)","Erwachsene ab Jahrgang 1970"],"vocabularyFocus":["Masern","Impffstatus","Trüpfcheninfektion","Masernenzephalitis","SSPE"],"tags":["B2","Öffentlichkeit","Masern","Impfung"]},{"id":"r59","title":"Vorbereitung: Koloskopie","type":"Appointment instruction sheet","text":"VORBEREITUNG ZUR DARMSPIEGELUNG (KOLOSKOPIE)\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nIhr Termin zur Darmspiegelung: 14.06.2026 um 10:00 Uhr, Praxis Dr. Gross, Raum 105.\\n\\nDie Vorbereitung ist entscheidend für die Qualität der Untersuchung.\\n\\n3 Tage vor der Untersuchung:\\n- Keine körnigen oder faserreichen Lebensmittel mehr (kein Vollkornbrot, kein Müsli, keine Nüsse, kein Popcorn, keine Körner)\\n- Erlaubt: Weissbrot, Kartoffeln, Reis, Nudeln, Joghurt, weicher Kä se\\n\\n1 Tag vor der Untersuchung:\\n- Nur leichte Kost zum Frühstück und Mittagessen\\n- Ab 14:00 Uhr: Nur noch klare Flüssigkeiten (Bruhe, klarer Tee, Wasser, Limonade ohne rot)\\n- 18:00 Uhr: Beginn der Darmreinigung\\n\\nDarmreinigung:\\n- Sie erhalten 4 Beutel Moviprep\\n- 18:00 Uhr: 1. Beutel in 1 Liter Wasser, innerhalb 1 Stunde trinken\\n- 20:00 Uhr: 2. Beutel in 1 Liter Wasser\\n- Am Untersuchungstag um 05:30 Uhr: 3. + 4. Beutel\\n\\nAm Untersuchungstag:\\n- Ab 06:00 Uhr nichts mehr trinken\\n- Keine Medikamente einnehmen (ausser vom Arzt erlaubt)\\n- Blutverdünner nach Anweisung des verschreibenden Arztes absetzen\\n\\nBringen Sie mit:\\n- Überweisung, Versichertenkarte\\n- Medikamentenliste\\n- Eine Begleitperson (Fahrverbot nach Sedierung für 24h)","questions":["Welche Lebensmittel sollen 3 Tage vor der Koloskopie vermieden werden?","Wann beginnt die Darmreinigung am Tag vor der Untersuchung?","Wie viel Wasser ist pro Moviprep-Beutel erforderlich?","Wie lange gilt Fahrverbot nach der Sedierung?"],"answers":["Körnige und faserreiche Lebensmittel (Vollkornbrot, Müsli, Nüsse, Körner)","18:00 Uhr","1 Liter Wasser pro Beutel","24 Stunden"],"vocabularyFocus":["Darmspiegelung","Darmreinigung","Moviprep","Sedierung","Begleitperson"],"tags":["B2","Termin","Koloskopie","Gaströnterologie"]},{"id":"r60","title":"Patientenbeschwerde: Keine Privatsphäre","type":"Patient complaint letter","text":"Betreff: Beschwerde über mangelnden Datenschutz im Patientenzimmer\\n\\nSehr geehrte Klinikleitung,\\n\\nich war vom 20.05. bis 25.05.2026 auf Ihrer Station 3B (Gaströnterologie) als Patient aufgenommen. Ich möchte mich über einen massiven Verstoss gegen meine Privatsphäre beschweren.\\n\\nAm 22.05.2026 wurde auf der Station eine Visite durchgeführt. Dabei wurden meine persönlichen Laborwerte, meine Diagnose und meine geplante Behandlung im Gang vor dem Patientenzimmer laut besprochen. Die Tür stand offen, und mehrere andere Patienten und Besucher konnten alles hören. Ich wurde nicht gefragt, ob ich mit der Besprechung an diesem Ort einverstanden bin.\\n\\nDarüber hinaus lag mein Entlassungsbrief mit allen personenbezogenen Daten am nächsten Tag sichtbar im Ablagefach an der Tür, obwohl mir versichert wurde, dass solche Dokumente nur direkt dem Patienten ausgehändigt werden.\\n\\nIch bitte um:\\n1. Eine Stellungnahme zu diesem Vorfall\\n2. Schulung des Personals zum Datenschutz\\n3. Sicherstellung, dass Visiten grundsätzlich entweder hinter geschlossener Tür oder in einem separaten Raum stattfinden\\n\\nSollte keine zufriedenstellende Rückmeldung erfolgen, werde ich mich an den Datenschutzbeauftragten des Landes wenden.\\n\\nMit freundlichen Grüssen\\nDr. Frank Walther (Patient)\\n\\nAnlage: Kopie der Patienteninformation","questions":["Wo wurde das Patientengespräch geführt, das der Patient beanstandet?","Welches Dokument lag sichtbar im Ablagefach?","Was fordert der Patient als zweiten Punkt?","An wen wendet sich der Patient bei fehlender Rückmeldung?"],"answers":["Im Gang vor dem Patientenzimmer bei offener Tür","Der Entlassungsbrief","Schulung des Personals zum Datenschutz","An den Datenschutzbeauftragten des Landes"],"vocabularyFocus":["Datenschutz","Privatsphäre","Visite","Entlassungsbrief","Datenschutzbeauftragter"],"tags":["B2","Beschwerde","Datenschutz","Patientenrechte"]},{"id":"r61","title":"Arztbrief: Aufnahme bei Lungenembolie","type":"Arztbrief excerpt","text":"Arztbrief vom 08.06.2026\\n\\nPatient: Frau Petra Simon, 58 Jahre alt\\nDiagnose: Akute Lungenembolie (niedriges Risiko) bei tiefer Beinvenenthrombose rechts\\n\\nAufnahmegrund: Die Patientin wurde vom Notarzt mit plötzlich aufgetretener Dyspnö, Brustschmerz und Husten eingeliefert. Symptome begannen zwei Stunden vor Eintreffen. Die Patientin berichtet über eine längere Autofahrt vor einer Woche.\\n\\nDiagnostik:\\n- CT-Angiografie: Nachweis einer Lungenembolie segmental im rechten Unterlappen\\n- Duplexsonografie: Thrombose der Vena poplitea rechts\\n- Troponin: 0,02 ng/ml (Norm < 0,04), kein Hinweis auf Rechtsherzbelastung\\n- D-Dimere: 5,8 mg/l (Norm < 0,5)\\n\\nTherapie: Therapeutische Antikoagulation mit Enoxaparin s.c., begleitende Einstellung auf Apixaban. Saürstoff 2 l/min bei Bedarf.\\n\\nEmpfehlung: Nach Stabilisierung ambulante Weiterführung der Antikoagulation für mindestens 3 Monate. Kompressionsversorgung.","questions":["Welche Hauptdiagnose wurde gestellt?","Welche bildgebende Untersuchung bestätigte die Lungenembolie?","Welches Blutgerinnungsmedikament wird zur Langzeittherapie eingestellt?","Wie lange soll die Antikoagulation mindestens dauern?"],"answers":["Akute Lungenembolie (niedriges Risiko) bei tiefer Beinvenenthrombose","CT-Angiografie","Apixaban","Mindestens 3 Monate"],"vocabularyFocus":["Lungenembolie","CT-Angiografie","Antikoagulation","Apixaban","Duplexsonografie"],"tags":["B2","Arztbrief","Lungenembolie","Gefässmedizin"]},{"id":"r62","title":"Laborbericht: Leberwerte bei Fettleber","type":"Lab report explanation","text":"Laborbefund vom 10.06.2026\\n\\nPatient: Herr Sven Lehmann, 45 Jahre\\nAuftrag: Abklärung erhöhter Leberwerte bei V.a. Fettlebererkrankung\\n\\nKlinische Angabe: Zufallsbefund bei Routinelabor, leichtes Druckgefühl im rechten Oberbauch. Übergewicht (BMI 32). Kein Alkoholkonsum.\\n\\nErgebnisse:\\n- GOT (AST): 52 U/l (Norm < 35 U/l) - leicht erhöht\\n- GPT (ALT): 78 U/l (Norm < 35 U/l) - erhöht\\n- GGT: 95 U/l (Norm < 40 U/l) - erhöht\\n- AP: 85 U/l (Norm < 130 U/l) - normwertig\\n- Bilirubin: 0,8 mg/dl (Norm < 1,2) - normwertig\\n- HbA1c: 6,4 Prozent (Norm < 5,7) - erhöht, Hinweis auf Prädiabetes\\n- Triglyceride: 280 mg/dl (Norm < 150) - erhöht\\n- Hepatitis-Serologie: negativ\\n\\nSonografie Abdomen: Echoarme Leber, homogen, keine Raumforderung, vermehrte Echogenität vereinbar mit Fettleber.\\n\\nBeurteilung: Nicht-alkoholische Fettlebererkrankung (NAFLD) mit milden Transaminasenerhöhungen und metabolischem Risikoprofil. Empfehlung: Gewichtsreduktion um mindestens 7 Prozent, Bewegung.","questions":["Welche Transaminase ist am stärksten erhöht?","Welcher Blutzucker-Langzeitwert ist erhöht?","Welche Erkrankung der Leber wird vermutet?","Welche Massnahme wird als erste empfohlen?"],"answers":["GPT (ALT) mit 78 U/l","HbA1c mit 6,4 Prozent","Nicht-alkoholische Fettlebererkrankung (NAFLD)","Gewichtsreduktion um mindestens 7 Prozent"],"vocabularyFocus":["Fettleber","Transaminasen","NAFLD","HbA1c","Fibroscan"],"tags":["B2","Labor","Leber","Stoffwechsel"]},{"id":"r63","title":"Knochenszintigrafie: V.a. Skelettmetastasen","type":"Imaging report excerpt","text":"KNOCHENSZINTIGRAFIE-BEFUND\\n\\nPatient: Herr Günther Koch, 69 Jahre\\nDatum: 12.06.2026\\nFragestellung: V.a. Skelettmetastasen bei bekanntem Prostatakarzinom (Gleason 8, T3a)\\n\\nTechnik: Ganzkörperszintigrafie 3 Stunden nach Injektion von 650 MBq Tc-99m-DPD. Zusätzliche SPECT/CT des Thorax und der LWS.\\n\\nBefund:\\n- Physiologische Mehranreicherung in Nieren und ableitenden Harnwegen\\n- Keine pathologische Mehranreicherung am Schädel, an der HWS, BWS oder den oberen Extremitäten\\n- Im Bereich der LWS: fokale Mehranreicherung in BWK 12 und LWK 3, in der SPECT/CT korrespondierend zu osteoplastischen Läsionen\\n- Keine pathologischen Frakturen\\n\\nBeurteilung: Ganzkörperszintigrafisch Nachweis von zwei osteoplastischen Skelettmetastasen in BWK 12 und LWK 3 bei bekanntem Prostatakarzinom. Bei Schmerzen oder Frakturgefahr Indikation zur Radiotherapie prüfen.","questions":["Welche Tumorerkrankung liegt dem Patienten zugrunde?","Wie viele Skelettmetastasen wurden gefunden?","In welchen Wirbelkörpern befinden sich die Metastasen?","Welche Therapieoption wird bei Frakturgefahr empfohlen?"],"answers":["Prostatakarzinom (Gleason 8, T3a)","Zwei","BWK 12 und LWK 3","Radiotherapie der befallenen Wirbelkörper"],"vocabularyFocus":["Knochenszintigrafie","Skelettmetastase","osteoplastisch","SPECT/CT","Radiotherapie"],"tags":["B2","Szintigrafie","Prostata","Onkologie"]},{"id":"r64","title":"Packungsbeilage: Pantoprazol 40 mg","type":"Medication leaflet excerpt","text":"GEBRAUCHSINFORMATION: Pantoprazol 40 mg magensaftresistente Tabletten\\n\\nWirkstoff: Pantoprazol-Natrium-Sesquihydrat\\nAnwendungsgebiete: Sodbrennen, saures Aufstossen, Magengeschwüre. Behandlung der gastroösophagealen Refluxkrankheit. In Kombination mit Antibiotika zur Eradikation von Helicobacter pylori.\\n\\nGegenanzeigen:\\n- Überempfindlichkeit gegen Pantoprazol oder andere Protonenpumpenhemmer\\n- Gleichzeitige Einnahme von Atazanavir\\n- Schwere Leberfunktionsstörung\\n\\nDosierung:\\n- Erwachsene: 1 Tablette (40 mg) täglich\\n- Tablette unzerkaut und mit etwas Wasser vor dem Frühstück einnehmen\\n\\nBesondere Warnhinweise:\\n- Bei Langzeitanwendung über 1 Jahr: erhöhtes Risiko für Knochenbrüche\\n- Langzeittherapie kann Vitamin-B12-Mangel begünstigen\\n- Schwerer Durchfall kann auf Clostridium-difficile-Infektion hinweisen\\n\\nNebenwirkungen:\\nHäufig: Kopfschmerzen, Durchfall, Verstopfung, Blähungen\\nGelegentlich: Übelkeit, Erbrechen, Schlaflosigkeit","questions":["Bei welcher Grunderkrankung darf Pantoprazol nicht eingenommen werden?","Wie soll die Tablette eingenommen werden?","Welches Risiko besteht bei Langzeitanwendung über 1 Jahr?","Welcher Erreger kann schweren Durchfall verursachen?"],"answers":["Bei gleichzeitiger Einnahme von Atazanavir","Unzerkaut mit etwas Wasser vor dem Frühstück","Erhöhtes Risiko für Knochenbrüche","Clostridium-difficile-Infektion"],"vocabularyFocus":["Pantoprazol","Protonenpumpenhemmer","Reflux","Helicobacter pylori","Clostridium difficile"],"tags":["B2","Medikament","Pantoprazol","Magen"]},{"id":"r65","title":"Klinikrichtlinie: Umgang mit multiresistenten Erregern","type":"Hospital policy","text":"KLINIKRICHTLINIE: UMGANG MIT MULTIRESISTENTEN ERREGERN (MRE)\\n\\nStand: Februar 2026\\n\\n1. Screening bei Aufnahme:\\nFolgende Patienten werden bei Aufnahme auf MRSA, VRE und 3-/4-MRGN getestet:\\n- Patienten mit bekanntem MRE in der Vorgeschichte\\n- Patienten aus Altenheim oder Pflegeheim\\n- Patienten aus Ländern mit hoher MRE-Prävalenz\\n- Patienten mit wiederholten Krankenhausaufenthalten in den letzten 12 Monaten\\n\\n2. Isolierungsmassnahmen:\\n- MRSA: Einzelzimmer mit Schleusenfunktion\\n- VRE: Einzelzimmer, Schutzkittel und Handschuhe bei Patientenkontakt\\n- 4-MRGN: Strenges Einzelzimmer mit Schleuse, FFP2-Maske, Schutzkittel, Handschuhe\\n\\n3. Entisolierung:\\n- MRSA: Nach 3 negativen Abstrichen (24h Abstand)\\n- 3-/4-MRGN: Mit Infektiologie besprechen\\n\\n4. Hygienebeauftragte tägliche Visite aller MRE-Patienten.","questions":["Welche Patienten werden bei Aufnahme routinemässig auf MRE getestet?","Welche Schutzmassnahme gilt für 4-MRGN-Patienten?","Nach wie vielen negativen Abstrichen darf ein MRSA-Patient entisoliert werden?","Wie oft besucht der Hygienebeauftragte die MRE-Patienten?"],"answers":["Patienten mit bekanntem MRE, aus Alten-/Pflegeheimen oder mit wiederholten KH-Aufenthalten","Strenges Einzelzimmer mit Schleuse, FFP2-Maske, Schutzkittel, Handschuhe","Nach 3 negativen Abstrichen (24h Abstand)","Täglich"],"vocabularyFocus":["MRE","MRSA","MRGN","VRE","Isolierung"],"tags":["B2","Klinik","Hygiene","Infektiologie"]},{"id":"r66","title":"Einwilligungserklärung: Herzkatheteruntersuchung","type":"Consent form","text":"Einwilligungserklärung für EINE HERZKATHETERUNTERSUCHUNG\\n\\nPatient: _________________ Datum: _________________\\n\\nAufklärender Arzt: Dr. med. Karsten Bender, Kardiologie\\n\\nDiagnose: V.a. koronare Herzkrankheit bei belastungsabhängigem Brustschmerz\\n\\nUntersuchung: Koronarangiografie über die rechte Leistenarterie\\n\\nAblauf:\\n- Die Untersuchung erfolgt in örtlicher Betaubung\\n- Ein Katheter wird über die Leistenarterie bis zu den Herzkranzgefässen vorgeschoben\\n- Über den Katheter wird Kontrastmittel gespritzt\\n- Dauer: ca. 20-30 Minuten\\n\\nRisiken:\\n- Häufig: Blürguss an der Punktionsstelle (3-5 Prozent)\\n- Selten: Nachblutung, Gefässverschluss (unter 1 Prozent)\\n- Sehr selten: Herzinfarkt, Schlaganfall (0,1 Prozent)\\n\\nNach der Untersuchung:\\n- Druckverband für 6-8 Stunden, Bettruhe für 12 Stunden\\n- Viel trinken (mindestens 1,5 Liter)\\n- Bei stärkeren Schmerzen: sofort melden\\n\\nFalls sich eine behandlungsbedürftige Gefässverengung zeigt, kann direkt eine Ballondilatation (PTCA) angeschlossen werden.","questions":["Über welches Blutgefäss wird der Herzkatheter eingeführt?","Wie lange muss der Patient nach der Untersuchung Bettruhe einhalten?","Welche Komplikation ist selten, aber schwerwiegend?","Welche Massnahme kann bei einer Gefässverengung angeschlossen werden?"],"answers":["Rechte Leistenarterie","12 Stunden","Nachblutung oder Gefässverschluss an der Punktionsstelle","Ballondilatation (PTCA) mit Stenteinlage"],"vocabularyFocus":["Herzkatheter","Koronarangiografie","Kontrastmittel","PTCA","Judkins-Technik"],"tags":["B2","Einwilligung","Herzkatheter","Kardiologie"]},{"id":"r67","title":"Entlassungsbrief: Asthma bronchiale","type":"Discharge summary","text":"ENTLASSUNGSBRIEF\\n\\nPatient: Kevin Jung, 19 Jahre\\nAufenthalt: 10.06.2026 bis 14.06.2026\\nDiagnose: Akuter schwerer Asthmaanfall bei bekanntem Asthma bronchiale (GINA 4)\\n\\nAnamnese: Der Patient wurde mit akuter schwerer Dyspnö, exspiratorischem Stridor und Sprechdyspnö eingeliefert. Auslösend: Pollenexposition bei Heuschnupfen.\\n\\nDiagnostik und Verlauf:\\n- Peak-Flow bei Aufnahme: 150 l/min (Sollwert 480 l/min, 31 Prozent)\\n- SpO2: 88 Prozent Raumluft\\n- Therapie: Salbutamol und Ipratropium Inhalationen, Prednisolon 50 mg i.v.\\n- Innerhalb von 6 Stunden Besserung\\n- Peak-Flow bei Entlassung: 410 l/min (85 Prozent)\\n\\nMedikation bei Entlassung:\\n- Salbutamol-Dosierärosol nach Bedarf\\n- Budesonid/Formoterol 160/4,5 Mikrogramm 2 Hübe 2x täglich\\n- Montelukast 10 mg 0-0-1\\n\\nEmpfehlungen: Tägliches Peak-Flow-Monitoring, Allergietestung, Asthma-Schulung, Notfallplan.","questions":["Welcher Peak-Flow-Wert wurde bei Aufnahme gemessen?","Welches Medikament wurde intravenös gegeben?","Welchen Anteil des Sollwerts erreichte der Patient bei Entlassung?","Welche Überwachung soll der Patient täglich durchführen?"],"answers":["150 l/min (31 Prozent des Sollwerts)","Prednisolon 50 mg i.v.","85 Prozent (410 l/min)","Tägliches Peak-Flow-Monitoring"],"vocabularyFocus":["Asthma","Peak-Flow","Sprechdyspnö","exspiratorischer Stridor","GINA"],"tags":["B2","Entlassung","Asthma","Pneumologie"]},{"id":"r68","title":"Überweisung: Kardiologie bei Vorhofflimmern","type":"Referral letter","text":"Überweisung zum Kardiologen\\n\\nPatientin: Elke Meissner, 62 Jahre\\n\\nSehr geehrter Herr Dr. Wagner,\\n\\nich überweise Frau Meissner zur weiteren Abklärung von Herzrhythmusstörungen. Die Patientin berichtet über seit Wochen zunehmendes Herzstolpern und Herzrasen, insbesondere nachts und in Ruhephasen.\\n\\nVorerkrankungen:\\n- Arterielle Hypertonie, eingestellt mit Valsartan 80 mg\\n- BMI 28 (Übergewicht)\\n\\nAktülle Untersuchungen:\\n- 24h-Langzeit-EKG: SVES 2.340/24h, kurze Salven von Vorhofflimmern, bis zu 4 Minuten mit Kammerfreqünz bis 145/min\\n- Echokardiografie: Linker Vorhof leicht dilatiert, LVEF 62 Prozent\\n\\nBitte überprüfen Sie die Indikation zur rhythmuserhaltenden Therapie oder Antikoagulation bei paroxysmalem Vorhofflimmern.\\n\\nDr. Helga Kurz, Hausärztin","questions":["Welche Symptome in Ruhe beschreibt die Patientin?","Welche Rhythmusstörung wurde bestätigt?","Welche Kammerfreqünz wurde im Schlaf gemessen?","Welche Therapieoption soll geprüft werden?"],"answers":["Herzstolpern und Herzrasen, besonders nachts und in Ruhe","Paroxysmales Vorhofflimmern","Bis zu 145/min","Rhythmusbaltende Therapie oder Antikoagulation"],"vocabularyFocus":["Vorhofflimmern","paroxysmal","Langzeit-EKG","SVES","Antikoagulation"],"tags":["B2","Überweisung","Vorhofflimmern","Kardiologie"]},{"id":"r69","title":"Merkblatt: Inkontinenzversorgung","type":"Patient information sheet","text":"MERKBLATT: VERSORGUNG MIT INKONTINENZMATERIAL\\n\\nStand: Mai 2026\\n\\nIhr Arzt hat Ihnen Inkontinenzmaterial verordnet.\\n\\nVerordnung:\\n- Das Material wird auf Rezept vom Hausarzt oder Facharzt verschrieben\\n- Die Kosten werden von der Krankenkasse übernommen\\n- Sie zahlen 10 Euro pro Rezept zzgl. 10 Prozent des Rezeptbetrags\\n\\nArten:\\n1. Einweg-Vorlagen (bei mässiger Inkontinenz)\\n2. Netzhosen (zur Fixierung der Vorlage)\\n3. Inkontinenzhosen für schwere Inkontinenz\\n4. Bettunterlagen\\n\\nVersorgung:\\n- Sanitätshausfachberater kommt für die Erstberatung\\n- Lieferung alle 4-6 Wochen\\n\\nHautpflege:\\n- Material mindestens 3-4 Mal täglich wechseln\\n- Haut mit Wasser waschen und sanft abtrocknen\\n- Wundschutzcreme auftragen, keine parfümierten Produkte","questions":["Wer verordnet das Inkontinenzmaterial?","Wie hoch ist die Zuzahlung pro Rezept?","Welche Hilfsmittel sind für schwere Inkontinenz geeignet?","Wie oft sollte das Material mindestens gewechselt werden?"],"answers":["Der Hausarzt oder Facharzt","10 Euro pro Rezept zzgl. 10 Prozent des Rezeptbetrags","Inkontinenzhosen zum Anziehen wie Unterwasche","Mindestens 3-4 Mal täglich"],"vocabularyFocus":["Inkontinenz","Hilfsmittelverordnung","Sanitätshaus","Zuzahlung","Hautpflege"],"tags":["B2","Patienteninfo","Inkontinenz","Pflege"]},{"id":"r70","title":"Krankenkasse: Genehmigung einer Haushaltshilfe","type":"Insurance/admin document","text":"AOK Hessen\\nServicezentrum, 60528 Frankfurt am Main\\n\\nBescheid über Haushaltshilfe\\n\\nVersicherte: Renate Fuchs\\nMitgliedsnummer: 852963741\\nDatum: 15.06.2026\\n\\nSehr geehrte Frau Fuchs,\\n\\nwir haben Ihren Antrag auf Kostenübernahme einer Haushaltshilfe nach Paragraf 38 SGB V geprüft und bewilligt.\\n\\nVoraussetzung:\\n- Der Antrag wurde aufgrund Ihres stationären Krankenhausaufenthalts vom 01.06. bis 12.06.2026 gestellt\\n- Sie leben mit einem minderjährigen Kind (8 Jahre) zusammen\\n- Es ist keine andere Person für die Haushaltsführung vorhanden\\n\\nBewilligter Umfang:\\n- Täglich 4 Stunden Haushaltshilfe\\n- Zeitraum: 12.06.2026 bis 26.06.2026 (14 Tage)\\n\\nLeistungserbringer:\\n- Sie können die Haushaltshilfe selbst wählen\\n- Vorschlag der Krankenkasse: Deutsches Rotes Kreuz","questions":["Welche Rechtsgrundlage führt die Krankenkasse für die Haushaltshilfe an?","Wie viele Stunden täglich umfasst die bewilligte Haushaltshilfe?","Wer kann die Haushaltshilfe aussuchen?","Was passiert bei längerem Bedarf als 14 Tage?"],"answers":["Paragraf 38 SGB V","4 Stunden täglich","Die Versicherte kann die Haushaltshilfe selbst wählen","Ein Folge- oder Verlängerungsantrag ist erforderlich"],"vocabularyFocus":["Haushaltshilfe","SGB V","Eigenanteil","Bemessungsgrenze","Familienpflegerin"],"tags":["B2","Krankenkasse","Haushaltshilfe","Versicherung"]},{"id":"r71","title":"Leitlinie: Behandlung der unipolaren Depression","type":"Clinical guideline summary","text":"S3-Leitlinie: Unipolare Depression bei Erwachsenen\\n\\nStand: 2026 (Auszug)\\n\\nKlassifikation nach Schweregrad:\\n- Leichte Episode: 2-3 Kernsymptome, Alltag noch möglich\\n- Mittelgradige Episode: 4-5 Symptome, deutliche Einschränkung\\n- Schwere Episode: Mehr als 5 Symptome, keine alltäglichen Aktivitäten mehr möglich\\n\\nDiagnostik:\\n- Strukturiertes klinisches Interview\\n- Fragebögen (PHQ-9, BDI-II)\\n- Ausschluss organischer Ursachen (TSH, Vitamin B12, Folsäure, Eisen)\\n\\nTherapie:\\n- Leichte Episode: Psychöducation, nicht medikamentös\\n- Mittelgradige Episode: Psychotherapie ODER SSRI\\n- Schwere Episode: Kombination Psychotherapie und Medikation\\n\\nMedikamentöse Therapie:\\n- SSRI (Sertralin, Escitalopram, Citalopram) als erste Wahl\\n- Einschleichen über 1-2 Wochen, Wirkeintritt nach 2-4 Wochen\\n- Mindestens 6 Monate Erhaltungstherapie\\n\\nSuizidalität: Bei akuter Eigengefährdung sofortige Einweisung.","questions":["Welcher Fragebogen wird zur Schweregrad-Einschätzung eingesetzt?","Welche Laborwerte müssen vor der Behandlung geprüft werden?","Welche Antidepressiva der ersten Wahl werden empfohlen?","Wann ist eine stationäre Einweisung erforderlich?"],"answers":["PHQ-9 und BDI-II","TSH, Vitamin B12, Folsäure, Eisen","SSRI (Sertralin, Escitalopram, Citalopram)","Bei akuter Eigengefährdung (Suizidalität)"],"vocabularyFocus":["Depression","SSRI","PHQ-9","Psychotherapie","Suizidalität"],"tags":["B2","Leitlinie","Depression","Psychiatrie"]},{"id":"r72","title":"Notaufnahmeprotokoll: Akute Nierenkolik","type":"Emergency department note","text":"NOTAUFNAHME - ärztlicher ERSTBERICHT\\n\\nDatum: 17.06.2026, 05:30 Uhr\\n\\nPatient: Tobias Stein, 41 Jahre\\n\\nVorstellungsgrund: Seit 03:00 Uhr wellenförmig zunehmende Schmerzen im rechten Flankenbereich mit Ausstrahlung in die Leiste.\\n\\nAnamnese:\\n- Keine Vorerkrankungen\\n- Keine vorherigen Nierensteine\\n- Trinkt beruflich bedingt wenig\\n\\nUntersuchung:\\n- Klopfschmerz rechtes Nierenlager\\n- Abdomen weich, keine Abwehrspannung\\n- Temperatur: 36,9 Grad\\n\\nLabor:\\n- CRP normal\\n- Urinstatus: Erythrozyten ++\\n\\nSonografie: Rechte Niere mit leichtem Harnstau, Stein im proximalen Ureter rechts, 7 mm.\\n\\nDiagnose: Akute Nierenkolik bei Ureterstein rechts.\\n\\nTherapie:\\n- Novaminsulfon 2,5 g i.v., dann Ibuprofen 800 mg oral\\n- Tamsulosin 0,4 mg zur Spontanabgangsförderung\\n- Trinkempfehlung: mindestens 3 Liter pro Tag\\n- Bei ausbleibendem Abgang in 2 Wochen: ESWL","questions":["In welche Körperregion strahlen die Schmerzen aus?","Welcher Befund wurde im Ultraschall festgestellt?","Welches Medikament fördert den Spontanabgang des Steins?","Welche Behandlung wird bei ausbleibendem Abgang empfohlen?"],"answers":["In die Leiste und in die Genitalregion","7 mm Stein im proximalen Ureter rechts mit leichtem Harnstau","Tamsulosin 0,4 mg","ESWL (extrakorporale Stosswellenlithotripsie)"],"vocabularyFocus":["Nierenkolik","Ureterstein","Harnstau","ESWL","Tamsulosin"],"tags":["B2","Notaufnahme","Nierenstein","Urologie"]},{"id":"r73","title":"Operationsbericht: Schilddrüsenresektion","type":"Operation report excerpt","text":"OPERATIONSBERICHT\\n\\nPatientin: Frau Marie Seifert, 35 Jahre\\nDatum: 19.06.2026\\nOperation: Subtotale Schilddrüsenresektion beidseits\\n\\nPräoperative Diagnose: Struma nodosa mit Kompressionssymptomen\\n\\nOperationsverlauf:\\nNach Hautdesinfektion und steriler Abdeckung erfolgte ein qürverlaufender Kragenschnitt. Die Subkutis und Platysma wurden durchtrennt. Die Schilddrüse wurde dargestellt.\\n\\nDer rechte Schilddrüsenlappen war vergrössert (8 x 4 x 3 cm) mit mehreren Knoten bis 2,5 cm. Der linke Lappen (6 x 3 x 2 cm) mit einem Knoten von 1,5 cm.\\n\\nDer Nervus laryngeus recurrens beidseits wurde dargestellt und geschont. Vier Nebenschilddrüsen wurden identifiziert. Nach Blutstillung erfolgte der Wundverschluss mit Einlage einer Redon-Drainage.\\n\\nBlutverlust: ca. 80 ml\\nOperationsdaür: 1 Stunde 20 Minuten","questions":["Welcher Hautschnitt wurde gewählt?","Welcher Nerv wurde präpariert und geschont?","Wie viele Nebenschilddrüsen wurden identifiziert?","Wie hoch war der Blutverlust?"],"answers":["Ein qürverlaufender Kragenschnitt","Nervus laryngeus recurrens beidseits","Vier","Ca. 80 ml"],"vocabularyFocus":["Struma nodosa","Kragenschnitt","Nervus laryngeus recurrens","Nebenschilddrüse","Redon-Drainage"],"tags":["B2","Operationsbericht","Schilddrüse","Chirurgie"]},{"id":"r74","title":"Visitennotiz: Enteritis durch Campylobacter","type":"Ward round note","text":"STATIONSVISITE - 21.06.2026\\n\\nPatient: Markus Keller, 33 Jahre, Zimmer 305\\nStation: 3A - Infektiologie\\n\\nDiagnose: Akute Enteritis durch Campylobacter jejuni\\n\\nAktüller Status:\\n- Der Patient wurde vor 2 Tagen mit wässrigen Durchfällen (8-10 Mal täglich), Fieber bis 39,2 Grad und krampfartigen Bauchschmerzen eingeliefert\\n- Heute: Durchfallhäufigkeit rückläufig (4 Mal), Fieber 37,4 Grad\\n- Blutdruck: 120/75 mmHg\\n- Keine Dehydratationszeichen\\n\\nLabor im Verlauf:\\n- CRP: 45 mg/l (Eintritt 180 mg/l)\\n- Leukozyten: 9.500 (Eintritt 14.500)\\n- Kalium: 3,8 mmol/l (Norm 3,5-5,1)\\n\\nStuhldiagnostik: Campylobacter jejuni.\\nTherapie: Azithromycin 500 mg 1x täglich für 3 Tage.\\n\\nPlan: Entlassung in 1-2 Tagen nach Symptomfreiheit. Lebensmittelhygiene besprechen (unzureichend gegartes Geflügel als wahrscheinliche Ursache).","questions":["Welcher Erreger verursacht die Enteritis?","Welcher CRP-Wert wurde bei Aufnahme gemessen?","Welches Antibiotikum erhält der Patient?","Was war die wahrscheinliche Infektionsqülle?"],"answers":["Campylobacter jejuni","180 mg/l","Azithromycin 500 mg 1x täglich","Unzureichend gegartes Geflügel"],"vocabularyFocus":["Enteritis","Campylobacter","Azithromycin","Dehydratation","Lebensmittelhygiene"],"tags":["B2","Visite","Enteritis","Infektiologie"]},{"id":"r75","title":"Pflegeübergabe: PEG-Sondenversorgung","type":"Nursing handover note","text":"Pflichtenübergabe - Frühschicht\\n\\nDatum: 22.06.2026, 06:30 Uhr\\n\\nPatientin: Hilde Winter, 79 Jahre, Zimmer 206\\nStation: 4C - Geriatrie\\n\\nDiagnose: Z.n. Schlaganfall mit Schluckstörung, Ernährung über PEG-Sonde\\n\\nAktüller Zustand:\\n- Die Patientin ist wach, aber zeitlich desorientiert\\n- PEG-Sonde: Anlage vor 6 Tagen, Einstichstelle reizlos, kein Hautausschlag\\n- Heutige Sondenkost: Fresubin 1.500 ml/24h über Ernährungspumpe, nächtliche Gabe\\n\\nLetzte 24 Stunden:\\n- Sondenkost vertragen, letzter Rückfluss morgens 30 ml (hell)\\n- Stuhlgang: einmal, weich (normal bei Sondenkost)\\n- Gewicht: stabil 62 kg\\n\\nPflegemassnahmen:\\n- Sondenschulung der Angehörigen beginnt heute um 14:00 Uhr durch Pflegeberatung\\n- Mundpflege alle 2 Stunden (Mundtrockenheit bei Sondenernährung)\\n- Verbandwechsel der PEG-Einstichstelle mit steriler Kompresse und Desinfektion\\n\\nWichtige Termine:\\n- Heute 10:00 Uhr: Logopädie (Schlucktraining)\\n- Morgen: Schluckvideografie zur Prufung, ob orale Kost wieder möglich\\n- Übermorgen: Entlassungsgespräch mit Tochter","questions":["Welche Art der Ernährung erhält die Patientin?","Wie viel Sondenkost bekommt die Patientin pro Tag?","Welche Pflegemassnahme ist wegen der Sondenernährung besonders wichtig?","Welche Untersuchung ist für morgen geplant?"],"answers":["Ernährung über eine PEG-Sonde (Sondenkost)","1.500 ml/24h (Fresubin)","Mundpflege alle 2 Stunden","Schluckvideografie zur Prufung der oralen Kost"],"vocabularyFocus":["PEG-Sonde","Sondenkost","Schluckstörung","Mundpflege","Schlucktraining"],"tags":["B2","Pflege","PEG","Ernährung"]},{"id":"r76","title":"Reha-Empfehlung: Nach Bandscheiben-OP","type":"Rehabilitation recommendation","text":"REHA-EMPFEHLUNG\\n\\nPatient: Christian Wolter, 45 Jahre\\nDiagnose: Z.n. mikrochirurgischer Seqüstrektomie L4/L5 links\\nDatum: 24.06.2026\\n\\nSehr geehrte Reha-Klinik,\\n\\nHerr Wolter wurde am 15.06.2026 an der Lendenwirbelsäule wegen eines seqüstrierten Bandscheibenvorfalls L4/L5 links operiert.\\n\\nAktüller Zustand:\\n- Keine radikulären Schmerzen mehr\\n- Leichte Parasthesien im Dermatom L5 links\\n- Motorik: Kraftgrad M5 für den Quadrizeps, M4 für den Grosszehenheber links\\n- Mobilisation: freies Gehen auf Station, Treppensteigen mit Festhalten möglich\\n\\nIndikation: Anschlussheilbehandlung nach lumbaler Bandscheiben-OP.\\n\\nReha-Ziele:\\n1. Rückenstabilisation und Kräftigung der Rumpfmuskulatur\\n2. Haltungsschulung und Rückenschule\\n3. Berufliche Wiedereingliederung als Elektriker (He bearbeitung in Zwangshaltung)\\n4. Ergonomieberatung für den Arbeitsplatz\\n5. Schmerzbewältigung bei Restparasthesien\\n\\nBelastbarkeit: Kein schweres Heben (> 10 kg) für 6 Wochen.\\nKeine Wirbelsäulenrotation für 4 Wochen.\\n\\nEmpfohlene Dauer: 3 Wochen stationär.","questions":["Welche Operation wurde durchgeführt?","Welches Restgefühl besteht noch im linken Bein?","Welchen Beruf hat der Patient?","Wie lange darf der Patient keine schweren Lasten heben?"],"answers":["Mikrochirurgische Seqüstrektomie L4/L5 links","Leichte Parasthesien im Dermatom L5 links","Elektriker","6 Wochen (kein Heben über 10 kg)"],"vocabularyFocus":["Seqüstrektomie","Bandscheibenvorfall","Parasthesien","Rückenschule","berufliche Wiedereingliederung"],"tags":["B2","Reha","Wirbelsäule","Orthopädie"]},{"id":"r77","title":"Nachsorgebrief: Nierentransplantation","type":"Follow-up letter","text":"NACHSORGEBRIEF - NEPHROLOGISCHE AMBULANZ\\n\\nPatientin: Angelika Dressler, 52 Jahre\\nDiagnose: Z.n. Nierentransplantation (03.02.2026), Spender: Lebendspende (Ehemann)\\nGrunderkrankung: IgA-Nephropathie\\n\\nSehr geehrte Frau Kollegin, sehr geehrter Herr Kollege,\\n\\nwir haben Frau Dressler heute zur Routine-Nachsorge gesehen.\\n\\nAktüller Befund:\\n- Die Patientin fühlt sich gut, keine Absto ssungszeichen\\n- Blutdruck: 128/75 mmHg (unter Medikation)\\n- Keine Ödeme, ausreichende Urinausscheidung (1.800 ml/24h)\\n\\nLabor:\\n- Kreatinin: 1,2 mg/dl (stabil)\\n- eGFR: 52 ml/min (stabil, CKD Stadium 3)\\n- Tacrolimus-Talspiegel: 7,2 ng/ml (Zielbereich 5-10 ng/ml)\\n- Harnsaure: 6,8 mg/dl (leicht erhöht)\\n\\nMedikation:\\n- Tacrolimus 5 mg 1-0-1\\n- Mycophenolatmofetil 500 mg 1-0-1\\n- Prednisolon 5 mg 1-0-0\\n- Valsartan 80 mg 1-0-0\\n- Cotrimoxazol 3x wöchentlich zur PCP-Prophylaxe\\n\\nEmpfehlungen:\\n1. Nächste Kontrolle in 3 Monaten mit Spiegeln\\n2. Transplantatsonografie in 6 Monaten\\n3. Bei Fieber über 38,5 Grad oder reduziertem Urin sofort vorstellen\\n4. Impfungen auffrischen (inflünza, Pneumokokken, COVID-19)\\n5. Sonnenschutz wegen Immunsuppression","questions":["Welche Nierenerkrankung führte zur Transplantation?","Welcher Tacrolimus-Talspiegel wurde heute gemessen?","In welchem CKD-Stadium befindet sich die Patientin?","Welches Medikament dient der PCP-Prophylaxe?"],"answers":["IgA-Nephropathie","7,2 ng/ml (Zielbereich 5-10 ng/ml)","CKD Stadium 3 (eGFR 52 ml/min)","Cotrimoxazol 3x wöchentlich"],"vocabularyFocus":["Nierentransplantation","Immunsuppression","Tacrolimus","eGFR","PCP-Prophylaxe"],"tags":["B2","Nachsorge","Nierentransplantation","Nephrologie"]},{"id":"r78","title":"Aushang: FSME-Risikogebiete","type":"Public health notice","text":"GESUNDHEITSAMT FREIBURG\\n\\nINFORMATION: FSME - ZEKSCHUTZ IN RISIKOGEBIETEN\\n\\nStand: Mai 2026\\n\\nDie frühjahrliche Zeckensaison hat begonnen. In Baden-Württemberg sind weite Teile FSME-Risikogebiet.\\n\\nWas ist FSME?\\nDie Frühsommer-Meningönzephalitis (FSME) ist eine Virusinfektion, die durch Zeckenstich übertragen wird. Die Inkubationszeit beträgt 5-28 Tage.\\n\\nSymptome:\\n- Erstes Stadium: Fieber, Kopfschmerzen, Müdigkeit, Gliederschmerzen (3-7 Tage)\\n- Zweites Stadium: ca. 10 Prozent der Infizierten entwickeln eine Hirnhautentzündung (Meningitis) oder Gehirnentzündung (Enzephalitis) mit Lichtscheu, Nackensteifigkeit, neurologischen Ausfällen\\n\\nSchutzmassnahmen:\\n1. Impfung: Die STIKO empfiehlt die FSME-Impfung für alle Personen in Risikogebieten. Grundimmunisierung: 3 Impfungen (0, 1-3, 12 Monate). Auffrischung alle 5 Jahre.\\n2. Körperliche Schutzmassnahmen: Lange Kleidung, festes Schuhwerk, Zeckenschutzmittel auf Haut und Kleidung\\n3. Nach Aufenthalt im Freien: Gründliche Körperkontrolle, Zecke sofort entfernen\\n\\nWichtig: Es gibt keine spezifische antivirale Therapie gegen FSME. Die Behandlung erfolgt symptomatisch. Bei neurologischen Symptomen: sofortige Krankenhauseinweisung.","questions":["Welche Krankheit wird durch Zecken übertragen?","Wie lange ist die Inkubationszeit?","Wie viele Impfungen umfasst die Grundimmunisierung?","Wie oft muss die FSME-Impfung aufgefrischt werden?"],"answers":["FSME (Frühsommer-Meningönzephalitis)","5-28 Tage","3 Impfungen (0, 1-3, 12 Monate)","Alle 5 Jahre"],"vocabularyFocus":["FSME","Zecken","Impfung","Meningitis","Enzephalitis"],"tags":["B2","Öffentlichkeit","FSME","Impfung"]},{"id":"r79","title":"Vorbereitung: Langzeit-Blutdruckmessung","type":"Appointment instruction sheet","text":"VORBEREITUNG: 24-STUNDEN-BLUTDRUCKMESSUNG\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nbei Ihrem nächsten Termin in unserer Praxis wird eine 24-Stunden-Blutdruckmessung durchgeführt. Diese Untersuchung misst Ihren Blutdruck über einen ganzen Tag und eine Nacht und gibt wichtige Hinweise auf Ihre Blutdruckeinstellung.\\n\\nTermin: 28.06.2026 um 08:00 Uhr in der Kardiologischen Praxis Dr. Fink, Raum 204.\\nDauer: 24 Stunden bis 29.06.2026 um 08:00 Uhr.\\n\\nAblauf:\\n- Eine Mitarbeiterin legt Ihnen eine Blutdruckmanschette am Oberarm an\\n- Die Manschette ist mit einem Aufzeichnungsgerät verbunden, das Sie am Gürtel tragen\\n- Tagsüber (08:00-22:00 Uhr) misst das Gerät alle 30 Minuten\\n- Nachts (22:00-06:00 Uhr) misst es alle 60 Minuten\\n- Sie führen ein Tagebuch über Aktivitäten, Beschwerden und Schlafenszeiten\\n\\nVerhalten während der Messung:\\n- Bei jeder Messung: Arm ruhig halten und nicht bewegen\\n- Normalen Tätigkeiten nachgehen (keinen Sport)\\n- Duschen ist nicht möglich (Gerät nicht wasserdicht)\\n- Normal weiteressen und Medikamente wie gewohnt einnehmen\\n\\nRückgabe: Am nächsten Morgen um 08:00 Uhr geben Sie das Gerät in der Praxis ab.","questions":["In welchem Intervall misst das Gerät nachts?","Wann soll der Patient ein Tagebuch führen?","Was muss der Patient bei jeder Messung beachten?","Ist Duschen wärend der Messung erlaubt?"],"answers":["Alle 60 Minuten (22:00-06:00 Uhr)","Über Aktivitäten, Beschwerden und Schlafenszeiten","Den Arm ruhig halten und nicht bewegen","Nein, das Gerät ist nicht wasserdicht"],"vocabularyFocus":["Blutdruckmessung","Langzeitmessung","Manschette","Tagebuch","Hypertonie"],"tags":["B2","Termin","Blutdruck","Kardiologie"]},{"id":"r80","title":"Patientenbeschwerde: Nicht ernst genommen","type":"Patient complaint letter","text":"Betreff: Beschwerde - Symptome wurden nicht ernst genommen\\n\\nSehr geehrter Chefarzt der Notaufnahme,\\n\\nich möchte mich über die Behandlung meiner Mutter, Frau Helga Paul (73 Jahre), in Ihrer Notaufnahme am 20.06.2026 beschweren.\\n\\nMeine Mutter kam um 19:30 Uhr mit starken Oberbauchschmerzen, Übelkeit und Erbrechen in die Notaufnahme. Ich als Tochter habe sie begleitet. Wir haben an der Anmeldung ca. 2 Stunden gewartet. Als wir dann endlich in einem Untersuchungszimmer waren, wurde meine Mutter von einer Ärztin untersucht, die etwa 25 Jahre alt wirkte.\\n\\nNach einer kurzen körperlichen Untersuchung sagte die Ärztin, es sei vermutlich eine Magen-Darm-Grippe und gab meiner Mutter ein Mittel gegen Übelkeit. Als ich fragte, ob nicht ein Ultraschall oder Blutuntersuchung sinnvoll wäre, wurde ich abgewimmelt mit den Worten \\"Dafür ist hier keine Zeit, das ist eine Virusinfektion\\". Man entliess meine Mutter gegen 22:30 Uhr.\\n\\nZu Hause wurden die Schmerzen schlimmer. Um 01:30 Uhr fuhren wir erneut in die Notaufnahme. Diesmal wurde sofort ein Ultraschall gemacht. Diagnose: Akute Cholezystitis (Gallenblasenentzündung) mit Steinen. Meine Mutter wurde notoperiert.\\n\\nIch erwarte eine Stellungnahme, warum die erste Ärztin meine Mutter ohne ausreichende Diagnostik entlassen hat und warum meine Bedenken als Angehörige ignoriert wurden.\\n\\nMit freundlichen Grüssen\\nSarah Paul","questions":["Wie lange mussten die Patientin und ihre Tochter in der Notaufnahme warten?","Welche Diagnose stellte die erste Ärztin?","Welche Frage der Tochter wurde abgewimmelt?","Welche korrekte Diagnose wurde beim zweiten Besuch gestellt?"],"answers":["Ca. 2 Stunden","Eine Magen-Darm-Grippe (Virusinfektion)","Ob ein Ultraschall oder eine Blutuntersuchung sinnvoll wäre","Akute Cholezystitis (Gallenblasenentzündung) mit Steinen"],"vocabularyFocus":["Beschwerde","Notaufnahme","Diagnose","Cholezystitis","Patientensicherheit"],"tags":["B2","Beschwerde","Notaufnahme","Patientenrechte"]},{"id":"r100","title":"Patientenbeschwerde: Zu späte Diagnose einer Sepsis","type":"Patient complaint letter","text":"Betreff: Beschwerde über verzögerte Erkennung einer Sepsis\\n\\nSehr geehrte Klinikleitung,\\n\\nich möchte mich im Namen meines Vaters, Herrn Alfred König (81 Jahre), über die Behandlung auf Ihrer Station 4A im Juni 2026 beschweren.\\n\\nMein Vater wurde am 10.06.2026 mit Fieber, Verwirrtheit und einer Harnwegsinfektion in Ihre Notaufnahme eingeliefert. Er wurde auf Station 4A aufgenommen. Obwohl bereits bei Aufnahme ein erhöhtes CRP von 180 mg/l und eine Leukozytose von 16.000 vorlagen, wurde erst am 12.06.2026 eine Blutkultur abgenommen. Die Antibiotikatherapie wurde erst 8 Stunden nach Aufnahme begonnen.\\n\\nAm 13.06.2026 verschlechterte sich sein Zustand dramatisch. Der Blutdruck fiel auf 80/40 mmHg, er wurde tachykard und entwickelte Fieber bis 39,8 Grad. Die Blutkultur ergab Escherichia coli. Die Diagnose einer uroseptischen Sepsis wurde gestellt. Mein Vater musste für 4 Tage auf die Intensivstation verlegt werden.\\n\\nIch sehe folgende Versäumnisse:\\n1. Die Blutkultur wurde zu spät abgenommen\\n2. Die Antibiotikatherapie wurde nicht zeitgerecht begonnen\\n3. Die Kriterien für eine beginnende Sepsis wurden übersehen\\n\\nMein Vater hat sich inzwischen erholt, aber der Aufenthalt auf der Intensivstation wäre vermutlich vermeidbar gewesen. Ich erwarte eine Darstellung des Falls und eine Stellungnahme, wie die frühzeitige Erkennung einer Sepsis auf Ihrer Station ver bessert werden soll.\\n\\nMit freundlichen Grüssen\\nDr. Robert König (Sohn des Patienten)","questions":["Welche Infektion führte zur Sepsis?","Welches CRP lag bereits bei Aufnahme vor?","Wann wurde die Blutkultur abgenommen?","Wohin musste der Patient verlegt werden?"],"answers":["Eine Harnwegsinfektion mit Escherichia coli","180 mg/l","Erst am 12.06.2026 (2 Tage nach Aufnahme)","Auf die Intensivstation"],"vocabularyFocus":["Sepsis","Urosepsis","Blutkultur","CRP","Intensivstation"],"tags":["B2","Beschwerde","Sepsis","Patientensicherheit"]},{"id":"r81","title":"Arztbrief: Aufnahme mit hypertensiver Krise","type":"Arztbrief excerpt","text":"Arztbrief vom 20.06.2026\\n\\nPatient: Herr Rüdiger Brandt, 50 Jahre alt\\nDiagnose: Hypertensive Krise bei unzureichend eingestelltem Bluthochdruck\\n\\nAufnahmegrund: Der Patient wurde vom Rettungsdienst mit einem Blutdruck von 220/130 mmHg, starken Kopfschmerzen, Schwindel und Nasenbluten eingeliefert. Der Patient gibt an, in den letzten Wochen sein Blutdruckmittel nicht regelmässig eingenommen zu haben.\\n\\nVitalparameter bei Aufnahme:\\n- Blutdruck: 220/130 mmHg\\n- Puls: 98/min\\n- Temperatur: 36,8 Grad Celsius\\n\\nLabor:\\n- Kreatinin: 1,3 mg/dl (Norm < 1,2) leicht erhöht\\n- Troponin: normal\\n- Urinstatus: Proteinurie +\\n\\nTherapie: Der Patient erhielt Urapidil 25 mg i.v. als Bolus, danach kontinuierliche Gabe über Perfusor. Der Blutdruck konnte innerhalb von 4 Stunden auf 155/90 mmHg gesenkt werden.\\n\\nEmpfehlung: Einstellung auf eine fixe Kombination aus Candesartan 16 mg und Hydrochlorothiazid 12,5 mg. Blutdrucktagesprofil in 2 Wochen. Aufklärung über Therapietreü.","questions":["Welchen Blutdruck hatte der Patient bei der Aufnahme?","Welches Medikament wurde intravenös gegeben?","Warum ist der Blutdruck so stark angestiegen?","Welche Kombinationstherapie wird empfohlen?"],"answers":["220/130 mmHg","Urapidil 25 mg i.v. als Bolus","Weil der Patient sein Blutdruckmittel nicht regelmässig eingenommen hat","Candesartan 16 mg und Hydrochlorothiazid 12,5 mg"],"vocabularyFocus":["hypertensive Krise","Urapidil","Therapietreü","Candesartan","Perfusor"],"tags":["B2","Arztbrief","Hypertonie","Notfallmedizin"]},{"id":"r82","title":"Laborbericht: Nierenwerte bei akuter Nierenschädigung","type":"Lab report explanation","text":"Laborbefund vom 22.06.2026\\n\\nPatient: Frau Bianka Seidel, 68 Jahre alt\\nAuftrag: Abklärung einer akuten Nierenfunktionsverschlechterung\\n\\nKlinische Angabe: Z.n. grosser Hüft-OP vor 5 Tagen, jetzt verminderte Urinausscheidung (ca. 300 ml/24h), Beinödeme.\\n\\nErgebnisse:\\n- Kreatinin: 3,8 mg/dl (Norm 0,6-1,2 mg/dl) - stark erhöht\\n- Kreatinin vor OP (08.06.): 0,9 mg/dl - Normwert\\n- Harnstoff: 95 mg/dl (Norm 10-50 mg/dl) - erhöht\\n- eGFR: 14 ml/min (Norm > 90) - stark erniedrigt\\n- Kalium: 5,6 mmol/l (Norm 3,5-5,1 mmol/l) - erhöht\\n- Natrium: 135 mmol/l (Norm 135-145) - normwertig\\n- Harnsaure: 9,2 mg/dl (Norm < 6,0) - erhöht\\n\\nUrinstatus: spezifisches Gewicht 1.010, Erythrozyten +, Protein +\\n\\nBeurteilung: Akute Nierenschädigung (AKI Stadium 2 nach KDIGO) bei V.a. prärenale Genese durch perioperativen Volumenmangel und mögliche Nephrotoxizität von Kontrastmittel und NSAR. Empfehlung: Volumengabe, Kaliumkontrolle, Nephrologie-Konsil.","questions":["Welches Kreatinin hatte die Patientin vor der Operation?","Welche eGFR wurde gemessen?","Welcher Elektrolytwert ist erhöht und besorgniserregend?","Welches Stadium der akuten Nierenschädigung liegt vor?"],"answers":["0,9 mg/dl","14 ml/min","Kalium mit 5,6 mmol/l","AKI Stadium 2 nach KDIGO"],"vocabularyFocus":["akute Nierenschädigung","AKI","eGFR","prärenal","KDIGO"],"tags":["B2","Labor","Niere","Nephrologie"]},{"id":"r83","title":"Echo-Befund: Herzklappenerkrankung","type":"Imaging report excerpt","text":"ECHOKARDIOGRAFIE-BEFUND\\n\\nPatient: Herr Robert Henning, 76 Jahre\\nDatum: 24.06.2026\\nFragestellung: Belastungsdyspnö NYHA III, V.a. Aortenklappenstenose\\n\\nTechnik: Transthorakale Echokardiografie (TTE) mit 2D, M-Mode, Farbdoppler und CW-Doppler\\n\\nBefund:\\n- Linker Ventrikel: konzentrische Linksherzhypertrophie, Septum 15 mm, Hinterwand 13 mm\\n- LVEF: 58 Prozent (normal)\\n- Rechter Ventrikel: normal gross, normale Funktion\\n- Linker Vorhof: leicht dilatiert (LAVI 38 ml/m2)\\n\\nKlappen:\\n- Aortenklappe: hochgradig verkalkt, öffnungseingeschränkt\\n- Vmax: 4,5 m/s, mittlerer Gradient 48 mmHg, Klappenöffnungsfläche 0,8 cm2\\n- Mitralklappe: mittelgradige Insuffizienz\\n- Trikuspidalklappe: geringe Insuffizienz, systolischer Pulmonalisdruck 40 mmHg\\n\\nBeurteilung: Hochgradige Aortenklappenstenose (Klappenöffnungsfläche 0,8 cm2) mit konzentrischer Linksherzhypertrophie und mittelgradiger Mitralinsuffizienz. Indikation zur Aortenklappenimplantation (TAVI oder operativ) gegeben.","questions":["Welcher mittlere Gradient wurde über der Aortenklappe gemessen?","Welche LVEF hat der Patient?","Wie gross ist die Klappenöffnungsfläche der Aortenklappe?","Welche Therapieoption wird empfohlen?"],"answers":["48 mmHg","58 Prozent","0,8 cm2","Aortenklappenimplantation (TAVI oder operativ)"],"vocabularyFocus":["Aortenklappenstenose","Echokardiografie","Gradient","Klappenöffnungsfläche","TAVI"],"tags":["B2","Echo","Herzklappe","Kardiologie"]},{"id":"r84","title":"Packungsbeilage: ASS 100 mg","type":"Medication leaflet excerpt","text":"GEBRAUCHSINFORMATION: ASS 100 mg magensaftresistente Tabletten\\n\\nWirkstoff: Acetylsalicylsäure\\nAnwendungsgebiete: Zur Hemmung der Blutgerinnung. Vorbeugung von Herzinfarkt und Schlaganfall bei bestehenden Risikofaktoren. Nach Herzinfarkt oder Schlaganfall zur Rückfallprophylaxe.\\n\\nGegenanzeigen:\\n- Überempfindlichkeit gegen Salicylate\\n- Akute Magen-Darm-Geschwüre\\n- Hämorrhagische Diathese (Blutungsneigung)\\n- Schwere Leber- oder Niereninsuffizienz\\n- Letztes Drittel der Schwangerschaft\\n- Asthmaanfälle in der Vorgeschichte durch Salicylate\\n\\nDosierung:\\n- Erwachsene: 1 Tablette (100 mg) täglich, vorzugsweise nach dem Frühstück\\n- Die Tablette unzerkaut mit etwas Wasser einnehmen\\n\\nWechselwirkungen:\\n- Erhöhtes Blutungsrisiko bei gleichzeitiger Gabe von anderen Blutgerinnungshemmern\\n- Wirkungsverstärkung von Methotrexat, Lithium\\n- Verminderte Wirkung von Blutdrucksenkern\\n\\nNebenwirkungen:\\n- Häufig: Sodbrennen, Magendruck\\n- Gelegentlich: Magenblutungen (auch ohne Warnzeichen)\\n- Selten: allergische Reaktionen, Hautausschlag","questions":["Gegen welche Allergien darf ASS 100 nicht eingenommen werden?","Wie viele Tabletten soll der Patient täglich einnehmen?","Wann steigt das Blutungsrisiko besonders?","Welche häufige Nebenwirkung im Magen-Darm-Trakt tritt auf?"],"answers":["Überempfindlichkeit gegen Salicylate","1 Tablette (100 mg) täglich","Bei gleichzeitiger Gabe von anderen Blutgerinnungshemmern","Sodbrennen und Magendruck"],"vocabularyFocus":["Acetylsalicylsäure","Blutgerinnungshemmer","Rückfallprophylaxe","hämorrhagische Diathese","Wechselwirkungen"],"tags":["B2","Medikament","ASS","Thrombozytenaggregationshemmer"]},{"id":"r85","title":"Klinikrichtlinie: Umgang mit Sterbefällen","type":"Hospital policy","text":"KLINIKRICHTLINIE: UMGANG MIT STERBEFÄLLEN AUF DER STATION\\n\\nStand: April 2026\\n\\n1. Feststellung des Todes:\\nDer Tod wird von einem Arzt festgestellt. Der Arzt dokumentiert Todeszeitpunkt, Todesumstände und auffällige Befunde. Bei ungeklärter Todesursache oder aussergewöhnlichen Umständen wird die Polizei und die Staatsanwaltschaft informiert.\\n\\n2. Versorgung des Verstorbenen:\\n- Der Verstorbene wird gewaschen, angekleidet und in eine natürrliche Position gelegt\\n- Alle medizinischen Zugänge werden entfernt\\n- Die Identifikationsarmbänder bleiben am Handgelenk\\n- Der Verstorbene wird mit einem Laken bedeckt\\n\\n3. Information der Angehörigen:\\n- Die Angehörigen werden sofort durch den behandelnden Arzt informiert\\n- Das Gespräch findet in einem separaten Raum statt\\n- Den Angehörigen wird Zeit und Raum für die Verabschiedung gegeben\\n- Ein Seelsorger wird auf Wunsch hinzugezogen\\n\\n4. Formalitäten:\\n- Die Todesbescheinigung wird vom Arzt ausgefüllt (insgesamt 4 Durchschläge)\\n- Der Leichenschauschein wird an das Standesamt geschickt\\n- Die Verwaltung informiert den Bestatter nach Freigabe durch die Angehörigen\\n\\n5. Besonderheiten bei Organentnahme:\\n- Bei Hirntod und fehlendem Widerspruch wird die DSO (Deutsche Stiftung Organtransplantation) informiert","questions":["Was macht der Arzt bei einem Todesfall als erstes?","Was bleibt am Handgelenk des Verstorbenen?","In welcher Form findet das Gespräch mit den Angehörigen statt?","Welche Institution wird bei Hirntod kontaktiert?"],"answers":["Er stellt den Tod fest und dokumentiert die Umstände","Die Identifikationsarmbänder","In einem separaten Raum","Die Deutsche Stiftung Organtransplantation (DSO)"],"vocabularyFocus":["Todesfeststellung","Leichenschau","Todesbescheinigung","Hirntod","Organtransplantation"],"tags":["B2","Klinik","Richtlinie","Sterbefall"]},{"id":"r86","title":"Einwilligungserklärung: MRT mit Kontrastmittel","type":"Consent form","text":"Einwilligungserklärung für EINE MRT-UNTERSUCHUNG MIT KONTRASTMITTEL\\n\\nPatient: _________________ Datum: _________________\\n\\nAufklärender Arzt: Dr. med. Robert Fricke, Radiologie\\n\\nUntersuchung: Magnetresonanztomografie des Schädels mit gadoliniumhaltigem Kontrastmittel\\n\\nZweck der Untersuchung: Darstellung von Hirntumoren, Entzündungen oder Durchblutungsstörungen\\n\\nÜber das Kontrastmittel:\\n- Das Kontrastmittel enthält Gadolinium\\n- Es wird über eine Vene injiziert\\n- Wirkung: verstärkter Kontrast in bestimmten Geweben\\n\\nRisiken des Kontrastmittels:\\n- Häufig: Warmegefühl, metallischer Geschmack (vorübergehend)\\n- Selten: allergische Reaktion (Juckreiz, Hautausschlag, Übelkeit)\\n- Sehr selten: schwere allergische Reaktion (Atemnot, Blutdruckabfall) - Häufigkeit unter 0,01 Prozent\\n- Bei Niereninsuffizienz (GFR unter 30 ml/min): Risiko einer nephrogenen systemischen Fibrose (NSF)\\n\\nSicherheitsfragen vor der Untersuchung:\\n- Herzschrittmacher, Cochlea-Implantat, metallische Fremdkörper?\\n- Bekannte Allergien, Asthma?\\n- Eingeschränkte Nierenfunktion, Diabetes?\\n- Schwangerschaft oder Stillzeit?\\n\\nMir wurde erklärt, dass ich vor der Untersuchung einen Fragebogen zu Sicherheitsaspekten ausfülle.","questions":["Welches Organ wird mit der MRT untersucht?","Welche sehr seltene, aber schwere Reaktion auf das Kontrastmittel kann auftreten?","Bei welcher Nierenfunktion besteht ein Risiko für NSF?","Welche Fragen werden vor der MRT geklärt?"],"answers":["Das Gehirn (Schädel)","Schwere allergische Reaktion mit Atemnot und Blutdruckabfall","Bei GFR unter 30 ml/min","Nach Herzschrittmacher, Allergien, Nierenfunktion und Schwangerschaft"],"vocabularyFocus":["Gadolinium","nephrogene systemische Fibrose","Kontrastmittelallergie","MRT-Sicherheit","Schrittmacher"],"tags":["B2","Einwilligung","MRT","Radiologie"]},{"id":"r87","title":"Entlassungsbrief: Guillain-Barre-Syndrom","type":"Discharge summary","text":"ENTLASSUNGSBRIEF\\n\\nPatient: Felix Hofer, 38 Jahre\\nAufenthalt: 15.06.2026 bis 25.06.2026\\nDiagnose: Guillain-Barre-Syndrom (akute inflammatorische demyelinisierende Polyneuropathie)\\n\\nAnamnese: Der Patient wurde mit aufsteigender Muskelschwäche in beiden Beinen, Gefühlsstörungen in den Füssen und unsicherem Gang eingewiesen. Eine Woche zuvor hatte er einen Atemwegsinfekt mit Durchfall.\\n\\nDiagnostik:\\n- Nervenleitgeschwindigkeit: deutliche Verlängerung der distalen Latenz, verminderte Amplitude\\n- Liquor: Eiweisserhöhung auf 120 mg/dl bei normaler Zellzahl (zytoalbuminäre Dissoziation)\\n- MRT Wirbelsäule: unauffällig\\n\\nTherapie und Verlauf:\\n- Immunglobuline i.v. (2 g/kg Körpergewicht über 5 Tage)\\n- Der Patient konnte am 5. Tag wieder kurze Strecken mit einem Rollator gehen\\n- Die Kraft in den Armen blieb stets erhalten\\n- Keine respiratorische Insuffizienz\\n\\nMedikation bei Entlassung:\\n- Keine Daürmedikation\\n- Physiotherapie 3x wöchentlich ambulant\\n\\nEmpfehlungen: Neurologische Verlaufskontrolle in 4 Wochen, Ergotherapie, bei neürlicher Schwäche oder Schluckstörungen sofortige Vorstellung. Die Prognose ist bei früher Therapie günstig.","questions":["Welche Infektion ging dem Guillain-Barre-Syndrom voraus?","Welcher Laborwert im Liquor war typischerweise erhöht?","Mit welcher Therapie wurde der Patient behandelt?","War eine respiratorische Insuffizienz aufgetreten?"],"answers":["Ein Atemwegsinfekt mit Durchfall","Eiweisserhöhung auf 120 mg/dl bei normaler Zellzahl","Immunglobuline i.v. (2 g/kg über 5 Tage)","Nein, die Atemmuskulatur war nicht betroffen"],"vocabularyFocus":["Guillain-Barre-Syndrom","Polyneuropathie","Immunglobuline","zytoalbuminäre Dissoziation","Nervenleitgeschwindigkeit"],"tags":["B2","Entlassung","Guillain-Barre","Neurologie"]},{"id":"r88","title":"Überweisung: Pneumologie bei Lungenrundherd","type":"Referral letter","text":"Überweisung an das Lungenzentrum\\n\\nPatient: Dieter Mann, 62 Jahre\\n\\nSehr geehrter Herr Prof. Dr. Nüsser,\\n\\nich überweise Herrn Mann zur weiteren Abklärung eines Lungenrundherds im rechten Oberlappen.\\n\\nVorgeschichte:\\n- Nikotinanamnese: 45 Packungsjahre, seit 2 Jahren Nichtraucher\\n- Beruf: Früher Asbest- und Quarzstaubexposition (Schlosser)\\n- Chronischer Husten, seit 3 Monaten zunehmend\\n\\nBildgebung:\\n- Röntgen-Thorax: Runder, etwa 2,5 cm grosser Herd im rechten Oberlappen\\n- CT-Thorax (aktüll): 2,8 x 2,4 x 2,2 cm grosser, spikulierter Rundherd im Segment 3 rechts, leichte Kontrastmittelaufnahme. Keine Lymphknotenvergrösserung mediastinal. Kein Pleurärguss.\\n\\nAllgemeinzustand: Gut, keine Gewichtsabnahme, keine Hämoptysen.\\n\\nBitte führen Sie eine Bronchoskopie mit transbronchialer Biopsie oder eine CT-gesteürte Punktion durch. Ggf. PET-CT zur Stadienabklärung.\\n\\nMit freundlichen kollegialen Grüssen\\nDr. med. Friedhelm Reuter, Hausarzt","questions":["Welches Risikoverhalten hatte der Patient früher?","Wie gross ist der Rundherd im CT?","Welche Berufsanamnese ist auffällig?","Welche Untersuchung soll als nächstes durchgeführt werden?"],"answers":["Nikotin (45 Packungsjahre)","2,8 x 2,4 x 2,2 cm","Asbest- und Quarzstaubexposition als Schlosser","Bronchoskopie mit Biopsie oder CT-gesteürte Punktion"],"vocabularyFocus":["Lungenrundherd","spikuliert","Packungsjahre","PET-CT","Bronchoskopie"],"tags":["B2","Überweisung","Lunge","Pneumologie"]},{"id":"r89","title":"Merkblatt: Thromboseprophylaxe nach OP","type":"Patient information sheet","text":"MERKBLATT: THROMBOSEPROPHYLAXE NACH OPERATIONEN\\n\\nLiebe Patientin, lieber Patient,\\n\\nnach einer Operation haben Sie ein erhöhtes Risiko für eine Beinvenenthrombose. Deshalb erhalten Sie während Ihres Krankenhausaufenthalts Massnahmen zur Thromboseprophylaxe.\\n\\nWarum haben Sie ein erhöhtes Risiko?\\n- Die Bewegungseinschränkung nach der OP verlangsamt den Blutfluss\\n- Der Eingriff selbst aktiviert die Blutgerinnung\\n- Übergewicht, vorherige Thrombosen oder Krebserkrankungen erhöhen das Risiko zusätzlich\\n\\nMassnahmen:\\n1. Medikamentöse Prophylaxe:\\n- Injektion von niedermolekularem Heparin (z.B. Clexane 40 mg 1x täglich s.c.)\\n- Die Spritze wird in die Bauchhaut gegeben\\n- Dauer: mindestens bis zur vollständigen Mobilisation\\n\\n2. Physikalische Massnahmen:\\n- Fruhmobilisation (am Tag der OP aufstehen)\\n- Kompressionsströmpfe (tragen bis zum abendlichen Waschen)\\n- Fussgymnastik (mehrmals täglich Fuss kreisen und anziehen)\\n\\n3. Allgemeine Massnahmen:\\n- Ausreichend trinken (mindestens 1,5 Liter pro Tag)\\n- Beine hochlagern im Sitzen\\n- Enge Kleidung vermeiden\\n\\nWarnsignale:\\n- Schwellung, Schweregefühl oder Schmerzen in einem Bein\\n- Hitzegefühl oder rötliche Verfärbung\\n- Plötzliche Atemnot oder Brustschmerz (Hinweis auf Lungenembolie)\\n\\nBei diesen Warnsignalen: sofort Ärztin oder Pflegepersonal verständigen.","questions":["Welches Medikament wird zur Thromboseprophylaxe gespritzt?","Wie oft sollen die Fussübungen gemacht werden?","Wie viel soll der Patient täglich trinken?","Welches Warnsignal könnte auf eine Lungenembolie hinweisen?"],"answers":["Niedermolekulares Heparin (z.B. Clexane 40 mg)","Mehrmals täglich","Mindestens 1,5 Liter pro Tag","Plötzliche Atemnot oder Brustschmerz"],"vocabularyFocus":["Thromboseprophylaxe","niedermolekulares Heparin","Fruhmobilisation","Kompressionsströmpfe","Lungenembolie"],"tags":["B2","Patienteninfo","Thrombose","Chirurgie"]},{"id":"r90","title":"Krankenkasse: Widerspruch abgelehnt","type":"Insurance/admin document","text":"IKK classic\\nService-Center, 01097 Dresden\\n\\nWiderspruchsbescheid\\n\\nVersicherter: Max Wunderlich\\nMitgliedsnummer: 369258147\\nDatum: 25.06.2026\\n\\nBetreff: Ihr Widerspruch gegen die Ablehnung der Kostenübernahme für eine Liposuktion\\n\\nSehr geehrter Herr Wunderlich,\\n\\nSie haben am 10.05.2026 Widerspruch gegen unseren Bescheid vom 25.04.2026 eingelegt.\\n\\nWir haben Ihren Widerspruch erneut geprüft. Das Ergebnis:\\n\\nDer Widerspruch wird zurückgewiesen.\\n\\nBegründung:\\nNach Paragraf 27b SGB V ist eine Liposuktion zur Behandlung des Lipödems nur dann Kassenleistung, wenn folgende Voraussetzungen gemeinsam vorliegen:\\n- Gesicherte Diagnose Lipödem Stadium II oder III\\n- Erfolglose konservative Therapie über mindestens 6 Monate\\n- Dokumentierte ständige Schmerzen und Bewegungseinschränkung\\n\\nBei Ihnen liegt die Diagnose Lipödem Stadium I vor. Nach den aktüllen Leitlinien ist in diesem Stadium die konservative Therapie die Behandlung der Wahl. Die beantragte Liposuktion ist daher keine Leistung der gesetzlichen Krankenversicherung.\\n\\nRechtsbehelfsbelehrung:\\nGegen diesen Bescheid können Sie innerhalb eines Monats nach Bekanntgabe Klage beim Sozialgericht Dresden einlegen.\\n\\nDie Klage ist schriftlich oder zur Niederschrift des Urkundsbeamten der Geschäftsstelle einzureichen.","questions":["Welche Erkrankung wurde beim Patienten diagnostiziert?","Welches Stadium liegt nach Aktenlage vor?","Auf welcher Rechtsgrundlage beruht die Entscheidung?","Wo kann der Patient innerhalb eines Monats Klage einreichen?"],"answers":["Lipödem Stadium I","Stadium I","Paragraf 27b SGB V","Beim Sozialgericht Dresden"],"vocabularyFocus":["Widerspruch","Liposuktion","Lipödem","Rechtsbehelfsbelehrung","Sozialgericht"],"tags":["B2","Krankenkasse","Widerspruch","Versicherung"]},{"id":"r91","title":"Leitlinie: Diagnostik der tiefen Beinvenenthrombose","type":"Clinical guideline summary","text":"S2k-Leitlinie: Diagnostik der tiefen Beinvenenthrombose\\n\\nStand: 2026 (Auszug)\\n\\nVorgehen bei V.a. tiefe Beinvenenthrombose (TVT):\\n\\nSchritt 1: Klinische Wahrscheinlichkeit\\nAnwendung des Wells-Scores. Kriterien:\\n- Aktive Tumorerkrankung (+1 Punkt)\\n- Parese oder kürzliche Immobilisation (+1)\\n- Bettlagerigkeit > 3 Tage oder OP < 4 Wochen (+1)\\n- Schmerz an der tiefen Vene (+1)\\n- Schwellung des ganzen Beins (+1)\\n- Umfangsdifferenz > 3 cm (+1)\\n- Eindrückbares Ödem (+1)\\n- Kollateralvenen (+1)\\n- Alternative Diagnose ebenso wahrscheinlich (-2)\\n\\nAuswertung:\\n- Wells-Score > 2 = hohe Wahrscheinlichkeit\\n- Wells-Score <= 2 = geringe Wahrscheinlichkeit\\n\\nSchritt 2: D-Dimere (bei geringer Wahrscheinlichkeit)\\n- D-Dimere negativ (< 0,5 mg/l): TVT unwahrscheinlich\\n- D-Dimere positiv: Kompressionssonografie erforderlich\\n\\nSchritt 3: Kompressionssonografie (bei hoher Wahrscheinlichkeit oder positiven D-Dimeren)\\n- Kompressibilität der tiefen Beinvenen\\n- Fehlende Kompressibilität = Nachweis einer Thrombose\\n\\nTherapie: Bei gesicherter TVT sofort therapeutische Antikoagulation beginnen.","questions":["Welcher Score wird zur Bestimmung der klinischen Wahrscheinlichkeit verwendet?","Ab welcher Umfangsdifferenz wird ein Punkt im Wells-Score vergeben?","Wann kommt der D-Dimer-Test zum Einsatz?","Was zeigt die fehlende Kompressibilität in der Sonografie an?"],"answers":["Der Wells-Score","Über 3 cm","Bei geringer klinischer Wahrscheinlichkeit","Den Nachweis einer Thrombose"],"vocabularyFocus":["Wells-Score","Kompressionssonografie","D-Dimere","TVT","Immobilisation"],"tags":["B2","Leitlinie","Thrombose","Gefässmedizin"]},{"id":"r92","title":"Notaufnahmeprotokoll: Anaphylaktischer Schock","type":"Emergency department note","text":"NOTAUFNAHME - ärztlicher ERSTBERICHT\\n\\nDatum: 27.06.2026, 14:50 Uhr\\n\\nPatientin: Lena Kraft, 26 Jahre\\nEintreffart: Mit Rettungswagen, Notarzt\\n\\nVorstellungsgrund: Akute allergische Reaktion mit Atemnot nach Wespenstich in den rechten Unterarm.\\n\\nZeitlicher Verlauf:\\n- 14:15 Uhr: Wespenstich beim Picknick\\n- 14:20 Uhr: Beginnende Schwellung am Arm, Juckreiz am gesamten Körper\\n- 14:25 Uhr: Übelkeit, Schwindel, Atemnot, Hautrötung am gesamten Körper\\n- 14:30 Uhr: Eintreffen des Notarztes\\n\\nVitalparameter bei Eintreffen des Notarztes:\\n- Blutdruck: 85/50 mmHg\\n- Puls: 120/min, tachykard\\n- SpO2: 91 Prozent\\n\\nNotarztmassnahmen:\\n- Adrenalin 0,5 mg intramuskulär\\n- Volumen: 500 ml NaCl 0,9% als Bolus\\n- Prednisolon 250 mg i.v.\\n- Clemastin 2 mg i.v.\\n- Saürstoff 6 l/min über Maske\\n\\nBefund in der Notaufnahme (14:50 Uhr):\\n- Blutdruck: 100/60 mmHg\\n- Puls: 95/min\\n- SpO2: 97 Prozent unter 2 l Saürstoff\\n- Haut: Urtikaria rückläufig\\n- Lunge: vereinzelt Giemen\\n\\nDiagnose: Anaphylaktischer Schock Grad III nach Ring und Messmer (Kreislauf + Atmung + Haut) bei Wespenstichallergie.\\n\\nTherapie: Stationäre Überwachung für 24 Stunden. Notfallset und Allergiepass. Überweisung zur spezifischen Immuntherapie (Hyposensibilisierung).","questions":["Welches Insekt hat die Patientin gestochen?","Welcher Schockgrad liegt nach Ring und Messmer vor?","Welches Medikament wurde als erstes vom Notarzt gegeben?","Welche Langzeittherapie wird empfohlen?"],"answers":["Eine Wespe","Grad III (Kreislauf + Atmung + Haut)","Adrenalin 0,5 mg intramuskulär","Spezifische Immuntherapie (Hyposensibilisierung)"],"vocabularyFocus":["anaphylaktischer Schock","Urtikaria","Giemen","Hyposensibilisierung","Notfallset"],"tags":["B2","Notaufnahme","Allergie","Anaphylaxie"]},{"id":"r93","title":"Operationsbericht: Leistenbruch beidseits","type":"Operation report excerpt","text":"OPERATIONSBERICHT\\n\\nPatient: Tobias Specht, 52 Jahre\\nDatum: 29.06.2026\\nOperation: Beidseitige laparoskopische Leistenhernienversorgung (TAPP)\\n\\nPräoperative Diagnose: Leistenhernie rechts und links\\nPostoperative Diagnose: s.o.\\n\\nOperationsverlauf:\\nDie Operation erfolgte in Intubationsnarkose. Der Patient wurde in Rückenlage gelagert. Nach Desinfektion und steriler Abdeckung wurde ein Pneumoperitoneum mit 14 mmHg angelegt.\\n\\nEine 10 mm Optik-Trokarhülle wurde umbilikal eingebracht. Zwei 5 mm Arbeits-Trokare wurden lateral der Rektusscheiden platziert.\\n\\nRechtsseitig zeigte sich eine mediale Leistenhernie mit einem Bruchluck von ca. 2 cm. Der Bruchsack reponierte sich spontan. Das Peritoneum wurde von der Bauchwand abgelöst. Ein 12 x 15 cm grosses Polypropylemetz wurde eingelegt und mit Tacks fixiert. Danach wurde das Peritoneum mit Naht verschlossen.\\n\\nAuf der linken Seite fand sich eine laterale Leistenhernie mit einem Bruchluck von ca. 1,5 cm. Es erfolgte das gleiche Vorgehen mit Netzeinlage.\\n\\nBlutstillung: Sorgfältig, keine aktive Blutung\\nBlutverlust: unter 20 ml\\nOperationsdaür: 1 Stunde 10 Minuten\\nKomplikationen: Keine","questions":["Welche OP-Methode wurde gewählt?","Was wurde zur Verstärkung der Bauchwand eingelegt?","Welcher Zugang wurde für die Optik gewählt?","Wie lange dauerte die Operation?"],"answers":["TAPP (beidseitige laparoskopische Leistenhernienversorgung)","Ein Polypropylemetz","Umbilikal (10 mm Trokar)","1 Stunde 10 Minuten"],"vocabularyFocus":["TAPP","Leistenhernie","Pneumoperitoneum","Polypropylemetz","Trokar"],"tags":["B2","Operationsbericht","Leistenbruch","Chirurgie"]},{"id":"r94","title":"Visitennotiz: Alkoholentzugsdelir","type":"Ward round note","text":"STATIONSVISITE - 01.07.2026\\n\\nPatient: Johann Nestler, 55 Jahre, Zimmer 304\\nStation: 3C - Innere Medizin\\n\\nDiagnose: Alkoholentzugssyndrom mit Delir bei langjähriger Alkoholabhängigkeit\\n\\nAktüller Status Tag 3 der stationären Therapie:\\n- Aufnahmegrund: Der Patient wurde nach einem Krampfanfall mit anschliessendem verwirrten Zustand eingewiesen. Der Patient gibt täglichen Alkoholkonsum von ca. 200 g Alkohol an.\\n- Heute: Patient ist wach, zeitlich noch nicht voll orientiert, Tremor der Hände deutlich rückläufig\\n- Puls: 88/min, Blutdruck: 135/85 mmHg\\n- Schwitzen: nicht mehr kalt oder klam\\n\\nTherapie:\\n- Clomethiazol Ausschleichschema: heute 6 Kapseln (von initial 12)\\n- Vitamin B1 200 mg i.v. täglich (Prophylaxe Wernicke-Enzephalopathie)\\n- Multivitaminpräparat oral\\n- Physiotherapie und Beschäftigungstherapie seit gestern begonnen\\n\\nLabor:\\n- GGT: 220 U/l (erhöht)\\n- MCV: 104 fl (erhöht, makrozytär)\\n- Vitamin B12 180 pg/ml (niedrig, grenzwertig)\\n\\nPlan:\\n- Entlassung in 5-7 Tagen nach Abschluss des Ausschleichschemas\\n- Kontaktaufnahme mit Suchtberatungsstelle\\n- Sozialdienst für Reha-Massnahmen informieren","questions":["Welche akute Komplikation führte zur stationären Aufnahme?","Welches Medikament wird nach Ausschleichschema gegeben?","Welches Vitamin wird zur Wernicke-Prophylaxe gegeben?","Welcher Laborwert zeigt die chronische Alkoholbelastung an?"],"answers":["Ein Krampfanfall mit anschliessendem verwirrten Zustand","Clomethiazol","Vitamin B1 200 mg i.v. täglich","GGT mit 220 U/l"],"vocabularyFocus":["Alkoholentzug","Delir","Clomethiazol","Wernicke-Enzephalopathie","Suchtberatung"],"tags":["B2","Visite","Alkohol","Suchtmedizin"]},{"id":"r95","title":"Pflegeübergabe: Antikoagulation auf Station","type":"Nursing handover note","text":"Pflichtenübergabe - Frühschicht\\n\\nDatum: 02.07.2026, 06:30 Uhr\\n\\nPatient: Gerda Lüttgen, 74 Jahre, Zimmer 215\\nStation: 2B - Kardiologie\\n\\nDiagnose: Vorhofflimmern, Neüinstellung auf Phenprocoumon\\n\\nAktüller Zustand:\\n- Die Patientin ist wach und orientiert\\n- INR heute früh: 1,8 (Zielbereich 2,0 - 3,0)\\n- Keine Blutungszeichen, keine Hämaturie\\n- Blutdruck: 130/80 mmHg\\n\\nLetzte 24 Stunden:\\n- Phenprocoumon gestern 9 mg (nach INR-Schema)\\n- Enoxaparin 40 mg s.c. erneut gegeben (INR noch nicht therapeutisch)\\n- BZ-Kontrollen: normal (kein Diabetes)\\n- Stuhl: unauffällig (kein Teerstuhl)\\n\\nWichtige Hinweise:\\n- Patientin hat leichte Hämatome an beiden Unterarmen nach Blutabnahmen\\n- Bitte heute INR-Kontrolle um 18:00 Uhr\\n- Bei INR über 3,5: Phenprocoumon aussetzen und Arzt informieren\\n- Fallenlassen oder ungewöhnliche blaue Flecken dokumentieren\\n\\nAktülle Medikation:\\n- Phenprocoumon (nach INR-Schema)\\n- Bisoprolol 2,5 mg 1-0-0\\n- Pantoprazol 40 mg 1-0-0\\n\\nTermine:\\n- Heute 10:00 Uhr: Aufklärungsgespräch über INR-Selbstmessung","questions":["Welche INR wurde heute früh gemessen?","Welcher INR-Wert ist therapeutisch angestrebt?","Welches Medikament wird noch täglich gespritzt, bis die INR therapeutisch ist?","Ab welchem INR-Wert soll das Phenprocoumon ausgesetzt werden?"],"answers":["1,8","2,0 bis 3,0","Enoxaparin 40 mg s.c.","Über 3,5"],"vocabularyFocus":["INR","Phenprocoumon","Enoxaparin","Bridging","Hämatome"],"tags":["B2","Pflege","Antikoagulation","Kardiologie"]},{"id":"r96","title":"Reha-Empfehlung: Nach Schlaganfall","type":"Rehabilitation recommendation","text":"REHA-EMPFEHLUNG\\n\\nPatientin: Waltraud Schulz, 68 Jahre\\nDiagnose: Z.n. ischämischem Schlaganfall im Media-Teilgebiet rechts mit linksseitiger Hemiparese\\nDatum: 03.07.2026\\n\\nSehr geehrte Reha-Klinik,\\n\\nFrau Schulz erlitt am 15.06.2026 einen Media-Infarkt rechts. Eine Thrombolyse wurde durchgeführt, jedoch mit unvollständiger Rückbildung der Symptome.\\n\\nAktüller Zustand:\\n- Linksseitige Hemiparese: Arm Kraftgrad M3, Bein Kraftgrad M4\\n- Keine Aphasie (Sprachzentrum nicht betroffen)\\n- Schluckstörung: weiche Kost mit angepasster Konsistenz möglich, keine Sondenkost\\n- Alltag: Benötigt Hilfe bei Körperpflege und Anziehen\\n- Depression: Patientin ist niedergeschlagen, psychologische Mitbetreuung erforderlich\\n\\nBildgebung: MRT-Schädel zeigt grossen kortikalen Media-Infarkt rechts.\\n\\nReha-Ziele:\\n1. Verbesserung der Feinmotorik der linken Hand\\n2. Sicheres Gehen mit Hilfsmittel (Hausstrecke)\\n3. Selbstständigkeit bei der Körperpflege\\n4. Logopädisches Schlucktraining fortsetzen\\n5. Psychologische Begleitung der Erkrankungsverarbeitung\\n\\nBegleiterkrankungen: Hypertonie, Diabetes Typ 2.\\n\\nEmpfohlene Dauer: 4 Wochen stationär, ggf. Verlängerung auf 6 Wochen.","questions":["Welche Seite des Körpers ist von der Parese betroffen?","Welchen Kraftgrad hat der linke Arm?","Welche Komplikation besteht beim Schlucken?","Welche psychische Begleiterscheinung wird beschrieben?"],"answers":["Die linke Seite","M3","Schluckstörung, weiche Kost mit angepasster Konsistenz","Depression, Niedergeschlagenheit"],"vocabularyFocus":["Hemiparese","Media-Infarkt","Thrombolyse","Schlucktraining","Erkrankungsverarbeitung"],"tags":["B2","Reha","Schlaganfall","Neurologie"]},{"id":"r97","title":"Nachsorgebrief: Nach ESWL bei Nierensteinen","type":"Follow-up letter","text":"NACHSORGEBRIEF - UROLOGISCHE PRAXIS DR. STUMPF\\n\\nPatient: Lars Gebhardt, 44 Jahre\\nDiagnose: Z.n. ESWL (extrakorporale Stosswellenlithotripsie) Nierenstein linke Niere\\nDatum: 04.07.2026\\n\\nSehr geehrter Herr Kollege,\\n\\nwir haben Herrn Gebhardt heute 14 Tage nach der ESWL zur Verlaufskontrolle gesehen.\\n\\nAktüller Befund:\\n- Der Patient ist beschwerdefrei, keine Koliken mehr\\n- Keine Makrohämaturie mehr (mikroskopisch keine Erythrozyten mehr im Urin)\\n- Blutdruck: 125/80 mmHg\\n\\nBildgebung: Sonografie der Nieren zeigt Steinfragmente bis maximal 3 mm im unteren Kelch der linken Niere, kein Harnstau.\\n\\nSteinanalyse: Kalziumoxalat-Monohydrat (Weddellit).\\n\\nEmpfehlungen:\\n1. Nächste Kontrolle in 4 Wochen mit Sonografie und Urinstatus\\n2. Ausreichende Trinkmenge: mindestens 2,5-3 Liter pro Tag\\n3. Kochsalzarme Kost (maximal 5 g Salz pro Tag)\\n4. Kein übermässiger Konsum von oxalathaltigen Lebensmitteln (Spinat, Rhabarber, Schokolade, Nüsse)\\n5. Bei erneuten Schmerzen oder Fieber sofort vorstellen\\n6. Metabolische Abklärung (24h-Sammelurin) in 3 Monaten\\n\\nFalls es zu keinem vollständigen Abgang in 4 Wochen kommt, ist eine Ureterorenoskopie (URS) zu diskutieren.","questions":["Welche Behandlung wurde zur Zertrümmerung des Steins durchgeführt?","Welche Steinfragmente sind noch nachweisbar?","Aus welchem Material bestand der Stein?","Wie viel soll der Patient täglich trinken?"],"answers":["ESWL (extrakorporale Stosswellenlithotripsie)","Fragmente bis 3 mm im unteren Kelch","Kalziumoxalat-Monohydrat (Weddellit)","Mindestens 2,5 bis 3 Liter pro Tag"],"vocabularyFocus":["ESWL","Steinanalyse","Kalziumoxalat","Makrohämaturie","Ureterorenoskopie"],"tags":["B2","Nachsorge","Nierenstein","Urologie"]},{"id":"r98","title":"Öffentlicher Aushang: HIV-Testwoche","type":"Public health notice","text":"GESUNDHEITSAMT HAMBURG - PRESSEMITTEILUNG\\n\\nHIV-TESTWOCHE 2026: ICH LASS MICH TESTEN\\n\\nVom 15. bis 22. Juli 2026 findet in Hamburg die diesjährige HIV-Testwoche statt. Ziel der Aktion ist es, die Testbereitschaft zu erhöhen und die Zahl der unerkannten HIV-Infektionen zu senken.\\n\\nWarum testen lassen?\\n- In Deutschland leben schätzungsweise rund 90.800 Menschen mit HIV\\n- Etwa 8.600 wissen nichts von ihrer Infektion (Dunkelziffer)\\n- Eine frühzeitig erkannte HIV-Infektion ist heute gut behandelbar\\n- Die Lebenserwartung bei früher Therapie entspricht nahezu der Normalbevölkerung\\n\\nWer sollte sich testen lassen?\\n- Nach ungeschütztem Geschlechtsverkehr mit unbekanntem Partner\\n- Nach Kondomunfall oder Vergewaltigung\\n- Bei wiederholten fieberhaften Infekten, unklärem Gewichtsverlust, Durchfällen\\n- Bei geplanter Schwangerschaft\\n\\nWo kann man sich testen lassen?\\n- Bei Hausärzten (kassenfinanziert bei Verdacht)\\n- Gesundheitsamt Hamburg (anonym und kostenlos)\\n- Aidshilfe Hamburg (anonym, Kosten nach Selbsteinschätzung)\\n\\nMöglichkeiten der HIV-Postexpositionsprophylaxe (PEP):\\nNach einem Risikokontakt kann innerhalb von 48 Stunden eine PEP mit antiviralen Medikamenten die Infektion verhindern. Wenden Sie sich an die Notaufnahme eines Krankenhauses oder die nächste Aidshilfe.","questions":["Wie viele Menschen leben schätzungsweise mit HIV in Deutschland?","Wie viele wissen nichts von ihrer Infektion?","Wo kann man sich anonym testen lassen?","Innerhalb welcher Zeit ist eine HIV-Postexpositionsprophylaxe wirksam?"],"answers":["Rund 90.800","Etwa 8.600","Beim Gesundheitsamt or Aidshilfe","Innerhalb von 48 Stunden"],"vocabularyFocus":["HIV","Testkampagne","Dunkelziffer","PEP","anonym"],"tags":["B2","Öffentlichkeit","HIV","Präv ention"]},{"id":"r99","title":"Terminvorbereitung: Oraler Glukosetoleranztest","type":"Appointment instruction sheet","text":"VORBEREITUNG: ORALER GLUKOSETOLERANZTEST (oGTT)\\n\\nSehr geehrte Patientin, sehr geehrter Patient,\\n\\nbei Ihnen wurde ein oraler Glukosetoleranztest zur Abklärung eines Diabetes mellitus oder einer gestörten Glukosetoleranz verordnet.\\n\\nTermin: 07.07.2026 um 08:00 Uhr im Labor, Raum 001.\\n\\nWichtige Vorbereitung:\\n- Drei Tage vor dem Test: Normale Kohlenhydratzufuhr (mindestens 150 g Kohlenhydrate pro Tag)\\n- Keine strenge Diät vor dem Test\\n- Am Vorabend ab 22:00 Uhr: Nüchtern bleiben (nichts essen, nichts trinken ausser Wasser)\\n- Am Morgen des Tests: Nicht rauchen, keinen Kaffee oder Tee trinken\\n- Medikamente wie gewohnt einnehmen (ausser blutzuckersenkende Medikamente - bitte mit Arzt absprechen)\\n\\nAblauf:\\n1. Blutabnahme nüchtern (Blutzucker nuchtern)\\n2. Dann trinken Sie 300 ml einer Zuckerlösung (75 g Glukose) innerhalb von 5 Minuten\\n3. Nach 60 und 120 Minuten wird erneut Blut abgenommen\\n4. Sie bleiben wärend der gesamten Testdaür in der Praxis\\n\\nDauer: ca. 2,5 Stunden.\\n\\nBitte mitbringen: Versichertenkarte, etwas zu lesen, beqüme Kleidung.\\n\\nNach dem Test: Sie dürfen sofort wieder normal essen und trinken.","questions":["Wie viele Tage vor dem Test soll normal gegessen werden?","Ab wann müssen Sie nüchtern bleiben?","Was trinken Sie zu Beginn des eigentlichen Tests?","Wie oft wird nach dem Trinken Blut abgenommen?"],"answers":["Drei Tage vor dem Test","Ab 22:00 Uhr am Vorabend","300 ml einer Zuckerlösung mit 75 g Glukose","Nach 60 und 120 Minuten"],"vocabularyFocus":["Glukosetoleranztest","oGTT","nüchtern","Glukose","Kohlenhydrate"],"tags":["B2","Termin","Diabetes","Stoffwechsel"]}]`);export{e as default};